$vhds = @(
    @{ Path = "D:\DVDc\New Folder (2)\vxdev.vhdx"; Letter = "Q" },  # dev drive
    @{ Path = "D:\DVDc\VDc\D.vhdx";               Letter = "W" }   # D.vhdx drive
)

foreach ($v in $vhds) {
    if (Test-Path $v.Path) {

        # If not attached yet, mount it
        $img = Get-DiskImage -ImagePath $v.Path -ErrorAction SilentlyContinue
        if (-not $img -or -not $img.Attached) {
            $img = Mount-DiskImage -ImagePath $v.Path -PassThru
        }

        # Get the first partition and force the drive letter
        $disk = $img | Get-Disk
        $part = $disk | Get-Partition | Select-Object -First 1
        $part | Set-Partition -NewDriveLetter $v.Letter -ErrorAction SilentlyContinue
    }
}
