// context/strategyMemoryLoader.js
// ─────────────────────────────────────────────────────────────
// Loads strategy_memory.json and injects it as context into
// any AI agent call. Also logs session decisions back to the file.
// ─────────────────────────────────────────────────────────────

const fs = require('fs');
const path = require('path');

const MEMORY_PATH = path.join(__dirname, 'strategy_memory.json');

// ── Load memory from disk ──────────────────────────────────────
function loadMemory() {
  try {
    if (!fs.existsSync(MEMORY_PATH)) {
      console.warn('⚠️  strategy_memory.json not found. Creating default...');
      const defaultMemory = { version: '1.0.0', core_rules: [], session_log: [] };
      fs.writeFileSync(MEMORY_PATH, JSON.stringify(defaultMemory, null, 2));
      return defaultMemory;
    }
    const raw = fs.readFileSync(MEMORY_PATH, 'utf8');
    const memory = JSON.parse(raw);
    console.log(`✅ Strategy memory loaded (v${memory.version}) — ${memory.session_log.length} past sessions`);
    return memory;
  } catch (err) {
    console.error('❌ Failed to load strategy_memory.json:', err.message);
    throw err;
  }
}

// ── Build a system prompt string from memory ──────────────────
function buildSystemPrompt(memory, agentRole = 'hermes') {
  const role = memory.agent_roles?.[agentRole] || 'AI trading agent';
  const rules = (memory.core_rules || []).map((r, i) => `${i + 1}. ${r}`).join('\n');
  const tokens = (memory.token_universe || []).join(', ');
  const riskParams = memory.risk_parameters || {};
  const regime = memory.current_regime || 'unknown';

  // Pull last 5 session outcomes for context
  const recentSessions = (memory.session_log || [])
    .slice(-5)
    .map(s => `  [${s.date}] ${s.token} — ${s.action} — ${s.outcome} (confidence: ${s.confidence})`)
    .join('\n') || '  No sessions logged yet.';

  return `
You are the ${agentRole.toUpperCase()} agent in a multi-AI trading system.
Your role: ${role}

=== CORE TRADING RULES ===
${rules}

=== TOKEN UNIVERSE ===
${tokens}

=== RISK PARAMETERS ===
- Max position size: ${riskParams.max_position_size_pct * 100}%
- Max daily drawdown: ${riskParams.max_daily_drawdown_pct * 100}%
- Stop loss: ${riskParams.default_stop_loss_pct * 100}%
- Take profit: ${riskParams.default_take_profit_pct * 100}%
- Capital: £${riskParams.capital_gbp}
- Mode: ${memory.environment?.default_mode?.toUpperCase() || 'PAPER'}

=== CURRENT MARKET REGIME ===
${regime}

=== RECENT SESSION HISTORY ===
${recentSessions}

Always respond with valid JSON only: { signal, confidence, reason, constraints, approved }
`.trim();
}

// ── Log a trade decision to session_log ───────────────────────
function logSessionDecision(decision) {
  try {
    const memory = loadMemory();

    const entry = {
      date: new Date().toISOString(),
      token: decision.token || 'UNKNOWN',
      action: decision.signal || 'HOLD',
      confidence: decision.confidence || 0,
      outcome: decision.outcome || 'pending',
      approved: decision.approved || false,
      reason: decision.reason || '',
      agents_agreed: decision.consensus_count || 0,
    };

    memory.session_log.push(entry);
    memory.last_updated = new Date().toISOString().split('T')[0];

    // Keep only last 200 entries to avoid file bloat
    if (memory.session_log.length > 200) {
      memory.session_log = memory.session_log.slice(-200);
    }

    fs.writeFileSync(MEMORY_PATH, JSON.stringify(memory, null, 2));
    console.log(`📝 Session logged: ${entry.token} → ${entry.action} (approved: ${entry.approved})`);
  } catch (err) {
    console.error('❌ Failed to log session decision:', err.message);
  }
}

// ── Update current market regime ──────────────────────────────
function updateRegime(regime) {
  try {
    const memory = loadMemory();
    memory.current_regime = regime;
    memory.last_updated = new Date().toISOString().split('T')[0];
    fs.writeFileSync(MEMORY_PATH, JSON.stringify(memory, null, 2));
    console.log(`🔄 Market regime updated: ${regime}`);
  } catch (err) {
    console.error('❌ Failed to update regime:', err.message);
  }
}

// ── Get win rate from session log ─────────────────────────────
function getWinRate() {
  const memory = loadMemory();
  const completed = memory.session_log.filter(s => s.outcome !== 'pending');
  if (completed.length === 0) return { win_rate: null, sample_size: 0 };

  const wins = completed.filter(s => s.outcome === 'win').length;
  return {
    win_rate: ((wins / completed.length) * 100).toFixed(1) + '%',
    sample_size: completed.length,
    wins,
    losses: completed.length - wins,
  };
}

module.exports = {
  loadMemory,
  buildSystemPrompt,
  logSessionDecision,
  updateRegime,
  getWinRate,
};

