// agents/hermesAgent.js
// ─────────────────────────────────────────────────────────────
// Hermes 3 running locally via Ollama
// Acts as the final consensus validator across all AI agents
// ─────────────────────────────────────────────────────────────

const axios = require('axios');
const { loadMemory, buildSystemPrompt } = require('../context/strategyMemoryLoader');

const OLLAMA_URL = 'http://localhost:11434/api/chat';
const HERMES_MODEL = 'hermes3'; // or 'nous-hermes2' — see README

// ── Check Ollama is running ────────────────────────────────────
async function checkOllamaHealth() {
  try {
    const res = await axios.get('http://localhost:11434/api/tags', { timeout: 3000 });
    const models = res.data.models?.map(m => m.name) || [];
    const hermesAvailable = models.some(m => m.includes('hermes'));
    if (!hermesAvailable) {
      console.warn('⚠️  Hermes model not found in Ollama. Run: ollama pull hermes3');
    }
    return { running: true, models, hermesAvailable };
  } catch {
    console.error('❌ Ollama not running. Start it with: ollama serve');
    return { running: false, models: [], hermesAvailable: false };
  }
}

// ── Main consensus function ────────────────────────────────────
async function hermesConsensusCheck(agentSignals, token = 'UNKNOWN') {
  // Health check first
  const health = await checkOllamaHealth();
  if (!health.running || !health.hermesAvailable) {
    return {
      signal: 'HOLD',
      confidence: 0,
      consensus_count: 0,
      reason: 'Hermes unavailable — defaulting to HOLD',
      constraints: {},
      approved: false,
      error: 'Ollama not running or Hermes model missing',
    };
  }

  // Load memory and build system prompt
  const memory = loadMemory();
  const systemPrompt = buildSystemPrompt(memory, 'hermes');

  // Build the user message
  const userMessage = `
Evaluate the following AI agent signals for token: ${token}

${JSON.stringify(agentSignals, null, 2)}

Count how many agents agree on BUY vs SELL vs HOLD.
Apply the core rules from your system prompt.
Return ONLY valid JSON — no explanation, no markdown:

{
  "signal": "BUY" | "SELL" | "HOLD",
  "confidence": 0.0 to 1.0,
  "consensus_count": number,
  "reason": "one sentence",
  "constraints": {
    "max_position_size": 0.05,
    "stop_loss": 0.02,
    "take_profit": 0.04
  },
  "approved": true | false
}
`;

  try {
    console.log(`\n🔮 Hermes evaluating signals for ${token}...`);

    const response = await axios.post(
      OLLAMA_URL,
      {
        model: HERMES_MODEL,
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: userMessage },
        ],
        stream: false,
        options: {
          temperature: 0.1,    // Low temp for consistent structured output
          num_predict: 400,
        },
      },
      { timeout: 30000 }
    );

    const raw = response.data.message?.content || '';
    console.log('📨 Hermes raw response:', raw.substring(0, 200));

    // Clean and parse JSON
    const clean = raw.replace(/```json|```/g, '').trim();
    const result = JSON.parse(clean);

    // Safety gate — enforce core rules
    if (result.consensus_count < 3) {
      result.approved = false;
      result.reason += ' [BLOCKED: fewer than 3 agents in consensus]';
    }
    if (result.confidence < 0.65) {
      result.approved = false;
      result.reason += ' [BLOCKED: confidence below 0.65 threshold]';
    }

    console.log(`✅ Hermes verdict: ${result.signal} | confidence: ${result.confidence} | approved: ${result.approved}`);
    return result;

  } catch (err) {
    console.error('❌ Hermes agent error:', err.message);
    return {
      signal: 'HOLD',
      confidence: 0,
      consensus_count: 0,
      reason: `Hermes error: ${err.message}`,
      constraints: {},
      approved: false,
    };
  }
}

// ── Quick test function ────────────────────────────────────────
async function testHermes() {
  console.log('\n🧪 Running Hermes test...\n');

  const mockSignals = {
    claude:     { signal: 'BUY',  confidence: 0.78, reason: 'Bull regime detected' },
    gpt4o:      { signal: 'BUY',  confidence: 0.72, reason: 'Positive macro sentiment' },
    gemini:     { signal: 'BUY',  confidence: 0.69, reason: 'Breakout pattern confirmed' },
    grok:       { signal: 'HOLD', confidence: 0.55, reason: 'Mixed social signals' },
    perplexity: { signal: 'BUY',  confidence: 0.71, reason: 'No negative news found' },
  };

  const result = await hermesConsensusCheck(mockSignals, 'BTC');
  console.log('\n📊 Final Hermes Result:');
  console.log(JSON.stringify(result, null, 2));
}

module.exports = { hermesConsensusCheck, checkOllamaHealth, testHermes };

