  const [pulseAgent, setPulseAgent] = useState(0);
  const tradeIdRef = useRef(20);

  // Simulate live data
  useEffect(() => {
    if(!running) return;
    const interval = setInterval(() => {
      setBtcPrice(p => p + (Math.random()-0.45)*120);
      setSentiment(s => Math.max(0,Math.min(100,s+(Math.random()-0.48)*3)));
      setDailyPnL(p => p + (Math.random()-0.35)*0.000025);
      setTotalROI(r => r + (Math.random()-0.35)*0.01);
      setPulseAgent(Math.floor(Math.random()*AGENTS.length));
