      if(Math.random()>0.7) {
        setTrades(prev => [mkTrade(tradeIdRef.current++), ...prev].slice(0,20));
      }
      // Tick countdown
      setCountdown(lseCountdown());
    }, 1500);
    return () => clearInterval(interval);
  }, [running]);

  const toggleStrategy = useCallback(id => {
    setStrategies(prev => prev.map(s => s.id===id?{...s,active:!s.active}:s));
  }, []);

  const stopAll = () => {
    setRunning(false);
    setStrategies(prev => prev.map(s=>({...s,active:false})));
  };

  const runAIAnalysis = async () => {
    setAiLoading(true);
    setAiAnalysis('');
    try {
      const activeStrats = strategies.filter(s=>s.active).map(s=>s.name).join(', ');
      const res = await fetch('https://api.anthropic.com/v1/messages',{
        method:'POST',
        headers:{'Content-Type':'application/json'},
        body:JSON.stringify({
          model:'claude-sonnet-4-20250514',
          max_tokens:600,
          system:`You are a crypto market sentiment analyst AI agent. Return ONLY valid JSON: {"score":number,"regime":string,"analysis":string,"recommendation":string,"confidence":number}. No markdown, no code blocks.`,
          messages:[{role:'user',content:`Analyse crypto market:
BTC Price: $${btcPrice.toFixed(0)}
24h P&L: ${fBTC(dailyPnL)}
Sentiment input: ${sentiment}
Active strategies: ${activeStrats}
Total ROI: ${totalROI.toFixed(1)}%
LSE close in: ${countdown}

Return sentiment score 0-100, market regime, brief analysis (2 sentences), trading recommendation, confidence %.`}]
        })
      });
      const d = await res.json();
      const txt = d.content.find(b=>b.type==='text')?.text||'{}';
      const parsed = JSON.parse(txt.replace(/```json?|```/g,'').trim());
      setSentiment(parsed.score||sentiment);
      setRegime((parsed.regime||regime).toUpperCase());
      setAiAnalysis(parsed.analysis||'');
      setAiRec(parsed.recommendation||'');
    } catch(e) {
      setAiAnalysis('Analysis failed — check API key in .env and network connection.');
    }
    setAiLoading(false);
  };

  const totalPortfolioUSD = portfolioBTC * btcPrice;
  const activeCount = strategies.filter(s=>s.active).length;
  const totalStratPnL = strategies.reduce((a,s)=>a+s.pnl, 0);
  const distribCrypto = dailyPnL * 0.6;
  const distribCompound = dailyPnL * 0.4;
  const profitableTrades = trades.filter(t=>t.pnl>0).length;
  const tradeAccuracy = trades.length > 0 ? Math.round((profitableTrades/trades.length)*100) : 0;

