                    <td style={{padding:'5px 6px'}}><span style={{padding:'2px 6px',borderRadius:'4px',background:t.closed?'#00F5A010':'#F59E0B10',color:t.closed?'#00F5A0':'#F59E0B',fontSize:'8px',letterSpacing:'1px'}}>{t.closed?'CLOSED':'OPEN'}</span></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Data Sources */}
        <div style={{background:'#0B1220',border:'1px solid #162030',borderRadius:'10px',padding:'16px'}}>
          <div style={{color:'#374151',fontSize:'9px',letterSpacing:'2px',marginBottom:'12px'}}>DATA SOURCES</div>
          <div style={{display:'flex',flexDirection:'column',gap:'8px'}}>
            {DATA_SOURCES.map(src=>(
              <div key={src.name} style={{display:'flex',alignItems:'center',gap:'8px',padding:'8px',background:'#060A14',borderRadius:'6px',border:'1px solid #162030'}}>
                <div style={{width:'6px',height:'6px',borderRadius:'50%',background:src.color,boxShadow:`0 0 8px ${src.color}`,flexShrink:0,animation:'pulse 2s infinite'}}/>
