          <div style={{display:'flex',gap:'12px',marginBottom:'16px'}}>
            <div style={{flex:1,padding:'14px',background:'#003CFF10',border:'1px solid #003CFF40',borderRadius:'8px'}}>
              <div style={{color:'#374151',fontSize:'8px',letterSpacing:'1.5px',marginBottom:'6px'}}>60% → CRYPTO.COM</div>
