        method:"POST",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify({
          model:"claude-sonnet-4-20250514",
          max_tokens:500,
          system:`You are a professional crypto trading sentiment analyst AI agent embedded in a multi-agent trading system.
Return ONLY valid JSON — no markdown, no code blocks, no commentary:
{"score":number,"regime":string,"analysis":string,"recommendation":string}
score: 0-100 (100=extreme greed). regime: one of TRENDING BULL/RANGING/TRENDING BEAR/VOLATILE/ACCUMULATION. analysis: 2 concise sentences. recommendation: one action sentence.`,
          messages:[{role:"user",content:`Market snapshot:
BTC price: $${btcPrice.toLocaleString("en-US")}
Current sentiment input: ${sentiment}/100
Daily P&L: ${fBTC(dailyPnL)}
Total ROI: ${totalROI.toFixed(1)}%
Active strategies: ${active}
LSE closes in: ${lse}
Session: London/Edinburgh
Portfolio size: ${portfolioBTC.toFixed(5)} BTC

Analyse sentiment and provide trading guidance.`}]
        })
      });
      const d   = await res.json();
      const txt = d.content?.find(b=>b.type==="text")?.text || "{}";
      const p   = JSON.parse(txt.replace(/```json?|```/g,"").trim());
      if(typeof p.score==="number") setSentiment(Math.round(p.score));
      if(p.regime)         setRegime(p.regime.toUpperCase());
      if(p.analysis)       setAiText(p.analysis);
      if(p.recommendation) setAiRec(p.recommendation);
    } catch(e) {
      setAiText("Analysis failed — check ANTHROPIC_API_KEY in your .env file at C:\\Users\\barcl\\projects\\AiTradingagent\\.env");
    }
    setAiLoading(false);
  };

  // Derived values
  const activeCount = strats.filter(s=>s.active).length;
  const profTrades  = trades.filter(t=>t.pnl>0).length;
  const accuracy    = trades.length ? Math.round(profTrades/trades.length*100) : 0;
  const dist60      = dailyPnL * 0.6;
  const dist40      = dailyPnL * 0.4;
  const proj30      = +(portfolioBTC * Math.pow(1 + totalROI/100/365, 30)).toFixed(5);
  const totalPnL    = strats.reduce((a,s)=>a+s.pnl,0);

  const c = {
    bg:    "#060A14", card:  "#0B1220", border: "#162030",
    btc:   "#F59E0B", green: "#00F5A0", red:    "#FF3355",
    blue:  "#00C8FF", purp:  "#9F7AEA",
  };
  const mono = "'Share Tech Mono',monospace";
  const orb  = "'Orbitron',monospace";
  const raj  = "'Rajdhani',sans-serif";

  return (
    <div style={{fontFamily:raj,background:c.bg,color:"#E2E8F0",minHeight:"100vh",padding:"14px",boxSizing:"border-box"}}>

      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@600;900&family=Share+Tech+Mono&family=Rajdhani:wght@400;500;600&display=swap');
        @keyframes scanl  {0%{left:-100%}100%{left:100%}}
        @keyframes blink  {0%,100%{opacity:1}50%{opacity:.25}}
        @keyframes fadein {from{opacity:0;transform:translateY(-5px)}to{opacity:1;transform:translateY(0)}}
        *{box-sizing:border-box}
        ::-webkit-scrollbar{width:4px;background:#060A14}
        ::-webkit-scrollbar-thumb{background:#162030;border-radius:2px}
      `}</style>

      {/* ── HEADER ── */}
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:"14px",paddingBottom:"12px",borderBottom:`1px solid ${c.border}`}}>
        <div>
          <div style={{fontFamily:orb,fontSize:"15px",fontWeight:"900",letterSpacing:"2px",display:"flex",alignItems:"center",gap:"10px"}}>
            <span style={{color:c.blue}}>⬡</span> AITRADINGAGENT PRO
            <span style={{fontSize:"7px",color:c.btc,border:`1px solid ${c.btc}40`,padding:"2px 8px",borderRadius:"4px",letterSpacing:"2px",fontFamily:mono}}>
              ALAN J · PAPER MODE
            </span>
          </div>
          <div style={{color:"#374151",fontSize:"9px",letterSpacing:"2px",marginTop:"3px",fontFamily:mono}}>
            Edinburgh · Multi-Agent · All values in ₿
          </div>
        </div>
        <div style={{display:"flex",gap:"8px",alignItems:"center"}}>
          <div style={{display:"flex",alignItems:"center",gap:"6px",padding:"6px 12px",background:c.card,border:`1px solid ${c.border}`,borderRadius:"6px"}}>
            <div style={{width:"6px",height:"6px",borderRadius:"50%",
              background:running ? c.green : c.red,
              animation:running ? "blink 1.5s infinite" : "none"
            }}/>
            <span style={{fontSize:"9px",letterSpacing:"2px",color:running ? c.green : c.red,fontFamily:orb}}>
              {running ? "LIVE" : "STOPPED"}
            </span>
          </div>
          {running
            ? <button onClick={stopAll} style={{padding:"8px 16px",background:`linear-gradient(135deg,${c.red},#AA0022)`,border:"none",borderRadius:"6px",color:"#fff",fontFamily:orb,fontSize:"9px",fontWeight:"900",letterSpacing:"1px",cursor:"pointer"}}>⬛ STOP ALL</button>
            : <button onClick={resume}  style={{padding:"8px 16px",background:"linear-gradient(135deg,#00F5A0,#00A870)",border:"none",borderRadius:"6px",color:"#060A14",fontFamily:orb,fontSize:"9px",fontWeight:"900",letterSpacing:"1px",cursor:"pointer"}}>▶ RESUME</button>
          }
        </div>
      </div>

      {/* ── KEY METRICS ── */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:"8px",marginBottom:"12px"}}>
        {[
          {lbl:"PORTFOLIO",       val:`${portfolioBTC.toFixed(5)} ₿`, sub:fUSD(portfolioBTC,btcPrice), col:c.btc},
          {lbl:"BTC PRICE",       val:`$${btcPrice.toLocaleString("en-US",{maximumFractionDigits:0})}`, sub:`${fPct(1.8)} 24h`, col:c.btc},
          {lbl:"24H P&L",         val:fBTC(dailyPnL), sub:fUSD(dailyPnL,btcPrice), col:dailyPnL>=0 ? c.green : c.red},
          {lbl:"TOTAL ROI",       val:fPct(totalROI), sub:`${activeCount} strats · compounding`, col:c.blue},
        ].map(m=>(
          <div key={m.lbl} style={{background:c.card,border:`1px solid ${c.border}`,borderRadius:"10px",padding:"14px"}}>
            <div style={{color:"#374151",fontSize:"8px",letterSpacing:"2px",marginBottom:"8px",fontFamily:mono}}>{m.lbl}</div>
            <div style={{color:m.col,fontFamily:mono,fontSize:"17px",fontWeight:"700",marginBottom:"4px"}}>{m.val}</div>
            <div style={{color:"#475569",fontSize:"10px"}}>{m.sub}</div>
          </div>
        ))}
      </div>

      {/* ── SENTIMENT + INTELLIGENCE + AGENTS ── */}
      <div style={{display:"grid",gridTemplateColumns:"190px 1fr 210px",gap:"8px",marginBottom:"12px"}}>

        {/* Gauge */}
        <div style={{background:c.card,border:`1px solid ${c.border}`,borderRadius:"10px",padding:"14px",display:"flex",flexDirection:"column",alignItems:"center"}}>
          <div style={{color:"#374151",fontSize:"8px",letterSpacing:"2px",marginBottom:"8px",alignSelf:"flex-start",fontFamily:mono}}>SENTIMENT AGENT</div>
          <Gauge score={Math.round(sentiment)}/>
          <button onClick={runAI} disabled={aiLoading} style={{
            marginTop:"10px",width:"100%",padding:"8px",
            background:c.card,border:`1px solid ${c.blue}40`,
            borderRadius:"6px",color:c.blue,fontSize:"8px",letterSpacing:"1px",
            cursor:aiLoading ? "default":"pointer",fontFamily:orb,fontWeight:"600",opacity:aiLoading?0.6:1
          }}>{aiLoading ? "⟳ ANALYSING..." : "⟳ RUN AI ANALYSIS"}</button>
        </div>

        {/* Intelligence */}
        <div style={{background:c.card,border:`1px solid ${c.border}`,borderRadius:"10px",padding:"14px"}}>
          <div style={{color:"#374151",fontSize:"8px",letterSpacing:"2px",marginBottom:"10px",fontFamily:mono}}>MARKET INTELLIGENCE</div>
          <div style={{display:"flex",gap:"6px",marginBottom:"12px",flexWrap:"wrap"}}>
            {[
              {lbl:"REGIME",     val:regime,         col:c.green},
              {lbl:"LSE CLOSE",  val:lse,            col:c.btc},
              {lbl:"ACCURACY",   val:`${accuracy}%`, col:c.purp},
              {lbl:"STRATS",     val:`${activeCount}/6`, col:c.blue},
              {lbl:"ALL P&L",    val:fBTC(totalPnL), col:totalPnL>=0 ? c.green : c.red},
            ].map(chip=>(
              <div key={chip.lbl} style={{padding:"5px 10px",background:`${chip.col}10`,border:`1px solid ${chip.col}25`,borderRadius:"6px"}}>
                <div style={{color:"#374151",fontSize:"7px",letterSpacing:"1px",marginBottom:"3px"}}>{chip.lbl}</div>
                <div style={{color:chip.col,fontSize:"11px",fontWeight:"700",fontFamily:mono}}>{chip.val}</div>
              </div>
            ))}
          </div>
          {aiText
            ? <div style={{animation:"fadein 0.4s ease"}}>
                <div style={{color:"#64748B",fontSize:"10px",lineHeight:"1.75",marginBottom:"8px"}}>{aiText}</div>
                {aiRec && <div style={{padding:"6px 10px",background:`${c.blue}10`,border:`1px solid ${c.blue}25`,borderRadius:"6px",color:c.blue,fontSize:"9px",letterSpacing:"1px",fontFamily:mono}}>→ {aiRec}</div>}
              </div>
            : <div style={{color:"#2D3748",fontSize:"10px",fontStyle:"italic"}}>Click "Run AI Analysis" for live Claude market intelligence...</div>
          }
        </div>

        {/* Agents */}
        <div style={{background:c.card,border:`1px solid ${c.border}`,borderRadius:"10px",padding:"14px"}}>
          <div style={{color:"#374151",fontSize:"8px",letterSpacing:"2px",marginBottom:"10px",fontFamily:mono}}>AGENTS</div>
          {AGENTS.map((ag,i)=>(
            <div key={ag.name} style={{
              display:"flex",alignItems:"center",gap:"8px",padding:"7px 8px",borderRadius:"6px",
              background:pulseIdx===i && running ? `${ag.col}12` : "transparent",
              border:`1px solid ${pulseIdx===i && running ? ag.col+"40" : "transparent"}`,
              marginBottom:"4px",transition:"all 0.5s"
            }}>
              <div style={{width:"6px",height:"6px",borderRadius:"50%",flexShrink:0,
                background:ag.col,opacity:pulseIdx===i&&running?1:0.25,transition:"opacity 0.5s"
              }}/>
              <div style={{flex:1}}>
                <div style={{color:pulseIdx===i&&running ? ag.col : "#94A3B8",fontSize:"11px",fontWeight:"600",transition:"color 0.5s"}}>{ag.name}</div>
                <div style={{color:"#374151",fontSize:"8px"}}>{ag.role}</div>
              </div>
              {pulseIdx===i&&running && <div style={{color:ag.col,fontSize:"7px",animation:"blink 0.8s infinite"}}>●</div>}
            </div>
          ))}
        </div>
      </div>

      {/* ── STRATEGIES ── */}
      <div style={{marginBottom:"12px"}}>
        <div style={{color:"#374151",fontSize:"8px",letterSpacing:"2px",marginBottom:"8px",fontFamily:mono}}>
          STRATEGIES · <span style={{color:c.green}}>{activeCount} ACTIVE</span> · click to enable/disable
        </div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:"8px"}}>
          {strats.map(s=><StratCard key={s.id} s={s} onToggle={toggleStrat}/>)}
        </div>
      </div>

      {/* ── BOTTOM PANEL: tabbed ── */}
      <div style={{background:c.card,border:`1px solid ${c.border}`,borderRadius:"10px",overflow:"hidden"}}>
        {/* Tab bar */}
        <div style={{display:"flex",borderBottom:`1px solid ${c.border}`}}>
          {[
            {id:"trades", lbl:"TRADE LOG"},
            {id:"dist",   lbl:"DISTRIBUTION"},
            {id:"wallet", lbl:"WALLET"},
          ].map(t=>(
            <button key={t.id} onClick={()=>setTab(t.id)} style={{
              padding:"10px 20px",border:"none",borderBottom:`2px solid ${tab===t.id ? c.blue : "transparent"}`,
              background:"transparent",color:tab===t.id ? c.blue : "#374151",
              fontFamily:orb,fontSize:"9px",fontWeight:"700",letterSpacing:"1px",cursor:"pointer",
              transition:"all 0.2s"
            }}>{t.lbl}</button>
          ))}
          <div style={{flex:1}}/>
          {/* Data sources */}
          <div style={{display:"flex",alignItems:"center",gap:"10px",padding:"0 16px"}}>
            {DATA_SOURCES.map(src=>(
              <div key={src.name} style={{display:"flex",alignItems:"center",gap:"5px"}}>
                <div style={{width:"5px",height:"5px",borderRadius:"50%",background:src.col,animation:"blink 2s infinite"}}/>
                <span style={{color:"#374151",fontSize:"8px",fontFamily:mono}}>{src.name}</span>
                <span style={{color:"#2D3748",fontSize:"7px",fontFamily:mono}}>{src.lat}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Tab: Trade Log */}
        {tab==="trades" && (
          <div style={{padding:"14px"}}>
            <div style={{maxHeight:"240px",overflowY:"auto"}}>
              <table style={{width:"100%",borderCollapse:"collapse",fontSize:"10px"}}>
                <thead style={{position:"sticky",top:0,background:c.card}}>
                  <tr>
                    {["TIME","PAIR","SIDE","STRATEGY","AGENT","P&L ₿","CONF %","STATUS"].map(h=>(
                      <th key={h} style={{textAlign:"left",padding:"4px 8px",borderBottom:`1px solid ${c.border}`,color:"#374151",fontWeight:"400",fontSize:"8px",letterSpacing:"1px"}}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {trades.map((t,i)=>(
                    <tr key={t.id} style={{borderBottom:`1px solid #0F1828`,animation:i===0?"fadein 0.3s ease":"none"}}>
                      <td style={{padding:"5px 8px",color:"#475569",fontFamily:mono}}>{t.time}</td>
                      <td style={{padding:"5px 8px",color:"#94A3B8",fontFamily:mono}}>{t.pair}</td>
                      <td style={{padding:"5px 8px",color:t.side==="LONG" ? c.green : c.red,fontWeight:"600",fontSize:"9px"}}>{t.side}</td>
                      <td style={{padding:"5px 8px",color:"#64748B"}}>{t.strategy}</td>
                      <td style={{padding:"5px 8px",color:"#64748B"}}>{t.agent}</td>
                      <td style={{padding:"5px 8px",color:t.pnl>=0 ? c.green : c.red,fontFamily:mono}}>{fBTC(t.pnl)}</td>
                      <td style={{padding:"5px 8px",color:"#64748B",fontFamily:mono}}>{t.conf}%</td>
                      <td style={{padding:"5px 8px"}}>
                        <span style={{padding:"2px 6px",borderRadius:"4px",fontSize:"7px",letterSpacing:"1px",
                          background:t.closed ? "#00F5A010" : "#F59E0B10",
                          color:t.closed ? c.green : c.btc
                        }}>{t.closed?"CLOSED":"OPEN"}</span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* Tab: Distribution */}
        {tab==="dist" && (
          <div style={{padding:"16px"}}>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:"12px",marginBottom:"16px"}}>
              <div style={{padding:"16px",background:`${c.green}08`,border:`1px solid ${c.green}25`,borderRadius:"8px"}}>
                <div style={{color:"#374151",fontSize:"8px",letterSpacing:"1.5px",marginBottom:"8px",fontFamily:mono}}>TOTAL DAILY P&L</div>
                <div style={{color:dailyPnL>=0 ? c.green : c.red,fontFamily:mono,fontSize:"20px",fontWeight:"700"}}>{fBTC(dailyPnL)}</div>
                <div style={{color:"#475569",fontSize:"10px",marginTop:"4px"}}>{fUSD(dailyPnL,btcPrice)}</div>
              </div>
              <div style={{padding:"16px",background:"#4285F415",border:"1px solid #4285F430",borderRadius:"8px"}}>
                <div style={{color:"#374151",fontSize:"8px",letterSpacing:"1.5px",marginBottom:"8px",fontFamily:mono}}>60% → CRYPTO.COM</div>
                <div style={{color:"#5B8EFF",fontFamily:mono,fontSize:"20px",fontWeight:"700"}}>{fBTC(dist60)}</div>
                <div style={{color:"#475569",fontSize:"10px",marginTop:"4px"}}>{fUSD(dist60,btcPrice)}</div>
              </div>
              <div style={{padding:"16px",background:`${c.green}10`,border:`1px solid ${c.green}25`,borderRadius:"8px"}}>
                <div style={{color:"#374151",fontSize:"8px",letterSpacing:"1.5px",marginBottom:"8px",fontFamily:mono}}>40% → COMPOUND</div>
                <div style={{color:c.green,fontFamily:mono,fontSize:"20px",fontWeight:"700"}}>{fBTC(dist40)}</div>
                <div style={{color:"#475569",fontSize:"10px",marginTop:"4px"}}>{fUSD(dist40,btcPrice)}</div>
              </div>
            </div>
            <div style={{padding:"14px",background:"#060A14",borderRadius:"8px",border:`1px solid ${c.border}`}}>
              <div style={{color:"#374151",fontSize:"8px",letterSpacing:"1.5px",marginBottom:"10px",fontFamily:mono}}>30-DAY COMPOUNDING PROJECTION · BLOCKCHAIN FEES DEDUCTED</div>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-end"}}>
                <div>
                  <div style={{color:"#475569",fontSize:"10px",marginBottom:"4px"}}>Current: <span style={{color:"#E2E8F0",fontFamily:mono}}>{portfolioBTC.toFixed(5)} ₿  ({fUSD(portfolioBTC,btcPrice)})</span></div>
                  <div style={{color:"#475569",fontSize:"10px",marginBottom:"4px"}}>Fees est: <span style={{color:c.red,fontFamily:mono}}>-0.000012 ₿/day</span></div>
                  <div style={{color:"#475569",fontSize:"10px"}}>30d proj: <span style={{color:c.green,fontFamily:mono}}>{proj30} ₿  ({fUSD(proj30,btcPrice)})</span></div>
                </div>
                <div style={{textAlign:"right"}}>
                  <div style={{color:c.green,fontFamily:mono,fontSize:"28px",fontWeight:"700"}}>+{(totalROI/365*30).toFixed(1)}%</div>
                  <div style={{color:"#374151",fontSize:"9px"}}>estimated 30-day</div>
                  <div style={{color:"#374151",fontSize:"8px",marginTop:"2px"}}>Triggers at LSE close {lse}</div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Tab: Wallet */}
        {tab==="wallet" && (
          <div style={{padding:"16px"}}>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"12px"}}>
              <div>
                <div style={{display:"flex",alignItems:"center",gap:"12px",padding:"16px",background:"linear-gradient(135deg,#4285F415,#060A14)",border:"1px solid #4285F430",borderRadius:"8px",marginBottom:"12px"}}>
                  <div style={{width:"40px",height:"40px",borderRadius:"8px",background:"linear-gradient(135deg,#003CFF,#0066FF)",display:"flex",alignItems:"center",justifyContent:"center",color:"#fff",fontSize:"20px",flexShrink:0}}>₿</div>
                  <div style={{flex:1}}>
                    <div style={{color:"#475569",fontSize:"8px",letterSpacing:"1.5px",marginBottom:"4px"}}>TOTAL BALANCE</div>
                    <div style={{color:c.btc,fontFamily:mono,fontSize:"22px",fontWeight:"700"}}>{portfolioBTC.toFixed(5)} ₿</div>
                    <div style={{color:"#475569",fontSize:"10px"}}>{fUSD(portfolioBTC,btcPrice)} · Crypto.com</div>
                  </div>
                </div>
                <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"6px"}}>
                  {[
                    {lbl:"In Strategies",  val:fBTC(portfolioBTC*0.7),   col:c.blue},
                    {lbl:"Reserved",       val:fBTC(portfolioBTC*0.3),   col:c.purp},
                    {lbl:"Blockchain Fees",val:fBTC(-0.000012),          col:c.red},
                    {lbl:"Net Today",      val:fBTC(dailyPnL),           col:c.green},
                  ].map(item=>(
                    <div key={item.lbl} style={{padding:"10px",background:"#060A14",borderRadius:"6px",border:`1px solid ${c.border}`}}>
                      <div style={{color:"#374151",fontSize:"8px",marginBottom:"4px"}}>{item.lbl}</div>
                      <div style={{color:item.col,fontSize:"11px",fontFamily:mono}}>{item.val}</div>
                    </div>
                  ))}
                </div>
              </div>
              <div style={{display:"flex",flexDirection:"column",gap:"8px"}}>
                <div style={{padding:"14px",background:"#060A14",borderRadius:"8px",border:`1px solid ${c.border}`,flex:1}}>
                  <div style={{color:"#374151",fontSize:"8px",letterSpacing:"1.5px",marginBottom:"10px",fontFamily:mono}}>QUICK DEPOSIT · CRYPTO.COM</div>
                  <input
                    value={depAmt}
                    onChange={e=>setDepAmt(e.target.value)}
                    placeholder="Amount in BTC e.g. 0.001"
                    style={{width:"100%",padding:"10px",background:"#0B1220",border:`1px solid ${c.border}`,borderRadius:"6px",color:"#E2E8F0",fontSize:"11px",fontFamily:mono,outline:"none",marginBottom:"8px"}}
                  />
                  {depAmt && !isNaN(parseFloat(depAmt)) && (
                    <div style={{color:"#475569",fontSize:"9px",marginBottom:"8px",fontFamily:mono}}>≈ {fUSD(parseFloat(depAmt),btcPrice)}</div>
                  )}
                  <div style={{display:"flex",gap:"6px"}}>
                    <button style={{flex:1,padding:"10px",background:"linear-gradient(135deg,#003CFF,#0055FF)",border:"none",borderRadius:"6px",color:"#fff",fontFamily:orb,fontSize:"8px",fontWeight:"700",letterSpacing:"1px",cursor:"pointer"}}>↓ DEPOSIT</button>
                    <button style={{flex:1,padding:"10px",background:"transparent",border:`1px solid ${c.border}`,borderRadius:"6px",color:"#64748B",fontFamily:orb,fontSize:"8px",fontWeight:"700",letterSpacing:"1px",cursor:"pointer"}}>↑ WITHDRAW</button>
                  </div>
                </div>
                <div style={{padding:"10px",background:"#F59E0B08",border:`1px solid ${c.btc}20`,borderRadius:"8px"}}>
                  <div style={{color:"#F59E0B",fontSize:"9px",lineHeight:"1.6"}}>⚠ Paper mode is active. Connect live Crypto.com API keys in your <span style={{fontFamily:mono}}>.env</span> to enable real deposits and withdrawals.</div>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* FOOTER */}
      <div style={{marginTop:"12px",textAlign:"center",color:"#1E2D4A",fontSize:"8px",letterSpacing:"2px",fontFamily:mono}}>
        AITRADINGAGENT PRO · PAPER TRADING · ALL CRYPTO IN ₿ · {new Date().toLocaleString("en-GB")} · barcl@Edinburgh
      </div>
    </div>
  );
}

display_content.json_block:
{"language": "javascript", "code": "import { useState, useEffect, useCallback, useRef } from "react";

const STRATEGIES = [
  { id:"orb",      name:"Opening Range Breakout",   hitRate:68, trades:247, pnl:0.003122, active:true,  learning:false, desc:"First-hour momentum capture",       col:"#00C8FF" },
