function mkTrade(id) {
  const side = Math.random() > 0.38 ? "LONG" : "SHORT";
  const pnl  = (Math.random() - 0.28) * 0.00085;
  return {
    id,
    time: new Date(Date.now() - Math.random()*7200000).toLocaleTimeString("en-GB",{hour:"2-digit",minute:"2-digit",second:"2-digit"}),
    pair: `${COINS[Math.floor(Math.random()*COINS.length)]}/BTC`,
    side,
    strategy: S_NAMES[Math.floor(Math.random()*S_NAMES.length)],
    agent:    A_NAMES[Math.floor(Math.random()*A_NAMES.length)],
    pnl,
    conf:   Math.floor(65 + Math.random()*30),
    closed: Math.random() > 0.3,
  };
}

function getLSE() {
  const lon = new Date(new Date().toLocaleString("en-US",{timeZone:"Europe/London"}));
  const cl  = new Date(lon); cl.setHours(16,30,0,0);
  if(lon >= cl) cl.setDate(cl.getDate()+1);
  const d = cl - lon;
  const h = Math.floor(d/3600000), m = Math.floor((d%3600000)/60000), s = Math.floor((d%60000)/1000);
  return `${String(h).padStart(2,"0")}:${String(m).padStart(2,"0")}:${String(s).padStart(2,"0")}`;
}

const fBTC = v => `${v>=0?"+":""}${v.toFixed(6)} ₿`;
const fUSD = (b,p) => `$${(b*p).toLocaleString("en-US",{maximumFractionDigits:0})}`;
const fPct = v => `${v>=0?"+":""}${v.toFixed(2)}%`;

// ── Sentiment Gauge ───────────────────────────────────────────
function Gauge({score}) {
  const angle = (score/100)*180 - 90;
  const rad   = (angle - 90) * Math.PI/180;
  const col   = score < 30 ? "#FF3355" : score < 50 ? "#F59E0B" : score < 70 ? "#00C8FF" : "#00F5A0";
  const lbl   = score < 20 ? "EXTREME FEAR" : score < 40 ? "FEAR" : score < 60 ? "NEUTRAL" : score < 80 ? "GREED" : "EXTREME GREED";
  const nx = 80 + 58*Math.cos(rad), ny = 84 + 58*Math.sin(rad);
  return (
    <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:"4px"}}>
      <svg width="164" height="92" viewBox="0 0 164 92">
        <path d="M12 85 A70 70 0 0 1 152 85" fill="none" stroke="#162030" strokeWidth="13" strokeLinecap="round"/>
        <path d="M12 85 A70 70 0 0 1 50 27"  fill="none" stroke="#FF3355" strokeWidth="13" strokeLinecap="round" opacity="0.22"/>
        <path d="M50 27 A70 70 0 0 1 114 27" fill="none" stroke="#F59E0B" strokeWidth="13" strokeLinecap="round" opacity="0.22"/>
        <path d="M114 27 A70 70 0 0 1 152 85" fill="none" stroke="#00F5A0" strokeWidth="13" strokeLinecap="round" opacity="0.22"/>
        <line x1="82" y1="85" x2={nx} y2={ny} stroke={col} strokeWidth="2.5" strokeLinecap="round"/>
        <circle cx="82" cy="85" r="5" fill={col}/>
        <text x="82" y="71" textAnchor="middle" fill={col} fontSize="20" fontWeight="700" fontFamily="monospace">{score}</text>
      </svg>
      <div style={{color:col,fontSize:"9px",fontWeight:"700",letterSpacing:"3px"}}>{lbl}</div>
    </div>
  );
}

