      const key = `${coinId}-${signal.timestamp}`;
      if (tradeTimers.current[key]) return;
      tradeTimers.current[key] = true;

      const portfolioValue = getPortfolioValue();
      const maxTradeAmount = portfolioValue * MAX_POSITION_PCT;
      const amount = Math.min(tradeAmount, maxTradeAmount);

