import { useState, useEffect, useRef, useCallback } from "react";

const COINS = {
  bitcoin: { symbol: "BTC", name: "Bitcoin", color: "#F7931A" },
  ethereum: { symbol: "ETH", name: "Ethereum", color: "#627EEA" },
  cronos: { symbol: "CRO", name: "Cronos", color: "#003399" },
  solana: { symbol: "SOL", name: "Solana", color: "#9945FF" },
  "avalanche-2": { symbol: "AVAX", name: "Avalanche", color: "#E84142" },
  arbitrum: { symbol: "ARB", name: "Arbitrum", color: "#28A0F0" },
  optimism: { symbol: "OP", name: "Optimism", color: "#FF0420" },
};

const EXCHANGES = ["Binance", "Kraken", "Coinbase", "KuCoin"];
const STARTING_BALANCE = 10000;
const TRADE_FEE = 0.001;
const MAX_POS_PCT = 0.20;

// Deterministic price variance per exchange
const EX_VARIANCE = { Binance: 0.0018, Kraken: -0.0022, Coinbase: 0.0009, KuCoin: -0.0014 };

const fmt = (n, d = 2) => Number(n).toLocaleString("en-US", { minimumFractionDigits: d, maximumFractionDigits: d });
const fmtUSD = n => `$${fmt(n)}`;
const sign = n => n >= 0 ? "+" : "";

function exPrice(base, ex) {
  return base * (1 + (EX_VARIANCE[ex] ?? 0));
}

function scanArb(prices) {
  return Object.entries(COINS).map(([id, coin]) => {
    const base = prices[id]?.usd;
    if (!base) return null;
    const xPrices = EXCHANGES.map(ex => ({ ex, p: exPrice(base, ex) }));
    const low = xPrices.reduce((a, b) => a.p < b.p ? a : b);
    const high = xPrices.reduce((a, b) => a.p > b.p ? a : b);
    const spread = (high.p - low.p) / low.p;
    const net = spread - TRADE_FEE * 2;
    return { id, symbol: coin.symbol, color: coin.color, buyEx: low.ex, buyP: low.p, sellEx: high.ex, sellP: high.p, spread: spread * 100, net: net * 100, xPrices };
  }).filter(x => x && x.net > 0.05).sort((a, b) => b.net - a.net);
}

