<div id="root" style="background:#07091c;min-height:620px;display:flex;flex-direction:column;border:1px solid #1e2147">

  <!-- HEADER -->
  <div id="hdr" style="background:#0c0e28;border-bottom:1px solid #1e2147;padding:8px 14px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px">
    <div style="display:flex;align-items:center;gap:10px">
      <span style="font-weight:700;font-size:15px;color:#00d88a;letter-spacing:.12em">ALANBOT</span>
      <span style="background:#ff335511;border:1px solid #ff335544;color:#ff3355;padding:1px 6px;font-size:9px;letter-spacing:.1em">PAPER</span>
      <span id="auto-badge" style="font-size:9px;color:#4a4e6a"></span>
    </div>
    <div style="display:flex;gap:20px;align-items:center">
      <div>
        <div style="color:#4a4e6a;font-size:9px">PORTFOLIO</div>
        <div id="total-val" style="font-size:17px;font-weight:700;color:#c0c4e0">$10,000.00</div>
      </div>
      <div>
        <div style="color:#4a4e6a;font-size:9px">P&L</div>
        <div id="pnl-val" style="font-size:14px;font-weight:700">—</div>
      </div>
      <div>
        <div style="color:#4a4e6a;font-size:9px">USDT</div>
        <div id="usdt-val" style="font-size:13px;font-weight:700;color:#ffc300">$10,000.00</div>
      </div>
      <button onclick="resetPortfolio()" style="background:#1e2147;border:1px solid #2a2d55;color:#4a4e6a;padding:4px 8px;font-size:9px">↺ RESET</button>
    </div>
  </div>

  <!-- TABS -->
  <div style="background:#0c0e28;border-bottom:1px solid #1e2147;display:flex">
    <button id="tab-market" onclick="setTab('market')" class="tab-btn active-tab">◈ MARKET</button>
    <button id="tab-signals" onclick="setTab('signals')" class="tab-btn">⟁ AI SIGNALS</button>
    <button id="tab-arb" onclick="setTab('arb')" class="tab-btn">⟷ ARBITRAGE</button>
    <button id="tab-history" onclick="setTab('history')" class="tab-btn">◎ HISTORY</button>
  </div>

  <!-- BODY -->
  <div style="flex:1;display:grid;grid-template-columns:175px 1fr;overflow:hidden;min-height:400px">

    <!-- COIN LIST -->
    <div id="coin-list" style="border-right:1px solid #1e2147;overflow-y:auto"></div>

    <!-- MAIN CONTENT -->
    <div id="main-content" style="overflow-y:auto;padding:14px"></div>
  </div>

  <!-- CONSOLE -->
  <div style="border-top:1px solid #1e2147;background:#050713;padding:6px 12px;max-height:130px;overflow-y:auto">
    <div style="color:#2a2d55;font-size:9px;letter-spacing:.15em;margin-bottom:3px">CONSOLE</div>
    <div id="console-log"></div>
  </div>
</div>

<style>
.tab-btn{padding:6px 14px;background:transparent;color:#4a4e6a;font-size:10px;font-weight:700;letter-spacing:.1em;border-right:1px solid #1e2147;transition:all .2s}
.tab-btn.active-tab{background:#00d88a;color:#07091c}
.coin-item{padding:8px 10px;cursor:pointer;border-left:3px solid transparent;transition:background .15s}
.coin-item:hover{background:#0d0f26}
.coin-item.selected{border-left-color:currentColor}
.panel{background:#0c0e28;border:1px solid #1e2147;padding:12px 14px;margin-bottom:10px}
.btn-buy{background:#00d88a22;border:1px solid #00d88a;color:#00d88a;padding:9px;font-weight:700;letter-spacing:.08em;width:100%;transition:opacity .2s}
.btn-sell{background:#ff335522;border:1px solid #ff3355;color:#ff3355;padding:9px;font-weight:700;letter-spacing:.08em;width:100%;transition:opacity .2s}
.dim{color:#4a4e6a}
.green{color:#00d88a}
.red{color:#ff3355}
.yellow{color:#ffc300}
.blue{color:#4d9fff}
</style>

<script>
// ═══════════════════════════════════════
//  CONSTANTS
// ═══════════════════════════════════════
const COINS = {
  bitcoin:       {symbol:'BTC', name:'Bitcoin',   color:'#F7931A'},
  ethereum:      {symbol:'ETH', name:'Ethereum',  color:'#627EEA'},
  'crypto-com-chain':{symbol:'CRO', name:'Cronos', color:'#00aaff'},
  solana:        {symbol:'SOL', name:'Solana',    color:'#9945FF'},
  'avalanche-2': {symbol:'AVAX',name:'Avalanche', color:'#E84142'},
  arbitrum:      {symbol:'ARB', name:'Arbitrum',  color:'#28A0F0'},
  optimism:      {symbol:'OP',  name:'Optimism',  color:'#FF0420'},
};
const COIN_IDS = Object.keys(COINS);
const EXCHANGES = ['Binance','Kraken','Coinbase','KuCoin'];
const EX_V = {Binance:0.0018, Kraken:-0.0022, Coinbase:0.0009, KuCoin:-0.0014};
const START_BAL = 10000;
const FEE = 0.001;
const MAX_POS = 0.20;

// ═══════════════════════════════════════
//  STATE
// ═══════════════════════════════════════
const S = {
  prices: {},
  portfolio: {USDT: START_BAL},
  trades: [],
  signals: {},
  arb: [],
  logs: [{msg:'⬡ AlanBot v2.0 — Paper trading active', type:'system', ts:Date.now()}],
  selCoin: 'bitcoin',
  tab: 'market',
  amount: '500',
  autoTrade: false,
  loadingSig: false,
  usedSigs: new Set(),
};

// ═══════════════════════════════════════
//  HELPERS
// ═══════════════════════════════════════
const fmt = (n,d=2) => (+n||0).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const fmtUSD = n => `$${fmt(n)}`;
const sign = n => n>=0?'+':'';
const el = id => document.getElementById(id);

function exPrice(base, ex) {
  return base * (1 + (EX_V[ex]||0));
}

function scanArb(prices) {
  return COIN_IDS.map(id => {
    const p = prices[id]?.usd;
    if (!p) return null;
    const xp = EXCHANGES.map(ex => ({ex, p: exPrice(p,ex)}));
    const lo = xp.reduce((a,b) => a.p<b.p?a:b);
    const hi = xp.reduce((a,b) => a.p>b.p?a:b);
    const spread = (hi.p - lo.p) / lo.p;
    const net = spread - FEE*2;
    return {id, sym:COINS[id].symbol, color:COINS[id].color, buyEx:lo.ex, buyP:lo.p, sellEx:hi.ex, sellP:hi.p, spread:spread*100, net:net*100, xp};
  }).filter(x => x && x.net > 0.05).sort((a,b) => b.net-a.net);
}

function getTotal() {
  let v = S.portfolio.USDT || 0;
  Object.entries(S.portfolio).forEach(([sym, amt]) => {
    if (sym==='USDT') return;
    const id = COIN_IDS.find(i => COINS[i].symbol===sym);
    if (id && S.prices[id]?.usd) v += amt * S.prices[id].usd;
  });
  return v;
}

function addLog(msg, type='info') {
  S.logs.unshift({msg, type, ts:Date.now()});
  if (S.logs.length > 200) S.logs.pop();
  renderConsole();
}

// ═══════════════════════════════════════
//  TRADING
// ═══════════════════════════════════════
function executeTrade(coinId, action, usd) {
  const price = S.prices[coinId]?.usd;
  if (!price || usd <= 0) return;
  const sym = COINS[coinId].symbol;
  const fee = usd * FEE;

  if (action === 'BUY') {
    if ((S.portfolio.USDT||0) < usd) { addLog(`✗ Insufficient USDT for ${sym}`, 'error'); return; }
    const qty = (usd - fee) / price;
    S.portfolio.USDT = (S.portfolio.USDT||0) - usd;
    S.portfolio[sym] = (S.portfolio[sym]||0) + qty;
    addLog(`▲ BUY ${qty.toFixed(6)} ${sym} @ ${fmtUSD(price)} | fee ${fmtUSD(fee)}`, 'buy');
  } else {
    const has = S.portfolio[sym]||0;
    const qty = Math.min(has, (usd-fee)/price);
    if (qty <= 0) { addLog(`✗ No ${sym} to sell`, 'error'); return; }
    const received = qty * price - fee;
    S.portfolio[sym] = has - qty;
    S.portfolio.USDT = (S.portfolio.USDT||0) + received;
    addLog(`▼ SELL ${qty.toFixed(6)} ${sym} @ ${fmtUSD(price)} → ${fmtUSD(received)}`, 'sell');
  }

  S.trades.unshift({id:Date.now(), coinId, sym, action, price, usd, fee, ts:Date.now()});
  if (S.trades.length > 200) S.trades.pop();
  updateHeader();
  if (S.tab === 'market') renderMarketTab();
  if (S.tab === 'history') renderHistoryTab();
}

function execArb(op) {
  const amt = parseFloat(S.amount)||500;
  const profit = (op.net/100) * amt;
  S.portfolio.USDT = (S.portfolio.USDT||0) + profit;
  addLog(`⟷ ARB ${op.sym}: Buy ${op.buyEx} @ ${fmtUSD(op.buyP)} → Sell ${op.sellEx} @ ${fmtUSD(op.sellP)} | Profit +${fmtUSD(profit)}`, 'buy');
  S.trades.unshift({id:Date.now(), coinId:op.id, sym:op.sym, action:'ARB', price:op.buyP, usd:amt, fee:0, ts:Date.now(), arbProfit:profit});
  updateHeader();
}

async function genSignal(coinId) {
  if (!S.prices[coinId]?.usd || S.loadingSig) return;
  S.loadingSig = true;
  renderTab();

  const coin = COINS[coinId];
  const p = S.prices[coinId];

  try {
    const res = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {'Content-Type':'application/json'},
      body: JSON.stringify({
        model: 'claude-sonnet-4-20250514',
        max_tokens: 250,
        messages: [{
          role: 'user',
          content: `Analyze ${coin.name} (${coin.symbol}) for a paper trade signal.
Price: $${p.usd} | 24h: ${(p.usd_24h_change||0).toFixed(2)}%
Market cap: $${((p.usd_market_cap||0)/1e9).toFixed(2)}B

You are a crypto trading AI. Respond ONLY with a valid JSON object, no markdown, no explanation:
{"signal":"BUY","confidence":82,"reason":"Strong momentum with key support holding","momentum":"bullish","risk":"medium"}

signal must be BUY, SELL, or HOLD. confidence is 0-100. risk is low, medium, or high.`
        }]
      })
    });
    const data = await res.json();
    const text = (data.content?.[0]?.text || '{}').replace(/```[a-z]*/g,'').replace(/```/g,'').trim();
    const sig = JSON.parse(text);
    S.signals[coinId] = {...sig, ts: Date.now()};
    addLog(`[AI→${coin.symbol}] ${sig.signal} ${sig.confidence}% — ${sig.reason}`, sig.signal==='BUY'?'buy':sig.signal==='SELL'?'sell':'info');

    // Auto-trade
    if (S.autoTrade && sig.confidence >= 75 && sig.signal !== 'HOLD') {
      const key = `${coinId}-${S.signals[coinId].ts}`;
      if (!S.usedSigs.has(key)) {
        S.usedSigs.add(key);
        const total = getTotal();
        const maxAmt = total * MAX_POS;
        const tradeAmt = Math.min(parseFloat(S.amount)||500, maxAmt);
        executeTrade(coinId, sig.signal, tradeAmt);
      }
    }
  } catch(e) {
    addLog('AI signal error: ' + e.message, 'error');
  } finally {
    S.loadingSig = false;
    renderTab();
    renderCoinList();
  }
}

function resetPortfolio() {
  Object.assign(S, {portfolio:{USDT:START_BAL}, trades:[], signals:{}, usedSigs:new Set()});
  addLog('Portfolio reset to $10,000 USDT', 'system');
  updateHeader();
  renderTab();
  renderCoinList();
}

// ═══════════════════════════════════════
//  API
// ═══════════════════════════════════════
async function fetchPrices() {
  try {
    const ids = COIN_IDS.join(',');
    const r = await fetch(`https://api.coingecko.com/api/v3/simple/price?ids=${ids}&vs_currencies=usd&include_24hr_change=true&include_market_cap=true`);
    const d = await r.json();

    // Flash detection
    COIN_IDS.forEach(id => {
      const old = S.prices[id]?.usd;
      const nw = d[id]?.usd;
      if (old && nw && old !== nw) {
        const el = document.querySelector(`[data-coin="${id}"]`);
        if (el) {
          el.classList.remove('flash-g','flash-r');
          void el.offsetWidth;
          el.classList.add(nw > old ? 'flash-g' : 'flash-r');
        }
      }
    });

    S.prices = d;
    S.arb = scanArb(d);
    renderCoinList();
    updateHeader();
    if (S.tab === 'market') renderMarketTab();
    if (S.tab === 'arb') renderArbTab();
  } catch(e) {
    addLog('Price fetch error: ' + e.message, 'error');
  }
}

// ═══════════════════════════════════════
//  RENDER
// ═══════════════════════════════════════
function updateHeader() {
  const total = getTotal();
  const pnl = total - START_BAL;
  const pct = (pnl/START_BAL)*100;
  el('total-val').textContent = fmtUSD(total);
  el('pnl-val').textContent = `${sign(pnl)}${fmtUSD(Math.abs(pnl))} (${sign(pct)}${fmt(pct)}%)`;
  el('pnl-val').style.color = pnl>=0?'#00d88a':'#ff3355';
  el('usdt-val').textContent = fmtUSD(S.portfolio.USDT||0);
  el('auto-badge').innerHTML = S.autoTrade ? '<span class="blink" style="color:#00d88a">AUTO ●</span>' : 'MANUAL';
}

function renderCoinList() {
  el('coin-list').innerHTML = COIN_IDS.map(id => {
    const coin = COINS[id];
    const p = S.prices[id];
    const chg = p?.usd_24h_change;
    const sig = S.signals[id];
    const sel = S.selCoin === id;
    return `<div data-coin="${id}" class="coin-item ${sel?'selected':''}" 
      style="color:${coin.color};${sel?`background:${coin.color}11;border-left-color:${coin.color}`:'border-left-color:transparent'}"
      onclick="selectCoin('${id}')">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:3px">
        <span style="font-weight:700;font-size:12px">${coin.symbol}</span>
        ${sig ? `<span style="font-size:9px;padding:1px 4px;font-weight:700;background:${sig.signal==='BUY'?'#00d88a22':sig.signal==='SELL'?'#ff335522':'#ffc30022'};color:${sig.signal==='BUY'?'#00d88a':sig.signal==='SELL'?'#ff3355':'#ffc300'}">${sig.signal}</span>` : ''}
      </div>
      <div style="color:#c0c4e0;font-size:11px">${p ? fmtUSD(p.usd) : '—'}</div>
      <div style="font-size:10px;color:${(chg||0)>=0?'#00d88a':'#ff3355'}">${chg!=null?sign(chg)+fmt(chg)+'%':'—'}</div>
    </div>`;
  }).join('');
}

function renderMarketTab() {
  const id = S.selCoin;
  const coin = COINS[id];
  const p = S.prices[id];

  // Holdings display
  const holdings = Object.entries(S.portfolio).map(([sym, amt]) => {
    if (sym==='USDT') return `<div class="panel" style="padding:8px 12px;margin-bottom:0">
      <div class="yellow" style="font-size:10px">USDT</div>
      <div style="font-size:13px;font-weight:700">${fmtUSD(amt)}</div>
    </div>`;
    if ((amt||0) < 0.000001) return '';
    const cid = COIN_IDS.find(i => COINS[i].symbol===sym);
    const val = cid && S.prices[cid] ? amt * S.prices[cid].usd : 0;
    return `<div class="panel" style="padding:8px 12px;margin-bottom:0">
      <div style="color:${cid?COINS[cid].color:'#4a4e6a'};font-size:10px">${sym}</div>
      <div style="font-size:11px;font-weight:700">${fmt(amt,6)}</div>
      <div class="dim" style="font-size:10px">${fmtUSD(val)}</div>
    </div>`;
  }).filter(Boolean).join('');

  el('main-content').innerHTML = `
    <!-- Coin header -->
    <div class="panel" style="border-left:3px solid ${coin.color}">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:8px">
        <div>
          <span style="font-size:18px;font-weight:700;color:${coin.color}">${coin.symbol}</span>
          <span class="dim" style="margin-left:8px">${coin.name}</span>
        </div>
        ${p ? `<div style="text-align:right">
          <div style="font-size:20px;font-weight:700">${fmtUSD(p.usd)}</div>
          <div style="color:${(p.usd_24h_change||0)>=0?'#00d88a':'#ff3355'}">${sign(p.usd_24h_change||0)}${fmt(p.usd_24h_change||0)}% 24h</div>
        </div>` : '<div class="dim">Loading...</div>'}
      </div>
      ${p?.usd_market_cap ? `<div class="dim" style="font-size:10px">Mkt Cap: ${fmtUSD(p.usd_market_cap/1e9)}B</div>` : ''}
    </div>

    <!-- Exchange prices -->
    <div style="margin-bottom:10px">
      <div class="dim" style="font-size:9px;letter-spacing:.1em;margin-bottom:6px">EXCHANGE PRICES</div>
      <div style="display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:6px">
        ${EXCHANGES.map(ex => {
          const ep = p ? exPrice(p.usd, ex) : null;
          return `<div class="panel" style="padding:7px 10px;margin-bottom:0">
            <div class="dim" style="font-size:9px">${ex}</div>
            <div style="font-size:11px;margin-top:2px">${ep ? fmtUSD(ep) : '—'}</div>
          </div>`;
        }).join('')}
      </div>
    </div>

    <!-- Trade controls -->
    <div class="panel">
      <div class="dim" style="font-size:9px;letter-spacing:.1em;margin-bottom:10px">PAPER TRADE</div>
      <div style="display:flex;gap:6px;align-items:center;margin-bottom:10px;flex-wrap:wrap">
        <span class="dim">USD:</span>
        <input type="number" value="${S.amount}" oninput="S.amount=this.value" 
          style="background:#07091c;border:1px solid #1e2147;color:#c0c4e0;padding:4px 8px;width:90px">
        ${['250','500','1000','2000'].map(a => `<button onclick="S.amount='${a}';this.parentElement.querySelector('input').value='${a}'" 
          style="background:transparent;border:1px solid #1e2147;color:#4a4e6a;padding:3px 8px">${a}</button>`).join('')}
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">
        <button class="btn-buy" onclick="executeTrade('${id}','BUY',parseFloat(S.amount)||0)">▲ BUY ${coin.symbol}</button>
        <button class="btn-sell" onclick="executeTrade('${id}','SELL',parseFloat(S.amount)||0)">▼ SELL ${coin.symbol}</button>
      </div>
    </div>

    <!-- Holdings -->
    <div>
      <div class="dim" style="font-size:9px;letter-spacing:.1em;margin-bottom:6px">HOLDINGS</div>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(100px,1fr));gap:6px">
        ${holdings || '<span class="dim" style="font-size:11px">No holdings</span>'}
      </div>
    </div>
  `;
}

function renderSignalsTab() {
  const id = S.selCoin;
  const coin = COINS[id];
  const sig = S.signals[id];

  el('main-content').innerHTML = `
    <!-- Auto-trader -->
    <div class="panel" style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
      <div>
        <div style="font-weight:700;margin-bottom:3px">AUTO-TRADER</div>
        <div class="dim" style="font-size:10px">Confidence ≥75% triggers auto-execution | Max 20% portfolio per trade</div>
      </div>
      <button onclick="toggleAuto()" style="padding:8px 14px;background:${S.autoTrade?'#ff335522':'#00d88a22'};border:1px solid ${S.autoTrade?'#ff3355':'#00d88a'};color:${S.autoTrade?'#ff3355':'#00d88a'};font-weight:700;letter-spacing:.08em">
        ${S.autoTrade ? '■ STOP' : '▶ START'}
      </button>
    </div>

    <!-- Signal for selected coin -->
    <div class="panel" style="border-left:3px solid ${coin.color};margin-bottom:10px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">
        <span style="color:${coin.color};font-weight:700">AI SIGNAL — ${coin.symbol}</span>
        <button onclick="genSignal('${id}')" ${S.loadingSig?'disabled':''} 
          style="background:#4d9fff22;border:1px solid #4d9fff;color:#4d9fff;padding:5px 12px;font-weight:700;letter-spacing:.08em">
          ${S.loadingSig ? '⟳ ANALYZING...' : '⟁ GENERATE'}
        </button>
      </div>
      ${sig ? `
        <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;margin-bottom:12px">
          <div style="text-align:center">
            <div class="dim" style="font-size:9px;margin-bottom:4px">SIGNAL</div>
            <div style="font-size:22px;font-weight:700;color:${sig.signal==='BUY'?'#00d88a':sig.signal==='SELL'?'#ff3355':'#ffc300'}">${sig.signal}</div>
          </div>
          <div style="text-align:center">
            <div class="dim" style="font-size:9px;margin-bottom:4px">CONFIDENCE</div>
            <div style="font-size:20px;font-weight:700;color:${sig.confidence>=75?'#00d88a':sig.confidence>=50?'#ffc300':'#ff3355'}">${sig.confidence}%</div>
            <div style="height:3px;background:#1e2147;margin-top:4px;border-radius:2px">
              <div style="height:100%;width:${sig.confidence}%;background:${sig.confidence>=75?'#00d88a':'#ffc300'};border-radius:2px"></div>
            </div>
          </div>
          <div style="text-align:center">
            <div class="dim" style="font-size:9px;margin-bottom:4px">RISK</div>
            <div style="font-size:16px;font-weight:700;color:${(sig.risk||sig.riskLevel)==='low'?'#00d88a':(sig.risk||sig.riskLevel)==='medium'?'#ffc300':'#ff3355'}">${(sig.risk||sig.riskLevel||'?').toUpperCase()}</div>
          </div>
        </div>
        <div style="background:#07091c;padding:8px 12px;border-left:2px solid ${coin.color};font-size:11px;margin-bottom:10px">${sig.reason}</div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">
          <button class="btn-buy" onclick="executeTrade('${id}','BUY',parseFloat(S.amount)||500)">▲ MANUAL BUY</button>
          <button class="btn-sell" onclick="executeTrade('${id}','SELL',parseFloat(S.amount)||500)">▼ MANUAL SELL</button>
        </div>
      ` : `<div class="dim" style="text-align:center;padding:20px;font-size:11px">Click GENERATE to get AI analysis for ${coin.symbol}</div>`}
    </div>

    <!-- All signals -->
    <div>
