import { useState, useEffect, useRef, useCallback } from "react";

// ══════════════════════════════════════════
//  CONSTANTS
// ══════════════════════════════════════════

const COINS = {
  bitcoin: { symbol: "BTC", name: "Bitcoin", color: "#F7931A" },
  ethereum: { symbol: "ETH", name: "Ethereum", color: "#627EEA" },
  cronos: { symbol: "CRO", name: "Cronos", color: "#00aaff" },
  solana: { symbol: "SOL", name: "Solana", color: "#9945FF" },
  "avalanche-2": { symbol: "AVAX", name: "Avalanche", color: "#E84142" },
  arbitrum: { symbol: "ARB", name: "Arbitrum", color: "#28A0F0" },
  optimism: { symbol: "OP", name: "Optimism", color: "#FF0420" },
};

const EXCHANGES = ["Binance", "Kraken", "Coinbase", "KuCoin"];
const STARTING_BALANCE = 10000;
const TRADE_FEE = 0.001; // 0.1%
const MAX_POSITION_PCT = 0.2; // 20% of portfolio
const STOP_LOSS_PCT = 0.05; // 5%
const TAKE_PROFIT_PCT = 0.10; // 10%

// Exchange price variation seeds (deterministic per update)
const EXCHANGE_SEEDS = { Binance: 0.002, Kraken: -0.003, Coinbase: 0.001, KuCoin: -0.001 };

// ══════════════════════════════════════════
//  HELPERS
// ══════════════════════════════════════════

const fmt = (n, d = 2) => n?.toLocaleString("en-US", { minimumFractionDigits: d, maximumFractionDigits: d }) ?? "—";
const fmtUSD = (n) => `$${fmt(n)}`;
const fmtPct = (n) => `${n >= 0 ? "+" : ""}${fmt(n)}%`;

function getExchangePrice(basePrice, exchange, coinId) {
  // Deterministic variation per exchange + coin combo
  const seed = EXCHANGE_SEEDS[exchange] ?? 0;
  const coinSeed = coinId.charCodeAt(0) / 1000;
  const variation = seed + coinSeed * 0.0001;
  return basePrice * (1 + variation);
}

function findArbitrageOps(prices) {
  const ops = [];
  Object.entries(prices).forEach(([coinId, data]) => {
    if (!data?.usd) return;
    const basePrice = data.usd;

    const exPrices = EXCHANGES.map(ex => ({
      exchange: ex,
      price: getExchangePrice(basePrice, ex, coinId)
    }));

    const minEx = exPrices.reduce((a, b) => a.price < b.price ? a : b);
    const maxEx = exPrices.reduce((a, b) => a.price > b.price ? a : b);

    const spread = (maxEx.price - minEx.price) / minEx.price;
    const netProfit = spread - TRADE_FEE * 2;

    if (netProfit > 0.001) { // > 0.1% net
      ops.push({
        coinId,
        symbol: COINS[coinId]?.symbol ?? coinId,
        buyFrom: minEx.exchange,
        buyPrice: minEx.price,
        sellTo: maxEx.exchange,
        sellPrice: maxEx.price,
        spread: spread * 100,
        netProfit: netProfit * 100,
        profitable: netProfit > 0.002,
      });
    }
  });
  return ops.sort((a, b) => b.netProfit - a.netProfit);
}

