      const tradeAmt = Math.min(parseFloat(amount) || 500, maxAmount);
      if (sig.signal === "BUY") trade(coinId, "BUY", tradeAmt);
      else if (sig.signal === "SELL") trade(coinId, "SELL", tradeAmt);
    });
