import { useState, useEffect, useRef } from "react";

const ANTHROPIC_API = "https://api.anthropic.com/v1/messages";

// ─── Phone number utilities ──────────────────────────────────────────────────
function parsePhoneNumber(raw) {
  const digits = raw.replace(/\D/g, "");
  const e164 = digits.startsWith("44") ? `+${digits}` : digits.startsWith("0") ? `+44${digits.slice(1)}` : `+${digits}`;

  const countryMap = {
    "1": { country: "United States / Canada", region: "NANP", flag: "🇺🇸" },
    "44": { country: "United Kingdom", region: "Ofcom", flag: "🇬🇧" },
    "353": { country: "Ireland", region: "ComReg", flag: "🇮🇪" },
    "49": { country: "Germany", region: "BNetzA", flag: "🇩🇪" },
    "33": { country: "France", region: "ARCEP", flag: "🇫🇷" },
    "34": { country: "Spain", region: "CNMC", flag: "🇪🇸" },
    "39": { country: "Italy", region: "AGCOM", flag: "🇮🇹" },
    "31": { country: "Netherlands", region: "ACM", flag: "🇳🇱" },
    "48": { country: "Poland", region: "UKE", flag: "🇵🇱" },
    "7": { country: "Russia", region: "Roskomnadzor", flag: "🇷🇺" },
    "86": { country: "China", region: "MIIT", flag: "🇨🇳" },
    "81": { country: "Japan", region: "MIC", flag: "🇯🇵" },
    "91": { country: "India", region: "TRAI", flag: "🇮🇳" },
    "61": { country: "Australia", region: "ACMA", flag: "🇦🇺" },
    "27": { country: "South Africa", region: "ICASA", flag: "🇿🇦" },
  };

  let countryInfo = null;
  let cc = "";
  for (const code of ["1", "7", "27", "31", "33", "34", "39", "44", "48", "49", "61", "81", "86", "91", "353"]) {
    const stripped = e164.replace("+", "");
    if (stripped.startsWith(code)) { cc = code; countryInfo = countryMap[code]; break; }
  }

  // UK-specific number analysis
  let ukAnalysis = null;
  if (cc === "44") {
    const national = e164.replace("+44", "0");
    const prefix3 = national.slice(0, 3);
    const prefix4 = national.slice(0, 4);
    const prefix5 = national.slice(0, 5);

    const ukPrefixes = {
      "07": { type: "Mobile", carriers: ["EE", "O2", "Vodafone", "Three", "Virgin Mobile"] },
      "01": { type: "Geographic (Local)", carriers: ["BT", "Virgin Media", "TalkTalk"] },
      "02": { type: "Geographic (City)", carriers: ["BT", "Virgin Media"] },
      "03": { type: "Non-Geographic (Non-Profit/Public)", carriers: ["Various"] },
      "08": { type: "Non-Geographic (Special Rate)", carriers: ["Various"] },
      "09": { type: "Premium Rate", carriers: ["Various"] },
    };

    const mobileRanges = {
      "0771": "EE (formerly T-Mobile)", "0772": "EE", "0773": "EE", "0774": "EE",
      "0775": "O2", "0776": "O2", "0777": "O2", "0778": "Vodafone",
      "0779": "Vodafone", "0780": "Vodafone", "0781": "Vodafone",
      "0782": "Three", "0783": "Three", "0784": "Three",
      "0785": "EE", "0786": "EE", "0787": "O2",
      "0788": "O2", "0789": "O2", "0790": "Vodafone",
      "0791": "Vodafone", "0792": "Vodafone", "0793": "Vodafone",
      "0794": "EE", "0795": "EE", "0796": "EE",
      "0797": "O2", "0798": "O2", "0799": "Three",
      "0740": "Three", "0741": "Three", "0742": "Three",
      "0743": "Three", "0744": "Three", "0745": "Three",
      "0746": "Three", "0747": "Three", "0748": "Tesco Mobile",
      "0749": "Three", "0750": "Three", "0751": "Three",
      "0752": "O2", "0753": "O2", "0754": "O2",
      "0755": "O2", "0756": "O2", "0757": "O2",
      "0758": "EE", "0759": "EE",
    };

    const baseType = ukPrefixes[prefix3] || ukPrefixes[prefix4.slice(0,2)] || { type: "Unknown", carriers: [] };
    const inferredCarrier = mobileRanges[prefix4] || null;

    // Geographic areas for 01/02 numbers
    const geoAreas = {
      "0113": "Leeds", "0114": "Sheffield", "0115": "Nottingham", "0116": "Leicester",
      "0117": "Bristol", "0118": "Reading", "0121": "Birmingham", "0131": "Edinburgh",
      "0141": "Glasgow", "0151": "Liverpool", "0161": "Manchester", "0171": "London (old)",
      "0191": "Newcastle", "0207": "London (Central)", "0208": "London (Greater)",
      "0203": "London (New)", "0204": "London (New)", "0121": "Birmingham",
      "01224": "Aberdeen", "01382": "Dundee", "01292": "Ayr", "01463": "Inverness",
    };

    const geoArea = geoAreas[prefix4] || geoAreas[prefix5] || null;

    ukAnalysis = {
      national,
      e164,
      type: baseType.type,
      carriers: baseType.carriers,
      inferredCarrier,
      geoArea,
      length: national.length,
      valid: national.length === 11,
    };
  }

  return { raw, e164, cc, countryInfo, ukAnalysis, digits };
}

// ─── Scan log line component ─────────────────────────────────────────────────
function LogLine({ text, delay = 0 }) {
  const [visible, setVisible] = useState(false);
  useEffect(() => { const t = setTimeout(() => setVisible(true), delay); return () => clearTimeout(t); }, [delay]);
  return visible ? (
    <div style={{ fontFamily: "monospace", fontSize: "11px", color: "#4ade80", lineHeight: "1.6", opacity: 0.85 }}>
      <span style={{ color: "#22d3ee" }}>[SYS]</span> {text}
    </div>
  ) : null;
}

// ─── Result card ─────────────────────────────────────────────────────────────
function DataCard({ title, icon, children, accent = "#4ade80" }) {
  return (
    <div style={{
      background: "rgba(0,0,0,0.6)", border: `1px solid ${accent}33`,
      borderLeft: `3px solid ${accent}`, borderRadius: "4px",
      padding: "14px 16px", marginBottom: "12px",
    }}>
      <div style={{ fontFamily: "monospace", fontSize: "11px", color: accent, marginBottom: "8px", letterSpacing: "2px", textTransform: "uppercase" }}>
        {icon} {title}
      </div>
      {children}
    </div>
  );
}

function Field({ label, value, highlight = false }) {
  if (!value) return null;
  return (
    <div style={{ display: "flex", gap: "12px", marginBottom: "4px", flexWrap: "wrap" }}>
      <span style={{ fontFamily: "monospace", fontSize: "11px", color: "#6b7280", minWidth: "160px" }}>{label}:</span>
      <span style={{ fontFamily: "monospace", fontSize: "11px", color: highlight ? "#fbbf24" : "#e2e8f0", flex: 1 }}>{value}</span>
    </div>
  );
}

// ─── Main app ─────────────────────────────────────────────────────────────────
export default function CallerOSINT() {
  const [input, setInput] = useState("");
  const [phase, setPhase] = useState("idle"); // idle | scanning | done | error
  const [parsed, setParsed] = useState(null);
  const [aiReport, setAiReport] = useState("");
  const [logs, setLogs] = useState([]);
  const [streaming, setStreaming] = useState(false);
  const reportRef = useRef("");
  const logRef = useRef(null);

  const addLog = (msg) => setLogs(prev => [...prev, { msg, id: Date.now() + Math.random() }]);

  const runInvestigation = async () => {
    if (!input.trim()) return;
    const phoneData = parsePhoneNumber(input.trim());
    setParsed(phoneData);
    setPhase("scanning");
    setAiReport("");
    setLogs([]);
    reportRef.current = "";

    addLog(`Target acquired: ${phoneData.e164}`);
    addLog(`Country code detected: +${phoneData.cc}`);
    addLog(`Initiating OSINT sweep...`);
    addLog(`Querying public telecoms databases...`);
    addLog(`Cross-referencing number range allocations...`);
    addLog(`Engaging AI analyst with live web search...`);

    const systemPrompt = `You are an expert telecoms OSINT investigator. Analyse phone numbers and compile comprehensive public intelligence reports. 

    Structure your report with clear sections:
    1. NUMBER ANALYSIS - technical breakdown
    2. CARRIER / OPERATOR INTELLIGENCE - who owns this number range, MVNO possibilities  
    3. GEOGRAPHIC INTELLIGENCE - location data, area codes, regional patterns
    4. REGULATORY INTELLIGENCE - which regulator oversees this, number portability status possibilities
    5. RISK ASSESSMENT - spam/scam probability based on public reports, any known associations
    6. OSINT SURFACE - what public information might be findable, social media handles patterns, business directories
    7. INVESTIGATOR NOTES - methodology notes and confidence ratings

    Be factual, cite specific details. Use web search to find any public reports, spam databases, or business registrations associated with this number.
    Format as a professional intelligence briefing. Be thorough but concise.`;

    const userPrompt = `INVESTIGATE THIS NUMBER: ${phoneData.e164}

    Pre-parsed data:
    - E.164 format: ${phoneData.e164}
    - Country: ${phoneData.countryInfo?.country || "Unknown"}
    - UK Analysis: ${JSON.stringify(phoneData.ukAnalysis || {})}

    Search for:
    1. Any public spam/scam reports for this number (check who-called-me, 800notes, tellows, etc.)
    2. Business directory listings
    3. Social media associations
    4. Any news articles mentioning this number
    5. UK Ofcom number range data
    6. Whether this number has been reported for fraud/scam/robocall

    Compile a full OSINT briefing.`;

    try {
      const res = await fetch(ANTHROPIC_API, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-20250514",
          max_tokens: 1500,
          stream: true,
          system: systemPrompt,
          tools: [{ type: "web_search_20250305", name: "web_search" }],
          messages: [{ role: "user", content: userPrompt }],
        }),
      });

      if (!res.ok) throw new Error(`API error ${res.status}`);

      setStreaming(true);
      setPhase("done");
      addLog(`AI analyst online — streaming intelligence report...`);

      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let buffer = "";

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split("\n");
        buffer = lines.pop();

        for (const line of lines) {
          if (!line.startsWith("data:")) continue;
          const data = line.slice(5).trim();
          if (data === "[DONE]") continue;
          try {
            const evt = JSON.parse(data);
            if (evt.type === "content_block_delta" && evt.delta?.type === "text_delta") {
              reportRef.current += evt.delta.text;
              setAiReport(reportRef.current);
            }
          } catch {}
        }
      }
      setStreaming(false);
      addLog(`Investigation complete. Report compiled.`);
    } catch (err) {
      setPhase("error");
      setAiReport(`Investigation error: ${err.message}`);
      addLog(`ERROR: ${err.message}`);
    }
  };

  return (
    <div style={{
      minHeight: "100vh", background: "#020c06",
      backgroundImage: "radial-gradient(ellipse at 20% 50%, #0d2818 0%, transparent 60%), radial-gradient(ellipse at 80% 20%, #0a1628 0%, transparent 50%)",
      fontFamily: "monospace", color: "#e2e8f0", padding: "0",
    }}>
      {/* Scanline overlay */}
      <div style={{
        position: "fixed", inset: 0, pointerEvents: "none", zIndex: 10,
        backgroundImage: "repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(0,0,0,0.03) 2px, rgba(0,0,0,0.03) 4px)",
      }} />

      <div style={{ maxWidth: "900px", margin: "0 auto", padding: "24px 16px" }}>
        {/* Header */}
        <div style={{ textAlign: "center", marginBottom: "32px" }}>
          <div style={{ fontSize: "10px", color: "#22d3ee", letterSpacing: "6px", marginBottom: "8px" }}>
            ◈ TELECOMS INTELLIGENCE UNIT ◈
          </div>
          <h1 style={{
            fontSize: "clamp(20px, 4vw, 32px)", fontWeight: 900,
            color: "#4ade80", letterSpacing: "3px", margin: "0 0 4px",
            textShadow: "0 0 30px #4ade8055",
          }}>
            CALLER-ID OSINT
          </h1>
          <div style={{ fontSize: "10px", color: "#6b7280", letterSpacing: "4px" }}>
            OPEN SOURCE INTELLIGENCE PLATFORM v2.1
          </div>
          <div style={{ width: "120px", height: "1px", background: "linear-gradient(90deg, transparent, #4ade80, transparent)", margin: "12px auto 0" }} />
        </div>

        {/* Input panel */}
        <div style={{
          background: "rgba(0,0,0,0.7)", border: "1px solid #4ade8033",
          borderRadius: "6px", padding: "20px", marginBottom: "20px",
        }}>
          <div style={{ fontSize: "10px", color: "#22d3ee", letterSpacing: "3px", marginBottom: "12px" }}>
            ◉ TARGET ACQUISITION
          </div>
          <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
            <input
              value={input}
              onChange={e => setInput(e.target.value)}
              onKeyDown={e => e.key === "Enter" && runInvestigation()}
              placeholder="e.g. 447554657898 or +44 7554 657898 or 07554657898"
              style={{
                flex: 1, minWidth: "240px", background: "rgba(74,222,128,0.05)",
                border: "1px solid #4ade8044", borderRadius: "4px",
                color: "#4ade80", fontFamily: "monospace", fontSize: "13px",
                padding: "10px 14px", outline: "none",
                caretColor: "#4ade80",
              }}
            />
            <button
              onClick={runInvestigation}
              disabled={phase === "scanning"}
              style={{
                background: phase === "scanning" ? "transparent" : "#4ade8022",
                border: "1px solid #4ade80",
                color: "#4ade80", fontFamily: "monospace", fontSize: "11px",
                letterSpacing: "2px", padding: "10px 20px", borderRadius: "4px",
                cursor: phase === "scanning" ? "not-allowed" : "pointer",
                opacity: phase === "scanning" ? 0.5 : 1,
              }}
            >
              {phase === "scanning" ? "SCANNING..." : "INVESTIGATE ▶"}
            </button>
          </div>
          <div style={{ fontSize: "10px", color: "#6b7280", marginTop: "8px" }}>
            Accepts: E.164 (+447...) • National (07...) • Raw digits (447...)
          </div>
        </div>

        {/* Scan log */}
        {logs.length > 0 && (
          <div style={{
            background: "rgba(0,0,0,0.8)", border: "1px solid #22d3ee22",
            borderRadius: "4px", padding: "12px 14px", marginBottom: "16px",
            maxHeight: "120px", overflowY: "auto",
          }} ref={logRef}>
            {logs.map((l, i) => (
              <LogLine key={l.id} text={l.msg} delay={i * 180} />
            ))}
            {phase === "scanning" && (
              <div style={{ fontFamily: "monospace", fontSize: "11px", color: "#4ade80", marginTop: "4px" }}>
                <span style={{ animation: "pulse 1s infinite" }}>█</span>
              </div>
            )}
          </div>
        )}

        {/* Parsed phone data */}
        {parsed && phase !== "idle" && (
          <DataCard title="Number Decomposition" icon="◈" accent="#22d3ee">
            <Field label="E.164 Format" value={parsed.e164} highlight />
            <Field label="Country" value={parsed.countryInfo ? `${parsed.countryInfo.flag} ${parsed.countryInfo.country}` : "Unknown"} />
            <Field label="Regulator" value={parsed.countryInfo?.region} />
            {parsed.ukAnalysis && <>
              <Field label="National Format" value={parsed.ukAnalysis.national} />
              <Field label="Number Type" value={parsed.ukAnalysis.type} highlight />
              <Field label="Inferred Carrier" value={parsed.ukAnalysis.inferredCarrier || "Unknown (may be ported)"} />
              <Field label="Geographic Area" value={parsed.ukAnalysis.geoArea || "N/A (mobile or non-geo)"} />
              <Field label="Digit Count" value={`${parsed.ukAnalysis.length} digits — ${parsed.ukAnalysis.valid ? "✓ VALID LENGTH" : "⚠ INVALID LENGTH"}`} />
            </>}
          </DataCard>
        )}

        {/* AI Intelligence Report */}
        {(aiReport || streaming) && (
          <DataCard title="AI Intelligence Report" icon="◉" accent="#4ade80">
            <div style={{
              fontFamily: "monospace", fontSize: "11px", color: "#cbd5e1",
              lineHeight: "1.7", whiteSpace: "pre-wrap", wordBreak: "break-word",
            }}>
              {aiReport}
              {streaming && <span style={{ color: "#4ade80", animation: "blink 1s infinite" }}>█</span>}
            </div>
          </DataCard>
        )}

        {/* Disclaimer */}
        <div style={{
          marginTop: "20px", padding: "12px", border: "1px solid #ff444422",
          borderRadius: "4px", background: "rgba(255,68,68,0.05)",
        }}>
          <div style={{ fontSize: "10px", color: "#f87171", letterSpacing: "2px", marginBottom: "4px" }}>⚠ LEGAL NOTICE</div>
          <div style={{ fontSize: "10px", color: "#6b7280", lineHeight: "1.6" }}>
            This tool queries only publicly available information and open-source databases. No private data is accessed.
            Use only for legitimate purposes including fraud investigation, scam reporting, and personal safety.
            Misuse to harass or stalk individuals is illegal under the UK Protection of Freedoms Act 2012 and Harassment Act 1997.
          </div>
        </div>
      </div>

      <style>{`
        @keyframes pulse { 0%,100%{opacity:1} 50%{opacity:0} }
        @keyframes blink { 0%,100%{opacity:1} 50%{opacity:0} }
        input::placeholder { color: #4ade8044; }
        * { box-sizing: border-box; }
        ::-webkit-scrollbar { width: 4px; }
        ::-webkit-scrollbar-track { background: #020c06; }
        ::-webkit-scrollbar-thumb { background: #4ade8044; border-radius: 2px; }
      `}</style>
    </div>
  );
}

