function ProfitBadge({ pct }) {
  const good = pct >= 1;
  const ok   = pct >= 0.5;
  const color = good ? "var(--color-text-success)" : ok ? "var(--color-text-warning)" : "var(--color-text-secondary)";
  const bg    = good ? "var(--color-background-success)" : ok ? "var(--color-background-warning)" : "var(--color-background-secondary)";
  return (
    <span style={{
      fontSize: 13, fontWeight: 500, fontFamily: "var(--font-mono)",
      color, background: bg,
      borderRadius: "var(--border-radius-md)",
      padding: "2px 8px",
