        {["all",...tokens].map(t => (
          <button key={t} onClick={() => setToken(t)} style={{
            fontSize: 12, padding: "4px 12px",
            borderRadius: "var(--border-radius-md)",
            border: token === t ? "1.5px solid var(--color-border-info)" : "0.5px solid var(--color-border-secondary)",
