function AnalysisTab({ opportunities, prices }) {
  const [analysis, setAnalysis] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const top5 = opportunities.slice(0, 5);

  const priceSummary = Object.entries(prices).map(([token, chains]) => {
    const chainStr = Object.entries(chains)
      .map(([c, d]) => `${c}=$${d.price?.toLocaleString() ?? d.price_usd?.toLocaleString()}`)
      .join(", ");
    return `${token}: ${chainStr}`;
  }).join("\n");

  const oppStr = top5.map((o, i) => 
    `${i+1}. ${o.token} BUY ${o.buyChain || o.buy_chain} @$${(o.buyPrice ?? o.buy_price)?.toLocaleString()} → SELL ${o.sellChain || o.sell_chain} @$${(o.sellPrice ?? o.sell_price)?.toLocaleString()} | net=${(o.netPct ?? o.net_pct)?.toFixed(2)}% ($${(o.netUsd ?? o.net_usd_1k)?.toFixed(2)} per $1k)`
  ).join("\n");

  const prompt = `You are an expert crypto arbitrage analyst for a multi-chain automated trading bot.

LIVE MARKET DATA (${new Date().toUTCString()}):
${priceSummary}

TOP ARBITRAGE OPPORTUNITIES DETECTED:
${oppStr}

Analyse these and provide:
1. RECOMMENDATION for each (EXECUTE / WATCH / SKIP) with brief reasoning
2. RISK FACTORS: liquidity depth, slippage, gas spike risk
3. PRIORITY ORDER for limited capital
4. KEY INSIGHT: one non-obvious observation from this data

Keep it concise and actionable.`;

  const runAnalysis = async () => {
    if (top5.length === 0) {
      setError("No opportunities to analyse. Load data first.");
      return;
    }
    setLoading(true);
    setAnalysis("");
    setError("");

    try {
      const resp = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-20250514",
          max_tokens: 1000,
          messages: [{ role: "user", content: prompt }],
        }),
      });
      const data = await resp.json();
      if (data.content) {
        setAnalysis(data.content.filter(b => b.type === "text").map(b => b.text).join(""));
      } else {
        setError(data.error?.message || "Unexpected response");
      }
    } catch (e) {
      setError(`Request failed: ${e.message}`);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <div style={{
        background: "var(--color-background-secondary)",
        borderRadius: "var(--border-radius-lg)",
        padding: "1rem",
        marginBottom: "1rem",
        fontSize: 13,
        color: "var(--color-text-secondary)",
      }}>
        <div style={{ fontWeight: 500, marginBottom: 4, color: "var(--color-text-primary)" }}>Prompt preview</div>
        <pre style={{ fontFamily: "var(--font-mono)", fontSize: 11, whiteSpace: "pre-wrap", margin: 0, maxHeight: 120, overflow: "auto" }}>
          {prompt.slice(0, 400)}...
        </pre>
      </div>

      <button
        onClick={runAnalysis}
        disabled={loading}
        style={{ marginBottom: "1rem", padding: "8px 20px", cursor: loading ? "default" : "pointer" }}
      >
        {loading ? "Analysing..." : `Analyse ${top5.length} opportunities ↗`}
      </button>

      {error && (
        <div style={{ color: "var(--color-text-danger)", fontSize: 13, marginBottom: "1rem", padding: "0.75rem", background: "var(--color-background-danger)", borderRadius: "var(--border-radius-md)" }}>
          {error}
        </div>
      )}

      {analysis && (
        <div style={{
          background: "var(--color-background-primary)",
          border: "0.5px solid var(--color-border-tertiary)",
          borderRadius: "var(--border-radius-lg)",
          padding: "1.25rem",
        }}>
          <div style={{ fontSize: 14, fontWeight: 500, marginBottom: "0.75rem" }}>AI analysis result</div>
          <pre style={{ fontFamily: "var(--font-sans)", fontSize: 13, whiteSpace: "pre-wrap", margin: 0, lineHeight: 1.7, color: "var(--color-text-primary)" }}>
            {analysis}
          </pre>
        </div>
      )}
    </div>
  );
}

