    description:
      "Deep reasoning on market structure, drawdown risk, regime classification and peer rotation. Writes and validates the Python pipeline code. Primary architect of the data ingestion and feature modules.",
    responsibilities: [
      "Market regime classification (risk_on / neutral / risk_off)",
      "Peer rotation signals (rotate_in / hold / rotate_out)",
      "On-chain risk scoring (SOPR, MVRV)",
      "Code generation and validation for all modules",
      "BTC dominance regime analysis",
    ],
    model: "Claude Sonnet 4.6",
    api: "Anthropic API / Claude.ai",
  },
  {
    id: "gpt",
    name: "GPT-4o",
    role: "Macro & Sentiment Analyst",
