    description:
      "Processes macro news, earnings calendar, Fed statements, and broad market sentiment. Provides probability-weighted narrative context for each trade setup.",
    responsibilities: [
      "News sentiment scoring",
      "Macro event calendar awareness",
      "Fear & Greed index integration",
      "Narrative risk flagging",
      "Web search for breaking catalyst events",
    ],
    model: "GPT-4o",
    api: "OpenAI API (key in .env)",
  },
  {
    id: "grok",
