    color: "#ffd700",
    icon: "📡",
    description:
      "Real-time social signal extraction from X (Twitter). Detects whale wallet activity, trending narratives, influencer pumps, and abnormal volume spikes before they hit price.",
    responsibilities: [
      "X/Twitter trend monitoring",
      "Whale alert cross-referencing",
      "Influencer signal detection",
      "Volume anomaly flagging",
      "Meme coin early-warning system",
    ],
    model: "Grok-2",
    api: "xAI API (OpenRouter)",
  },
  {
    id: "gemini",
    name: "Gemini",
    role: "Technical Pattern Recognition",
    badge: "SPECIALIST",
    color: "#c084fc",
    icon: "🔍",
    description:
      "Chart pattern detection and multi-timeframe technical analysis. Validates Pine Script signals from TradingView before they reach execution. Also used for Trading Strategy Automator skill benchmarking.",
    responsibilities: [
      "OHLCV pattern recognition",
      "ORB breakout validation",
      "Multi-timeframe confluence checking",
      "Pine Script webhook signal validation",
      "Comparison benchmarking vs Claude strategy outputs",
    ],
    model: "Gemini 1.5 Pro",
    api: "Google AI API (key in .env)",
  },
];

const dataSources = [
  {
    name: "CoinMarketCap",
    type: "Historical Price + Market Cap",
    key: "Required (CMC_API_KEY in .env)",
    output: "price, marketcap, volume_24h, rank",
    file: "data/ingest/cmc_client.py",
    color: "#00d4ff",
  },
  {
    name: "CoinGecko",
    type: "Historical Price Backup",
    key: "Free tier (no key needed)",
    output: "price, market_cap, total_volume",
    file: "data/ingest/coingecko_client.py",
    color: "#7fff6b",
  },
  {
    name: "Glassnode",
    type: "On-Chain Metrics",
    key: "Required (GLASSNODE_API_KEY in .env)",
    output: "SOPR, MVRV, NVT, Active Addresses",
