  {
    name: "TradingView",
    type: "Pine Script Webhooks",
    key: "TradingView account",
    output: "JSON signals → 3Commas / PineConnector",
    file: "strategies/pine/*.pine",
    color: "#c084fc",
  },
];

const modules = [
  {
    path: "data/ingest/",
    files: [
      "cmc_client.py",
      "coingecko_client.py",
      "glassnode_client.py",
      "btc_dominance.py",
      "merge_sources.py",
      "pipeline_daily.py",
    ],
    desc: "Data ingestion — fetch, normalise, merge, cache to Parquet",
    status: "built",
  },
  {
    path: "data/feeds/",
    files: ["composite_feed.py"],
    desc: "CompositeFeed — assembles MarketContext from cached data",
    status: "built",
  },
  {
    path: "intelligence/features/",
    files: [
      "pair_features.py",
      "peer_features.py",
      "onchain_features.py",
      "ratio_features.py",
    ],
    desc: "Feature builders — return, drawdown, peer rank, on-chain, CRO/BTC ratio",
    status: "built",
  },
  {
    path: "intelligence/agents/",
    files: [
      "profit_maximiser.py",
      "risk_filter.py",
      "regime_switcher.py",
    ],
    desc: "Decision agents — overweight/underweight, leverage, regime switching",
    status: "in progress",
  },
  {
    path: "execution/",
    files: ["paper_trade.py", "live_trade.py", "signal_router.py"],
    desc: "Execution layer — paper mode enforced by default, live requires explicit flag",
    status: "in progress",
  },
  {
    path: "strategies/pine/",
    files: ["orb_strategy.pine", "volume_price_breakout.pine"],
    desc: "TradingView Pine Script strategies with webhook output",
    status: "built",
  },
  {
    path: "dashboard/",
    files: ["App.jsx", "ArbitrageScanner.jsx", "BreakoutPanel.jsx"],
    desc: "React trading dashboard — arbitrage scan + breakout signals + auto-execution toggles",
    status: "built",
  },
  {
    path: "arbitrage/",
    files: ["multi_chain_arb.py", "dex_screener.py"],
    desc: "7-chain arbitrage — ETH, Polygon, Cronos, Arbitrum, Base, BSC, Avalanche",
    status: "built",
  },
];

const chains = [
  { name: "Ethereum", color: "#627eea", symbol: "ETH" },
  { name: "Polygon", color: "#8247e5", symbol: "MATIC" },
  { name: "Cronos", color: "#002d74", symbol: "CRO" },
  { name: "Arbitrum", color: "#12aaff", symbol: "ARB" },
  { name: "Base", color: "#0052ff", symbol: "BASE" },
  { name: "BSC", color: "#f3ba2f", symbol: "BNB" },
  { name: "Avalanche", color: "#e84142", symbol: "AVAX" },
];

const universe = ["BTC", "ETH", "CRO", "SOL", "AVAX", "ARB", "OP"];

const statusBadge = (s) => {
  const map = {
    built: { bg: "#0d2e1a", color: "#7fff6b", label: "BUILT" },
    "in progress": { bg: "#2e1a00", color: "#ffd700", label: "IN PROGRESS" },
    planned: { bg: "#1a1a2e", color: "#c084fc", label: "PLANNED" },
  };
  const st = map[s] || map.planned;
  return (
    <span
      style={{
        background: st.bg,
        color: st.color,
        border: `1px solid ${st.color}44`,
        padding: "2px 8px",
        borderRadius: 3,
        fontSize: 10,
        fontFamily: "monospace",
        fontWeight: 700,
        letterSpacing: 1,
      }}
    >
      {st.label}
    </span>
  );
};

const tabs = ["Architecture", "Agents", "Data Pipeline", "File Structure", "Chains & Universe", "Setup Guide"];

export default function App() {
  const [activeTab, setActiveTab] = useState(0);
  const [expandedAgent, setExpandedAgent] = useState(null);

  return (
    <div
      style={{
        background: COLORS.bg,
        minHeight: "100vh",
        fontFamily: "'Courier New', monospace",
        color: COLORS.text,
        padding: 0,
      }}
    >
      {/* Header */}
      <div
        style={{
          borderBottom: `1px solid ${COLORS.border}`,
          padding: "20px 28px 16px",
          background: COLORS.panel,
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 6 }}>
          <div
            style={{
              width: 10,
              height: 10,
              borderRadius: "50%",
              background: COLORS.accent3,
              boxShadow: `0 0 8px ${COLORS.accent3}`,
              animation: "pulse 2s infinite",
            }}
          />
          <span style={{ color: COLORS.dim, fontSize: 11, letterSpacing: 2 }}>
            SYSTEM REFERENCE v2.0
          </span>
          <span style={{ color: COLORS.muted, fontSize: 11 }}>•</span>
          <span style={{ color: COLORS.dim, fontSize: 11, letterSpacing: 1 }}>
            AiTradingAgent · github.com/smokey79/aitradingagentboa799
          </span>
        </div>
        <h1
          style={{
            margin: 0,
            fontSize: 22,
            fontWeight: 700,
            color: "#fff",
            letterSpacing: 1,
          }}
        >
          Multi-AI Trading Agent System
        </h1>
        <p style={{ margin: "6px 0 0", color: COLORS.dim, fontSize: 13 }}>
          Claude · Copilot · GPT-4o · Grok · Gemini — Alan J, Edinburgh
        </p>
      </div>

      {/* Tabs */}
      <div
        style={{
          display: "flex",
          gap: 0,
          borderBottom: `1px solid ${COLORS.border}`,
          background: COLORS.panel,
          overflowX: "auto",
        }}
      >
        {tabs.map((t, i) => (
          <button
            key={t}
            onClick={() => setActiveTab(i)}
            style={{
              background: activeTab === i ? COLORS.bg : "transparent",
              border: "none",
              borderBottom: activeTab === i ? `2px solid ${COLORS.accent}` : "2px solid transparent",
              color: activeTab === i ? COLORS.accent : COLORS.dim,
              padding: "12px 18px",
              cursor: "pointer",
              fontSize: 12,
              fontFamily: "monospace",
              letterSpacing: 0.5,
              whiteSpace: "nowrap",
              transition: "all 0.15s",
            }}
          >
            {t.toUpperCase()}
          </button>
        ))}
      </div>

      <div style={{ padding: 24, maxWidth: 1100 }}>

        {/* ── TAB 0: Architecture ── */}
        {activeTab === 0 && (
          <div>
            <SectionTitle>System Architecture Overview</SectionTitle>
            <p style={{ color: COLORS.dim, fontSize: 13, marginBottom: 24, lineHeight: 1.7 }}>
              This is a <strong style={{ color: COLORS.text }}>multi-LLM collaborative trading system</strong>.
              Each AI model plays a specific specialist role. <strong style={{ color: COLORS.accent }}>Copilot acts as the
              meta-agent</strong> — it collects all specialist outputs and produces the final unified trade decision.
              No trade executes without passing the <strong style={{ color: COLORS.accent3 }}>80%+ win-rate gate</strong>.
            </p>

            {/* Flow diagram */}
            <div
              style={{
                background: COLORS.panel,
                border: `1px solid ${COLORS.border}`,
                borderRadius: 8,
                padding: 24,
                marginBottom: 24,
              }}
            >
              <div style={{ fontSize: 12, color: COLORS.dim, marginBottom: 16, letterSpacing: 1 }}>
                SIGNAL FLOW
              </div>

              {/* Row 1: Data Sources */}
              <FlowRow label="DATA SOURCES" color={COLORS.accent}>
                {["CMC", "CoinGecko", "Glassnode", "DexScreener", "TradingView"].map((s) => (
                  <FlowChip key={s} label={s} color={COLORS.accent} />
                ))}
              </FlowRow>

              <FlowArrow />

              {/* Row 2: Feature Layer */}
              <FlowRow label="FEATURE LAYER" color={COLORS.accent3}>
                {["CompositeFeed", "PairFeatures", "PeerRank", "OnChain", "Ratio CRO/BTC"].map((s) => (
                  <FlowChip key={s} label={s} color={COLORS.accent3} />
                ))}
              </FlowRow>

              <FlowArrow />

              {/* Row 3: Specialist Agents */}
              <FlowRow label="SPECIALIST AGENTS" color={COLORS.accent2}>
                {agents.filter((a) => a.id !== "copilot").map((a) => (
                  <FlowChip key={a.id} label={a.name} color={a.color} />
                ))}
              </FlowRow>

              <FlowArrow />

              {/* Row 4: Meta Agent */}
              <FlowRow label="META-AGENT (ORCHESTRATOR)" color={COLORS.accent}>
                <FlowChip label="Copilot — Synthesis & Final Decision" color={COLORS.accent} large />
              </FlowRow>

              <FlowArrow />

              {/* Row 5: Risk Gate */}
              <FlowRow label="RISK GATE" color={COLORS.accent4}>
                <FlowChip label="80%+ Win Rate Required" color={COLORS.accent4} />
                <FlowChip label="Paper Mode Default" color={COLORS.accent4} />
                <FlowChip label="Daily Loss Limit" color={COLORS.accent4} />
              </FlowRow>

              <FlowArrow />

              {/* Row 6: Execution */}
              <FlowRow label="EXECUTION" color="#c084fc">
                <FlowChip label="3Commas" color="#c084fc" />
                <FlowChip label="PineConnector" color="#c084fc" />
                <FlowChip label="Multi-Chain Arb (7 chains)" color="#c084fc" />
              </FlowRow>
            </div>

            {/* Key decisions */}
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16 }}>
              {[
                {
                  title: "Paper Mode Enforced",
                  body: "All trades simulate by default. Live trading requires an explicit LIVE=true flag in .env. This protects capital during development.",
                  color: COLORS.accent3,
                },
                {
                  title: "Profits Auto-Convert to BTC",
                  body: "Realised profits are automatically routed into BTC holdings. This protects against altcoin volatility in the base treasury.",
                  color: COLORS.accent4,
                },
                {
                  title: "80% Win Rate Gate",
                  body: "No strategy goes live without sufficient sample size and 80%+ win rate in backtesting. Odds must be confirmed before deployment.",
                  color: COLORS.accent2,
                },
                {
                  title: "No Hard-Coded Secrets",
                  body: "All API keys live in .env at C:\\Users\\barcl\\projects\\AiTradingagent\\.env and are excluded from Git via .gitignore.",
                  color: "#c084fc",
                },
              ].map((c) => (
                <div
                  key={c.title}
                  style={{
                    background: COLORS.panel,
                    border: `1px solid ${c.color}33`,
                    borderLeft: `3px solid ${c.color}`,
                    borderRadius: 6,
                    padding: 16,
                  }}
                >
                  <div style={{ color: c.color, fontSize: 12, fontWeight: 700, marginBottom: 6 }}>
                    {c.title}
                  </div>
                  <div style={{ color: COLORS.dim, fontSize: 12, lineHeight: 1.6 }}>{c.body}</div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* ── TAB 1: Agents ── */}
        {activeTab === 1 && (
          <div>
            <SectionTitle>AI Agent Roles & Responsibilities</SectionTitle>
            <p style={{ color: COLORS.dim, fontSize: 13, marginBottom: 20, lineHeight: 1.7 }}>
              Each LLM is assigned a <strong style={{ color: COLORS.text }}>specific domain</strong> where it performs best.
              Copilot synthesises all outputs. Click any agent to expand full details.
            </p>
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              {agents.map((agent) => (
                <div
                  key={agent.id}
                  style={{
                    background: COLORS.panel,
                    border: `1px solid ${expandedAgent === agent.id ? agent.color : COLORS.border}`,
                    borderRadius: 8,
                    overflow: "hidden",
                    transition: "border-color 0.2s",
                  }}
                >
                  <div
                    onClick={() =>
                      setExpandedAgent(expandedAgent === agent.id ? null : agent.id)
                    }
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 14,
                      padding: "14px 18px",
                      cursor: "pointer",
                    }}
                  >
                    <span style={{ fontSize: 22 }}>{agent.icon}</span>
                    <div style={{ flex: 1 }}>
                      <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                        <span style={{ color: "#fff", fontWeight: 700, fontSize: 15 }}>
                          {agent.name}
                        </span>
                        <span
                          style={{
                            background: `${agent.color}22`,
                            color: agent.color,
                            border: `1px solid ${agent.color}44`,
                            padding: "1px 7px",
                            borderRadius: 3,
                            fontSize: 10,
                            letterSpacing: 1,
                          }}
                        >
                          {agent.badge}
                        </span>
                      </div>
                      <div style={{ color: COLORS.dim, fontSize: 12, marginTop: 2 }}>
                        {agent.role}
                      </div>
                    </div>
                    <span style={{ color: COLORS.muted, fontSize: 18 }}>
                      {expandedAgent === agent.id ? "▲" : "▼"}
                    </span>
                  </div>
                  {expandedAgent === agent.id && (
                    <div
                      style={{
                        padding: "0 18px 18px",
                        borderTop: `1px solid ${COLORS.border}`,
                      }}
                    >
                      <p style={{ color: COLORS.text, fontSize: 13, lineHeight: 1.7, marginTop: 14 }}>
                        {agent.description}
                      </p>
                      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16, marginTop: 14 }}>
                        <div>
                          <div style={{ color: COLORS.dim, fontSize: 11, letterSpacing: 1, marginBottom: 8 }}>
                            RESPONSIBILITIES
                          </div>
                          {agent.responsibilities.map((r) => (
                            <div
                              key={r}
                              style={{
                                color: COLORS.text,
                                fontSize: 12,
                                marginBottom: 5,
                                paddingLeft: 12,
                                borderLeft: `2px solid ${agent.color}`,
                                lineHeight: 1.5,
                              }}
                            >
                              {r}
                            </div>
                          ))}
                        </div>
                        <div>
                          <InfoRow label="Model" value={agent.model} color={agent.color} />
                          <InfoRow label="Access via" value={agent.api} color={agent.color} />
                          {agent.id === "claude" && (
                            <InfoRow label="Key env var" value="ANTHROPIC_API_KEY" color={agent.color} mono />
                          )}
                          {agent.id === "gpt" && (
                            <InfoRow label="Key env var" value="OPENAI_API_KEY" color={agent.color} mono />
                          )}
                          {agent.id === "grok" && (
                            <InfoRow label="Key env var" value="OPENROUTER_API_KEY" color={agent.color} mono />
                          )}
                          {agent.id === "gemini" && (
                            <InfoRow label="Key env var" value="GEMINI_API_KEY" color={agent.color} mono />
                          )}
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}

        {/* ── TAB 2: Data Pipeline ── */}
        {activeTab === 2 && (
          <div>
            <SectionTitle>Data Ingestion Pipeline</SectionTitle>
            <p style={{ color: COLORS.dim, fontSize: 13, marginBottom: 20, lineHeight: 1.7 }}>
              <code style={{ color: COLORS.accent }}>pipeline_daily.py</code> runs once per day and caches all
              data to <code style={{ color: COLORS.accent }}>data/cache/</code> as Parquet files.
              The <code style={{ color: COLORS.accent }}>CompositeFeed</code> reads from cache to build{" "}
              <code style={{ color: COLORS.accent }}>MarketContext</code> for every agent.
            </p>
            {dataSources.map((ds) => (
              <div
                key={ds.name}
                style={{
                  background: COLORS.panel,
                  border: `1px solid ${COLORS.border}`,
                  borderLeft: `3px solid ${ds.color}`,
                  borderRadius: 6,
                  padding: 16,
                  marginBottom: 12,
                  display: "grid",
                  gridTemplateColumns: "140px 1fr 1fr",
                  gap: 16,
                  alignItems: "start",
                }}
              >
                <div>
                  <div style={{ color: ds.color, fontWeight: 700, fontSize: 14 }}>{ds.name}</div>
                  <div style={{ color: COLORS.dim, fontSize: 11, marginTop: 3 }}>{ds.type}</div>
                </div>
                <div>
                  <Label>OUTPUT FIELDS</Label>
                  <Code>{ds.output}</Code>
                  <Label style={{ marginTop: 8 }}>SOURCE FILE</Label>
                  <Code>{ds.file}</Code>
                </div>
                <div>
                  <Label>API KEY</Label>
                  <div
                    style={{
                      color: ds.key.startsWith("No") ? COLORS.accent3 : COLORS.accent4,
                      fontSize: 12,
                    }}
                  >
                    {ds.key}
                  </div>
                </div>
              </div>
            ))}

            {/* Feature pipeline */}
            <SectionTitle style={{ marginTop: 28 }}>Feature Engineering — What Each Module Produces</SectionTitle>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
              {[
                {
                  file: "pair_features.py",
                  output: ["ret_all_time", "ret_1y", "ret_3m", "max_dd_1y", "max_dd_3m", "rank_now", "rank_trend"],
                  color: COLORS.accent,
                },
                {
                  file: "peer_features.py",
                  output: ["peer_rank", "peer_total", "peer_percentile", "peer_return", "rotation_signal"],
                  color: COLORS.accent3,
                },
                {
                  file: "onchain_features.py",
                  output: ["sopr.value", "sopr.signal", "mvrv.value", "mvrv.signal", "onchain_risk_score"],
                  color: COLORS.accent2,
                },
                {
                  file: "ratio_features.py",
                  output: [
                    "current_ratio (e.g. CRO/BTC)",
                    "trend_30d",
                    "position_in_90d_range",
                    "signal: buy_base / neutral / sell_base",
