                    </div>
                  ))}
                </div>
              ))}
            </div>

            {/* BTC dominance */}
            <div
              style={{
                background: COLORS.panel,
                border: `1px solid ${COLORS.border}`,
                borderRadius: 6,
                padding: 16,
                marginTop: 12,
