import { useState } from "react";

const C = {
  bg: "#080c12",
  panel: "#0d1320",
  card: "#101826",
  border: "#1a2a3f",
  accent: "#00c8ff",
  green: "#39ff7a",
  orange: "#ff6b35",
  yellow: "#ffc944",
  purple: "#b06cfc",
  red: "#ff4455",
  text: "#c0d4e8",
  dim: "#506070",
  muted: "#304050",
};

// ─── DATA ────────────────────────────────────────────────────────────────────

const LAYERS = [
  {
    id: "L1", label: "Layer 1", title: "Data Ingestion",
    color: C.accent,
    desc: "Pull OHLCV, funding rate, open interest, liquidations, news, social sentiment and exchange account data into a normalised store. Every agent reads the same schema — no agent hits APIs directly.",
    items: ["CMC historical price + rank", "CoinGecko backup feed", "Glassnode on-chain (SOPR, MVRV)", "DexScreener live DEX prices (7 chains)", "TradingView Pine Script webhooks"],
    path: "agents/market_data/",
  },
  {
    id: "L2", label: "Layer 2", title: "Feature Engineering",
    color: C.green,
    desc: "Convert raw feeds into indicators, market regime labels, volatility buckets, sentiment scores and event flags. This matches how FreqAI expects engineered features and targets for prediction workflows.",
    items: ["pair_features.py — return, drawdown, rank trend", "peer_features.py — universe rotation signals", "onchain_features.py — SOPR/MVRV risk score", "ratio_features.py — CRO/BTC relative strength", "btc_dominance.py — regime classifier"],
    path: "agents/features/",
  },
  {
    id: "L3", label: "Layer 3", title: "Specialist Agents (LLMs)",
    color: C.orange,
    desc: "Split intelligence into focused workers. Each agent returns structured JSON: { signal, confidence, reason, constraints }. No agent produces a free-text trade order.",
    items: ["Claude — strategy, risk, regime classification", "GPT-4o — macro, sentiment, news catalyst", "Grok — X/Twitter social signal, whale alerts", "Gemini — chart patterns, Pine Script validation", "Perplexity — deep research, context enrichment"],
    path: "agents/signal/ + agents/regime/ + agents/sentiment/",
  },
  {
    id: "L4", label: "Layer 4", title: "Decision Synthesis (Copilot)",
    color: C.yellow,
    desc: "Copilot acts as meta-agent coordinator. It scores and votes across all specialist outputs, resolves conflicts, and produces a single action proposal: long / short / reduce / hold.",
    items: ["Weighted voting across all agents", "Conflict resolution logic", "80%+ win-rate gate enforcement", "Structured output: direction + confidence + stop + target", "Passes proposal to Risk Gate"],
    path: "apps/orchestrator/",
  },
  {
    id: "L5", label: "Layer 5", title: "Risk Gate (Hard Veto)",
    color: C.red,
    desc: "Non-negotiable. Caps exposure, blocks trades during abnormal volatility, enforces max drawdown, and can veto every other agent. Risk is a hard gate, not a suggestion.",
    items: ["Daily loss limit circuit breaker", "Max drawdown kill switch", "Position sizing enforcer", "Abnormal volatility detector", "Paper mode enforced (LIVE=false default)"],
    path: "agents/risk/",
  },
  {
    id: "L6", label: "Layer 6", title: "Execution — Freqtrade + FreqAI",
    color: C.purple,
    desc: "Freqtrade handles order placement, trade state, dry runs, and exchange plumbing. Your multi-agent layer handles reasoning. They connect via freqtrade-mcp (MCP bridge). FreqAI supports ML/RL model integration.",
    items: ["Freqtrade execution engine", "FreqAI — supervised + RL model classes", "freqtrade-mcp bridge (MCP protocol)", "3Commas / PineConnector signal adapter", "Multi-chain arbitrage (DexScreener, 7 chains)"],
    path: "connectors/freqtrade/ + execution/",
  },
  {
    id: "L7", label: "Layer 7", title: "Monitoring & Replay",
    color: C.green,
    desc: "Every decision must be reproducible from stored inputs, agent outputs and final actions — otherwise you cannot debug losses cleanly. Full audit trail for every trade.",
    items: ["PnL drift monitoring", "Slippage + fill latency tracking", "Full replay log (inputs → agent outputs → decision)", "Strategy backtesting with sample-size validation", "Dashboard (React) — ArbitrageScanner + BreakoutPanel"],
    path: "monitoring/ + dashboard/ + tests/",
  },
];

const AGENTS = [
  {
    name: "Copilot", role: "Synthesis / Meta-Agent", badge: "ORCHESTRATOR", color: C.accent, icon: "⚡",
    layer: "L4",
    desc: "Central coordinator. Collects structured JSON outputs from all specialist agents, applies weighted voting, resolves conflicts, and produces the final trade proposal. No trade executes without Copilot sign-off.",
    jobs: ["Aggregate {signal, confidence, reason, constraints} from all agents", "Weighted voting — resolve conflicts", "Apply 80%+ win-rate gate", "Output: {direction, confidence, stop, target, time_horizon}", "Route approved proposals to Risk Gate"],
    model: "GitHub Copilot / GPT-4o", env: "GitHub Copilot (IDE)", path: "apps/orchestrator/",
  },
  {
    name: "Claude", role: "Strategy, Risk & Regime", badge: "SPECIALIST", color: C.orange, icon: "🧠",
    layer: "L3",
    desc: "Deep reasoning on market structure, drawdown risk, regime classification and peer rotation. Writes and validates the Python pipeline code. Leads architecture decisions.",
    jobs: ["BTC dominance regime: risk_on / neutral / risk_off", "Peer rotation: rotate_in / hold / rotate_out", "On-chain risk score (SOPR, MVRV)", "All module code generation + validation", "Ratio analysis: CRO/BTC relative strength"],
    model: "Claude Sonnet 4.6", env: "ANTHROPIC_API_KEY", path: "agents/regime/ + agents/features/",
  },
  {
    name: "GPT-4o", role: "Macro & Sentiment", badge: "SPECIALIST", color: C.green, icon: "📊",
    layer: "L3",
    desc: "Processes macro news, Fed statements, earnings calendar, Fear & Greed index. Provides probability-weighted narrative context. Returns structured sentiment score per trade setup.",
    jobs: ["News sentiment scoring (bullish/bearish/neutral)", "Macro event calendar awareness", "Fear & Greed index integration", "Narrative risk flagging", "Breaking catalyst web search"],
    model: "GPT-4o", env: "OPENAI_API_KEY", path: "agents/sentiment/",
  },
  {
    name: "Grok", role: "Social & Real-Time Intel", badge: "SPECIALIST", color: C.yellow, icon: "📡",
    layer: "L3",
    desc: "Real-time social signal extraction from X (Twitter). Detects whale wallet activity, trending narratives, influencer pumps, and abnormal volume spikes before they hit price.",
    jobs: ["X/Twitter trend monitoring", "Whale alert cross-referencing", "Influencer signal detection", "Volume anomaly flagging", "Meme coin early-warning"],
    model: "Grok-2", env: "OPENROUTER_API_KEY", path: "agents/sentiment/social/",
  },
  {
    name: "Gemini", role: "Technical Pattern Recognition", badge: "SPECIALIST", color: C.purple, icon: "🔍",
    layer: "L3",
    desc: "Chart pattern detection and multi-timeframe technical analysis. Validates Pine Script signals from TradingView. Used for Trading Strategy Automator benchmarking vs Claude outputs.",
    jobs: ["OHLCV pattern recognition", "ORB + Volume-Price Breakout validation", "Multi-timeframe confluence check", "Pine Script webhook signal validation", "Benchmark comparison vs Claude strategies"],
    model: "Gemini 1.5 Pro", env: "GEMINI_API_KEY", path: "agents/signal/",
  },
  {
    name: "Perplexity", role: "Research & Context", badge: "SPECIALIST", color: "#22d3ee", icon: "🔎",
    layer: "L3",
    desc: "Deep research agent. Enriches trade context with cited sources, project fundamentals, tokenomics, and competitor analysis. Recommended layered architecture and Freqtrade integration.",
    jobs: ["Project tokenomics deep-dive", "Competitor chain analysis", "Cited source research for trade narrative", "Architecture recommendations (Freqtrade, FreqAI)", "Context enrichment before Copilot synthesis"],
    model: "Perplexity Sonar", env: "PERPLEXITY_API_KEY", path: "agents/signal/research/",
  },
];

const FILE_STRUCTURE = [
  { path: "apps/orchestrator/", files: ["coordinator.py", "voting.py", "conflict_resolver.py"], desc: "Copilot meta-agent — weighted voting, conflict resolution, final decision", status: "build next" },
  { path: "agents/market_data/", files: ["cmc_client.py", "coingecko_client.py", "dex_screener.py", "websocket_listener.py"], desc: "Exchange connectors, websocket, caching, schema normalisation", status: "built" },
  { path: "agents/features/", files: ["pair_features.py", "peer_features.py", "onchain_features.py", "ratio_features.py", "btc_dominance.py"], desc: "Indicators, regime labels, volatility buckets, feature sets", status: "built" },
  { path: "agents/sentiment/", files: ["news_agent.py", "social_agent.py", "fear_greed.py"], desc: "GPT-4o news + Grok social + Fear & Greed index", status: "in progress" },
  { path: "agents/regime/", files: ["regime_classifier.py", "regime_switcher.py"], desc: "Claude-powered trend/range/volatility/panic state detection", status: "built" },
