const Pill = ({ label, color }) => (
  <span style={{
    background: `${color}18`, border: `1px solid ${color}44`,
    color, padding: "2px 9px", borderRadius: 4,
    fontSize: 10, fontFamily: "monospace", letterSpacing: 0.8, fontWeight: 700,
  }}>{label}</span>
);

const StatusPill = ({ s }) => {
  const map = {
    "built":       { bg: "#0b2015", color: C.green },
    "in progress": { bg: "#201800", color: C.yellow },
    "build next":  { bg: "#1a0a00", color: C.orange },
    "planned":     { bg: "#150a25", color: C.purple },
  };
  const st = map[s] || map.planned;
  return <Pill label={s.toUpperCase()} color={st.color} />;
};

const Mono = ({ children, color }) => (
  <code style={{ color: color || C.accent, fontFamily: "monospace", fontSize: 12 }}>{children}</code>
);

const SectionTitle = ({ children }) => (
