                <span style={{ color: t.color, fontWeight: 700, minWidth: 20, fontSize: 13 }}>{t.n}.</span>
                <div>
                  <Mono color={t.color}>{t.task}</Mono>
                  <div style={{ color: C.dim, fontSize: 12, marginTop: 3 }}>{t.why}</div>
                </div>
              </div>
            ))}
          </div>
        )}

      </div>

      {/* Footer */}
      <div style={{
        borderTop: `1px solid ${C.border}`, padding: "12px 24px",
        display: "flex", justifyContent: "space-between", alignItems: "center",
        background: C.panel, marginTop: 20,
      }}>
        <span style={{ color: C.muted, fontSize: 11 }}>AiTradingAgent · Alan J, Edinburgh · Paper mode enforced</span>
        <span style={{ color: C.dim, fontSize: 11 }}>
          Sources: Perplexity research + Claude architecture + conversation history
        </span>
      </div>
    </div>
  );
}

