from typing import Dict, Any, List
import os, time, requests
class CoinGeckoClient:
    def __init__(self, base_url: str = "https://api.coingecko.com/api/v3"):
        self.base_url = base_url
    def get_ohlc(self, symbol: str, vs_currency: str = "usd", days: int = 90) -> List[Dict[str, Any]]:
        # /coins/{id}/ohlc expects a CoinGecko id, not ticker – map symbol->id in your config
        resp = requests.get(f"{self.base_url}/coins/{symbol}/ohlc", params={"vs_currency": vs_currency, "days": days})
        resp.raise_for_status()
        # Returns [timestamp, open, high, low, close]
        return resp.json()
class CoinMarketCapClient:
    def __init__(self, api_key: str | None = None, base_url: str = "https://pro-api.coinmarketcap.com/v1"):
        self.base_url = base_url
        self.api_key = api_key or os.getenv("CMC_API_KEY")
    def _headers(self) -> Dict[str, str]:
        return {"X-CMC_PRO_API_KEY": self.api_key} if self.api_key else {}
    def quotes_latest(self, symbol: str) -> Dict[str, Any]:
        resp = requests.get(
            f"{self.base_url}/cryptocurrency/quotes/latest",
            params={"symbol": symbol},
            headers=self._headers(),
        )
        resp.raise_for_status()
        return resp.json()

