# ---------------------------------------------------------------------------
# Router
# ---------------------------------------------------------------------------

class LLMRouter(LLMClient):
    """
    Routes generate_text / score_options calls to a named provider.
    Supports:
    - Per-call provider override via `llm=` kwarg
    - Ordered fallback chain on failure

