import React, { useState, useEffect } from 'react';
import { AlertCircle, TrendingUp, Search, RefreshCw, DollarSign, Zap } from 'lucide-react';

const ArbitrageAnalyzer = () => {
  const [opportunities, setOpportunities] = useState([]);
  const [loading, setLoading] = useState(false);
  const [settings, setSettings] = useState({
    minSpread: 0.5,
    investmentAmount: 1000,
    tradingFees: 0.1,
    withdrawalFees: 5,
    minProfit: 10
  });
  const [selectedAsset, setSelectedAsset] = useState('BTC');

  // Popular crypto assets to track
  const assets = ['BTC', 'ETH', 'CRO', 'BNB', 'SOL', 'MATIC', 'AVAX', 'DOT'];

  // Simulated exchange data (in real implementation, would connect to APIs)
  const exchanges = ['Binance', 'Crypto.com', 'Coinbase', 'Kraken', 'KuCoin'];

  const generateMockPrices = (basePrice) => {
    return exchanges.map(exchange => ({
      exchange,
      price: basePrice * (1 + (Math.random() - 0.5) * 0.02), // ±1% variance
      liquidity: Math.floor(Math.random() * 500000) + 100000,
      volume24h: Math.floor(Math.random() * 10000000) + 1000000
    }));
  };

  const basePrices = {
    'BTC': 42000,
    'ETH': 2200,
    'CRO': 0.12,
    'BNB': 310,
    'SOL': 95,
    'MATIC': 0.85,
    'AVAX': 35,
    'DOT': 7.2
  };

  const calculateArbitrage = () => {
    setLoading(true);

    setTimeout(() => {
      const arbs = [];

      assets.forEach(asset => {
        const prices = generateMockPrices(basePrices[asset]);

        // Find min and max prices
        const sortedPrices = [...prices].sort((a, b) => a.price - b.price);
        const buyExchange = sortedPrices[0];
        const sellExchange = sortedPrices[sortedPrices.length - 1];

        // Calculate spread
        const spread = ((sellExchange.price - buyExchange.price) / buyExchange.price) * 100;

        // Calculate potential profit
        const buyAmount = settings.investmentAmount / buyExchange.price;
        const grossProfit = buyAmount * sellExchange.price - settings.investmentAmount;
        const totalFees = (settings.investmentAmount * settings.tradingFees / 100 * 2) + settings.withdrawalFees;
        const netProfit = grossProfit - totalFees;
        const profitPercent = (netProfit / settings.investmentAmount) * 100;

        // Only include if meets minimum criteria
        if (spread >= settings.minSpread && netProfit >= settings.minProfit) {
          arbs.push({
            asset,
            buyExchange: buyExchange.exchange,
            buyPrice: buyExchange.price,
            sellExchange: sellExchange.exchange,
            sellPrice: sellExchange.price,
            spread: spread,
            netProfit: netProfit,
            profitPercent: profitPercent,
            buyLiquidity: buyExchange.liquidity,
            sellLiquidity: sellExchange.liquidity,
            executionRisk: spread < 1 ? 'Low' : spread < 2 ? 'Medium' : 'High'
          });
        }
      });

      // Sort by profit percentage
      arbs.sort((a, b) => b.profitPercent - a.profitPercent);

      setOpportunities(arbs);
      setLoading(false);
    }, 1500);
  };

  useEffect(() => {
    calculateArbitrage();
    // Auto-refresh every 30 seconds
    const interval = setInterval(calculateArbitrage, 30000);
    return () => clearInterval(interval);
  }, [settings.minSpread, settings.minProfit]);

  const getRiskColor = (risk) => {
    switch(risk) {
      case 'Low': return 'text-green-600 bg-green-100';
      case 'Medium': return 'text-yellow-600 bg-yellow-100';
      case 'High': return 'text-red-600 bg-red-100';
      default: return 'text-gray-600 bg-gray-100';
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900 p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 mb-6 border border-white/20">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3">
              <Zap className="text-yellow-400" size={32} />
              <h1 className="text-3xl font-bold text-white">Crypto Arbitrage Agent</h1>
            </div>
            <button 
              onClick={calculateArbitrage}
              disabled={loading}
              className="flex items-center gap-2 bg-purple-600 hover:bg-purple-700 text-white px-4 py-2 rounded-lg transition-all disabled:opacity-50"
            >
              <RefreshCw className={loading ? 'animate-spin' : ''} size={20} />
              {loading ? 'Scanning...' : 'Refresh'}
            </button>
          </div>

          <p className="text-gray-300">
            AI-powered real-time arbitrage opportunity scanner across major exchanges
          </p>
        </div>

        {/* Settings Panel */}
        <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 mb-6 border border-white/20">
          <h2 className="text-xl font-bold text-white mb-4">Settings</h2>
          <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-5 gap-4">
            <div>
              <label className="block text-sm text-gray-300 mb-2">Min Spread %</label>
              <input 
                type="number" 
                value={settings.minSpread}
                onChange={(e) => setSettings({...settings, minSpread: parseFloat(e.target.value)})}
                className="w-full bg-white/20 text-white border border-white/30 rounded px-3 py-2"
                step="0.1"
              />
            </div>

            <div>
              <label className="block text-sm text-gray-300 mb-2">Investment ($)</label>
              <input 
                type="number" 
                value={settings.investmentAmount}
                onChange={(e) => setSettings({...settings, investmentAmount: parseFloat(e.target.value)})}
                className="w-full bg-white/20 text-white border border-white/30 rounded px-3 py-2"
              />
            </div>

            <div>
              <label className="block text-sm text-gray-300 mb-2">Trading Fees %</label>
              <input 
                type="number" 
                value={settings.tradingFees}
                onChange={(e) => setSettings({...settings, tradingFees: parseFloat(e.target.value)})}
                className="w-full bg-white/20 text-white border border-white/30 rounded px-3 py-2"
                step="0.01"
              />
            </div>

            <div>
              <label className="block text-sm text-gray-300 mb-2">Withdrawal Fees ($)</label>
              <input 
                type="number" 
                value={settings.withdrawalFees}
                onChange={(e) => setSettings({...settings, withdrawalFees: parseFloat(e.target.value)})}
                className="w-full bg-white/20 text-white border border-white/30 rounded px-3 py-2"
                step="0.5"
              />
            </div>

            <div>
              <label className="block text-sm text-gray-300 mb-2">Min Profit ($)</label>
              <input 
                type="number" 
                value={settings.minProfit}
                onChange={(e) => setSettings({...settings, minProfit: parseFloat(e.target.value)})}
                className="w-full bg-white/20 text-white border border-white/30 rounded px-3 py-2"
              />
            </div>
          </div>
        </div>

        {/* Statistics */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
          <div className="bg-gradient-to-br from-green-500/20 to-green-600/20 backdrop-blur-lg rounded-xl p-4 border border-green-500/30">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-300 text-sm">Opportunities Found</p>
                <p className="text-3xl font-bold text-white mt-1">{opportunities.length}</p>
              </div>
              <TrendingUp className="text-green-400" size={32} />
            </div>
          </div>

          <div className="bg-gradient-to-br from-blue-500/20 to-blue-600/20 backdrop-blur-lg rounded-xl p-4 border border-blue-500/30">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-300 text-sm">Best Spread</p>
                <p className="text-3xl font-bold text-white mt-1">
                  {opportunities.length > 0 ? `${opportunities[0].spread.toFixed(2)}%` : '0%'}
                </p>
              </div>
              <DollarSign className="text-blue-400" size={32} />
            </div>
          </div>

          <div className="bg-gradient-to-br from-purple-500/20 to-purple-600/20 backdrop-blur-lg rounded-xl p-4 border border-purple-500/30">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-300 text-sm">Top Profit</p>
                <p className="text-3xl font-bold text-white mt-1">
                  {opportunities.length > 0 ? `$${opportunities[0].netProfit.toFixed(2)}` : '$0'}
                </p>
              </div>
              <TrendingUp className="text-purple-400" size={32} />
            </div>
          </div>

          <div className="bg-gradient-to-br from-yellow-500/20 to-yellow-600/20 backdrop-blur-lg rounded-xl p-4 border border-yellow-500/30">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-300 text-sm">Avg ROI</p>
                <p className="text-3xl font-bold text-white mt-1">
                  {opportunities.length > 0 
                    ? `${(opportunities.reduce((acc, opp) => acc + opp.profitPercent, 0) / opportunities.length).toFixed(2)}%`
                    : '0%'
                  }
                </p>
              </div>
              <Zap className="text-yellow-400" size={32} />
            </div>
          </div>
        </div>

        {/* Opportunities List */}
        <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
          <h2 className="text-xl font-bold text-white mb-4">Active Opportunities</h2>

          {loading ? (
            <div className="text-center py-12">
              <RefreshCw className="animate-spin mx-auto text-purple-400 mb-4" size={48} />
              <p className="text-gray-300">Scanning exchanges for arbitrage opportunities...</p>
            </div>
          ) : opportunities.length === 0 ? (
            <div className="text-center py-12">
              <AlertCircle className="mx-auto text-gray-500 mb-4" size={48} />
              <p className="text-gray-400">No profitable opportunities found with current settings</p>
              <p className="text-gray-500 text-sm mt-2">Try lowering your minimum spread or profit threshold</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead>
                  <tr className="border-b border-white/20">
                    <th className="text-left py-3 px-4 text-gray-300 font-semibold">Asset</th>
                    <th className="text-left py-3 px-4 text-gray-300 font-semibold">Buy From</th>
                    <th className="text-left py-3 px-4 text-gray-300 font-semibold">Buy Price</th>
                    <th className="text-left py-3 px-4 text-gray-300 font-semibold">Sell To</th>
                    <th className="text-left py-3 px-4 text-gray-300 font-semibold">Sell Price</th>
                    <th className="text-left py-3 px-4 text-gray-300 font-semibold">Spread</th>
                    <th className="text-left py-3 px-4 text-gray-300 font-semibold">Net Profit</th>
                    <th className="text-left py-3 px-4 text-gray-300 font-semibold">ROI</th>
                    <th className="text-left py-3 px-4 text-gray-300 font-semibold">Risk</th>
                  </tr>
                </thead>
                <tbody>
                  {opportunities.map((opp, idx) => (
                    <tr key={idx} className="border-b border-white/10 hover:bg-white/5 transition-colors">
                      <td className="py-3 px-4">
                        <span className="font-bold text-white">{opp.asset}</span>
                      </td>
                      <td className="py-3 px-4 text-gray-300">{opp.buyExchange}</td>
                      <td className="py-3 px-4 text-green-400 font-mono">
                        ${opp.buyPrice.toFixed(opp.asset === 'BTC' || opp.asset === 'ETH' ? 2 : 4)}
                      </td>
                      <td className="py-3 px-4 text-gray-300">{opp.sellExchange}</td>
                      <td className="py-3 px-4 text-red-400 font-mono">
                        ${opp.sellPrice.toFixed(opp.asset === 'BTC' || opp.asset === 'ETH' ? 2 : 4)}
                      </td>
                      <td className="py-3 px-4">
                        <span className="text-yellow-400 font-semibold">{opp.spread.toFixed(2)}%</span>
                      </td>
                      <td className="py-3 px-4">
                        <span className="text-green-400 font-bold">${opp.netProfit.toFixed(2)}</span>
                      </td>
                      <td className="py-3 px-4">
                        <span className="text-purple-400 font-semibold">{opp.profitPercent.toFixed(2)}%</span>
                      </td>
                      <td className="py-3 px-4">
                        <span className={`px-2 py-1 rounded text-xs font-semibold ${getRiskColor(opp.executionRisk)}`}>
                          {opp.executionRisk}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* Disclaimer */}
        <div className="mt-6 bg-yellow-500/10 backdrop-blur-lg rounded-xl p-4 border border-yellow-500/30">
          <div className="flex items-start gap-3">
            <AlertCircle className="text-yellow-400 flex-shrink-0 mt-1" size={20} />
            <div className="text-sm text-gray-300">
              <p className="font-semibold text-yellow-400 mb-1">Important Disclaimer</p>
              <p>This is a demonstration tool using simulated data. Real arbitrage involves risks including slippage, withdrawal delays, exchange limits, and market volatility. Always conduct thorough research and consider all costs before executing trades. Past performance does not guarantee future results.</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ArbitrageAnalyzer;

import React, { useState, useEffect } from 'react';
import { Bot, Zap, TrendingUp, AlertCircle, Settings, Play, Pause, DollarSign, Activity, CheckCircle, XCircle, Bell } from 'lucide-react';

const AutomatedTradingSystem = () => {
  const [activeTab, setActiveTab] = useState('arbitrage');
  const [botActive, setBotActive] = useState(false);
  const [positions, setPositions] = useState([]);
  const [arbOpportunities, setArbOpportunities] = useState([]);
  const [tradeHistory, setTradeHistory] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [stats, setStats] = useState({
    totalTrades: 0,
    winRate: 0,
    totalProfit: 0,
    activePositions: 0
  });

  // Bot Configuration
  const [config, setConfig] = useState({
    // Arbitrage Settings
    minArbSpread: 1.0,
    arbInvestment: 1000,
    maxArbPositions: 3,
    autoExecuteArb: false,

    // Breakout Strategy Settings
    riskPerTrade: 2,
    stopLoss: 2,
    takeProfit: 4,
    maxPositions: 5,
    autoExecuteBreakout: false,

    // API Keys (encrypted in production)
    exchanges: {
      binance: { enabled: false, apiKey: '', secret: '' },
      cryptocom: { enabled: false, apiKey: '', secret: '' },
      coinbase: { enabled: false, apiKey: '', secret: '' }
    },

    // Risk Management
    maxDailyLoss: 100,
    maxDrawdown: 10,
    dailyLoss: 0
  });

  // Simulate market data
  const generateMarketData = () => {
    const assets = ['BTC', 'ETH', 'CRO', 'BNB', 'SOL'];
    const exchanges = ['Binance', 'Crypto.com', 'Coinbase'];

    return assets.map(asset => {
      const basePrice = {
        'BTC': 42000,
        'ETH': 2200,
        'CRO': 0.12,
        'BNB': 310,
        'SOL': 95
      }[asset];

      return exchanges.map(exchange => ({
        asset,
        exchange,
        price: basePrice * (1 + (Math.random() - 0.5) * 0.03),
        volume: Math.random() * 1000000,
        timestamp: new Date()
      }));
    }).flat();
  };

  // Arbitrage Detection Engine
  const detectArbitrage = () => {
    const marketData = generateMarketData();
    const opportunities = [];

    // Group by asset
    const byAsset = marketData.reduce((acc, data) => {
      if (!acc[data.asset]) acc[data.asset] = [];
      acc[data.asset].push(data);
      return acc;
    }, {});

    // Find arbitrage opportunities
    Object.keys(byAsset).forEach(asset => {
      const prices = byAsset[asset];
      prices.sort((a, b) => a.price - b.price);

      const buy = prices[0];
      const sell = prices[prices.length - 1];
      const spread = ((sell.price - buy.price) / buy.price) * 100;

      if (spread >= config.minArbSpread) {
        const fees = config.arbInvestment * 0.002; // 0.2% total fees
        const quantity = config.arbInvestment / buy.price;
        const grossProfit = quantity * sell.price - config.arbInvestment;
        const netProfit = grossProfit - fees;

        opportunities.push({
          id: Date.now() + Math.random(),
          asset,
          buyExchange: buy.exchange,
          buyPrice: buy.price,
          sellExchange: sell.exchange,
          sellPrice: sell.price,
          spread,
          netProfit,
          roi: (netProfit / config.arbInvestment) * 100,
          timestamp: new Date()
        });
      }
    });

    setArbOpportunities(opportunities);
    return opportunities;
  };

  // Breakout Signal Detection
  const detectBreakouts = () => {
    // Simulate breakout signals
    const signals = [];
    const assets = ['BTC/USDT', 'ETH/USDT', 'CRO/USDT'];

    if (Math.random() > 0.7) { // 30% chance of signal
      const asset = assets[Math.floor(Math.random() * assets.length)];
      const price = Math.random() * 50000;

      signals.push({
        id: Date.now() + Math.random(),
        type: 'LONG',
        asset,
        entryPrice: price,
        stopLoss: price * (1 - config.stopLoss / 100),
        takeProfit: price * (1 + config.takeProfit / 100),
        volumeConfirmed: true,
        trendConfirmed: true,
        timestamp: new Date()
      });
    }

    return signals;
  };

  // Execute Arbitrage Trade
  const executeArbitrage = async (opportunity) => {
    if (config.dailyLoss >= config.maxDailyLoss) {
      addNotification('Daily loss limit reached. Trade rejected.', 'error');
      return;
    }

    if (positions.filter(p => p.type === 'arbitrage').length >= config.maxArbPositions) {
      addNotification('Max arbitrage positions reached.', 'warning');
      return;
    }

    // Simulate trade execution
    const newPosition = {
      id: Date.now() + Math.random(),
      type: 'arbitrage',
      asset: opportunity.asset,
      buyExchange: opportunity.buyExchange,
      sellExchange: opportunity.sellExchange,
      entryPrice: opportunity.buyPrice,
      exitPrice: opportunity.sellPrice,
      quantity: config.arbInvestment / opportunity.buyPrice,
      status: 'executing',
      profit: 0,
      timestamp: new Date()
    };

    setPositions(prev => [...prev, newPosition]);
    addNotification(`Executing arbitrage: ${opportunity.asset} - Buy ${opportunity.buyExchange} @ $${opportunity.buyPrice.toFixed(4)}, Sell ${opportunity.sellExchange} @ $${opportunity.sellPrice.toFixed(4)}`, 'success');

    // Simulate execution delay
    setTimeout(() => {
      const finalProfit = opportunity.netProfit * (0.9 + Math.random() * 0.2); // ±10% slippage

      setPositions(prev => prev.map(p => 
        p.id === newPosition.id 
          ? { ...p, status: 'closed', profit: finalProfit }
          : p
      ));

      setTradeHistory(prev => [{
        ...newPosition,
        status: 'closed',
        profit: finalProfit,
        closedAt: new Date()
      }, ...prev].slice(0, 50));

      updateStats(finalProfit);
      addNotification(`Arbitrage closed: ${opportunity.asset} - Profit: $${finalProfit.toFixed(2)}`, finalProfit > 0 ? 'success' : 'error');
    }, 3000 + Math.random() * 2000);
  };

  // Execute Breakout Trade
  const executeBreakout = (signal) => {
    if (config.dailyLoss >= config.maxDailyLoss) {
      addNotification('Daily loss limit reached. Trade rejected.', 'error');
      return;
    }

    if (positions.filter(p => p.type === 'breakout').length >= config.maxPositions) {
      addNotification('Max breakout positions reached.', 'warning');
      return;
    }

    const riskAmount = stats.totalProfit * (config.riskPerTrade / 100);
    const quantity = riskAmount / (signal.entryPrice - signal.stopLoss);

    const newPosition = {
      id: Date.now() + Math.random(),
      type: 'breakout',
      asset: signal.asset,
      entryPrice: signal.entryPrice,
      stopLoss: signal.stopLoss,
      takeProfit: signal.takeProfit,
      quantity,
      status: 'open',
      profit: 0,
      timestamp: new Date()
    };

    setPositions(prev => [...prev, newPosition]);
    addNotification(`Breakout entry: ${signal.asset} @ $${signal.entryPrice.toFixed(2)}`, 'success');
  };

  // Update Statistics
  const updateStats = (profit) => {
    setStats(prev => {
      const newTotalProfit = prev.totalProfit + profit;
      const newTotalTrades = prev.totalTrades + 1;
      const wins = tradeHistory.filter(t => t.profit > 0).length + (profit > 0 ? 1 : 0);

      return {
        totalTrades: newTotalTrades,
        winRate: (wins / newTotalTrades) * 100,
        totalProfit: newTotalProfit,
        activePositions: positions.filter(p => p.status === 'open' || p.status === 'executing').length
      };
    });

    setConfig(prev => ({
      ...prev,
      dailyLoss: profit < 0 ? prev.dailyLoss + Math.abs(profit) : prev.dailyLoss
    }));
  };

  // Add Notification
  const addNotification = (message, type = 'info') => {
    const notification = {
      id: Date.now(),
      message,
      type,
      timestamp: new Date()
    };

    setNotifications(prev => [notification, ...prev].slice(0, 10));
  };

  // Bot Main Loop
  useEffect(() => {
    if (!botActive) return;

    const interval = setInterval(() => {
      // Detect arbitrage opportunities
      const arbOpps = detectArbitrage();

      // Auto-execute if enabled
      if (config.autoExecuteArb && arbOpps.length > 0) {
        const bestOpp = arbOpps[0];
        executeArbitrage(bestOpp);
      }

      // Detect breakout signals
      const breakouts = detectBreakouts();

      // Auto-execute if enabled
      if (config.autoExecuteBreakout && breakouts.length > 0) {
        breakouts.forEach(signal => executeBreakout(signal));
      }

      // Manage open positions (check SL/TP)
      positions.forEach(position => {
        if (position.type === 'breakout' && position.status === 'open') {
          const currentPrice = position.entryPrice * (1 + (Math.random() - 0.5) * 0.05);

          if (currentPrice <= position.stopLoss || currentPrice >= position.takeProfit) {
            const profit = (currentPrice - position.entryPrice) * position.quantity;

            setPositions(prev => prev.map(p =>
              p.id === position.id
                ? { ...p, status: 'closed', profit }
                : p
            ));

            setTradeHistory(prev => [{
              ...position,
              status: 'closed',
              profit,
              closedAt: new Date()
            }, ...prev].slice(0, 50));

            updateStats(profit);
            addNotification(`Position closed: ${position.asset} - P/L: $${profit.toFixed(2)}`, profit > 0 ? 'success' : 'error');
