//@version=5
// Automated Volume-Price Breakout Strategy with Webhook Integration
// This strategy sends automated alerts that can trigger actual trades via webhooks

strategy("AUTOMATED Volume-Price Breakout",
     overlay=true,
     initial_capital=250,
     pyramiding=0,
     commission_type=strategy.commission.percent,
     commission_value=0.08,
     margin_long=1,
     margin_short=1)

// ========================================
// INPUTS
// ========================================

// Strategy Parameters
lenVol      = input.int(20,  "Volume MA Length", minval=1, group="Strategy")
volMult     = input.float(2, "Volume Spike Multiplier", step=0.1, group="Strategy")
lenTrend    = input.int(50,  "Trend EMA Length", minval=1, group="Strategy")
lenFast     = input.int(10,  "Fast EMA Length", minval=1, group="Strategy")

// Risk Management
riskPct     = input.float(2, "Risk % Per Trade", step=0.5, minval=0.1, maxval=10, group="Risk")
slPct       = input.float(2, "Stop Loss %", step=0.1, minval=0.1, group="Risk")
tpPct       = input.float(4, "Take Profit %", step=0.1, minval=0.2, group="Risk")
maxDailyLoss = input.float(5, "Max Daily Loss %", step=0.5, group="Risk")
maxPositions = input.int(3, "Max Concurrent Positions", minval=1, maxval=10, group="Risk")

// Automation Settings
enableAuto  = input.bool(false, "Enable Automated Trading", group="Automation")
useWebhook  = input.bool(true, "Use Webhook Alerts", group="Automation")
webhookURL  = input.string("https://your-webhook-url.com/api/trade", "Webhook URL", group="Automation")

// Advanced
useTrailing = input.bool(true, "Use Trailing Stop", group="Advanced")
trailPct    = input.float(1.5, "Trailing Stop %", step=0.1, group="Advanced")
confirmBars = input.int(1, "Confirmation Bars", minval=0, maxval=3, group="Advanced")

// ========================================
// CALCULATIONS
// ========================================

// EMAs
emaTrend = ta.ema(close, lenTrend)
emaFast  = ta.ema(close, lenFast)

// Volume
volMA    = ta.sma(volume, lenVol)
volSpike = volume > volMA * volMult

// Trend & Breakout Detection
upTrend      = close > emaTrend
breakAbove   = ta.crossover(close, emaFast)

// Confirmation Logic
var int barsAboveEMA = 0
if close > emaFast
    barsAboveEMA += 1
else
    barsAboveEMA := 0

confirmed = barsAboveEMA >= confirmBars

// Volume Confirmation (current or previous bar)
volConfirmed = volSpike or volSpike[1]

// Daily Loss Tracking
var float dailyPnL = 0.0
var int lastDay = dayofmonth
if dayofmonth != lastDay
    dailyPnL := 0.0
    lastDay := dayofmonth

// Update daily P/L
if strategy.closedtrades > strategy.closedtrades[1]
    dailyPnL += strategy.netprofit - strategy.netprofit[1]

dailyLossExceeded = dailyPnL < -(strategy.initial_capital * maxDailyLoss / 100)

// Position Count
positionCount = strategy.position_size != 0 ? 1 : 0
maxPositionsReached = positionCount >= maxPositions

// ========================================
// ENTRY CONDITIONS
// ========================================

longCondition = upTrend and breakAbove and volConfirmed and confirmed 
    and not dailyLossExceeded and not maxPositionsReached

// Position Sizing
stopPrice = close * (1.0 - slPct / 100.0)
riskValue = strategy.equity * (riskPct / 100.0)
qty = riskValue / math.abs(close - stopPrice)
qtySafe = math.max(qty, 0.001)

// ========================================
// WEBHOOK ALERT MESSAGES
// ========================================

// Entry Alert Message (JSON format for webhook)
entryMessage = '{"action":"buy","symbol":"' + syminfo.ticker + '","price":' + str.tostring(close) + 
     ',"quantity":' + str.tostring(qtySafe) + ',"stopLoss":' + str.tostring(stopPrice) + 
