// ========================================
// STRATEGY EXECUTION
// ========================================

if (longCondition and strategy.position_size == 0)
    if enableAuto
        strategy.entry("Long", strategy.long, qty=qtySafe, 
             alert_message=useWebhook ? entryMessage : "BUY SIGNAL: " + syminfo.ticker)

// Exit Conditions
if strategy.position_size > 0
    entryRef = strategy.position_avg_price
    tpPrice = entryRef * (1.0 + tpPct / 100.0)
    slPrice = entryRef * (1.0 - slPct / 100.0)

