// ========================================
// ALERTS
// ========================================

// Create automated alerts
alertcondition(longCondition, title="Long Entry Signal", 
     message='Long Signal: {{ticker}} @ {{close}}\nVolume Confirmed: {{volume}}\nEntry Price: {{close}}')

alertcondition(ta.crossunder(close, emaTrend) and strategy.position_size > 0, 
     title="Exit Signal - Trend Reversal",
     message='Exit Signal: {{ticker}} - Trend Reversal @ {{close}}')

// ========================================
// VISUALS
// ========================================

// Plot EMAs
plot(emaTrend, "Trend EMA", color=color.orange, linewidth=2)
plot(emaFast,  "Fast EMA",  color=color.blue, linewidth=1)

// Volume
plot(volMA, "Volume MA", color=color.yellow, style=plot.style_columns, display=display.pane)
barcolor(volSpike ? color.new(color.green, 60) : na, title="Volume Spike")

// Entry Signals
plotshape(longCondition, title="Long Signal", 
     style=shape.triangleup,
     location=location.belowbar, 
     color=color.lime, 
     size=size.small, 
     text="LONG")

// Draw SL/TP Lines
var line slLine = na
var line tpLine = na
var line entryLine = na

if strategy.position_size > 0
    entryRef = strategy.position_avg_price
    tpPrice = entryRef * (1.0 + tpPct / 100.0)
    slPrice = entryRef * (1.0 - slPct / 100.0)

    // Entry Line
    if na(entryLine)
        entryLine := line.new(bar_index, entryRef, bar_index + 1, entryRef, 
             color=color.blue, width=2, style=line.style_solid)
    else
        line.set_xy1(entryLine, bar_index, entryRef)
        line.set_xy2(entryLine, bar_index + 10, entryRef)

