             color=color.red, width=2, style=line.style_dashed)
    else
        line.set_xy1(slLine, bar_index, slPrice)
        line.set_xy2(slLine, bar_index + 10, slPrice)

    // Take Profit Line
    if na(tpLine)
        tpLine := line.new(bar_index, tpPrice, bar_index + 1, tpPrice, 
             color=color.green, width=2, style=line.style_dashed)
    else
        line.set_xy1(tpLine, bar_index, tpPrice)
        line.set_xy2(tpLine, bar_index + 10, tpPrice)
else
    if not na(slLine)
        line.delete(slLine)
        line.delete(tpLine)
        line.delete(entryLine)
        slLine := na
        tpLine := na
        entryLine := na

// ========================================
// STATISTICS TABLE
// ========================================

var table statsTable = table.new(position.top_right, 2, 8, 
     border_width=1, 
     bgcolor=color.new(color.black, 85),
     border_color=color.new(color.gray, 50))

if barstate.islast
    // Header
    table.cell(statsTable, 0, 0, "Bot Status", 
         bgcolor=enableAuto ? color.new(color.green, 70) : color.new(color.red, 70),
         text_color=color.white, text_size=size.normal)
    table.cell(statsTable, 1, 0, enableAuto ? "ACTIVE" : "PAUSED", 
