    winRate = strategy.closedtrades > 0 ? 
         (strategy.wintrades / strategy.closedtrades * 100) : 0
    table.cell(statsTable, 1, 2, str.tostring(winRate, "#.##") + "%", 
         text_color=winRate >= 50 ? color.green : color.red)

