    table.cell(statsTable, 0, 4, "Net Profit:", text_color=color.white)
    netProfitPct = (strategy.netprofit / strategy.initial_capital) * 100
    table.cell(statsTable, 1, 4, str.tostring(netProfitPct, "#.##") + "%", 
         text_color=netProfitPct > 0 ? color.green : color.red)

    table.cell(statsTable, 0, 5, "Daily P/L:", text_color=color.white)
    table.cell(statsTable, 1, 5, "$" + str.tostring(dailyPnL, "#.##"), 
         text_color=dailyPnL >= 0 ? color.green : color.red)

    table.cell(statsTable, 0, 6, "Max DD %:", text_color=color.white)
    maxDD = strategy.initial_capital > 0 ? 
         (strategy.max_drawdown / strategy.initial_capital) * 100 : 0
    table.cell(statsTable, 1, 6, str.tostring(maxDD, "#.##") + "%", text_color=color.red)

    table.cell(statsTable, 0, 7, "Position:", text_color=color.white)
    posStatus = strategy.position_size > 0 ? "LONG" : "NONE"
    table.cell(statsTable, 1, 7, posStatus, 
         text_color=strategy.position_size > 0 ? color.yellow : color.gray)

