    }

    // Crypto.com
    if (CONFIG.exchanges.cryptocom.apiKey) {
      exchangeClients.cryptocom = new ccxt.cryptocom({
        apiKey: CONFIG.exchanges.cryptocom.apiKey,
        secret: CONFIG.exchanges.cryptocom.secret
      });
