// =============================================

const tradingState = {
  dailyTrades: 0,
  lastResetDate: new Date().toDateString(),
  activePositions: new Map(),
  tradeHistory: []
};

function resetDailyCounters() {
  const today = new Date().toDateString();
  if (tradingState.lastResetDate !== today) {
    tradingState.dailyTrades = 0;
    tradingState.lastResetDate = today;
    console.log('📅 Daily counters reset');
  }
}

// =============================================
// SECURITY MIDDLEWARE
// =============================================

function validateWebhook(req, res, next) {
  // Check IP whitelist
  const clientIP = req.ip || req.connection.remoteAddress;
  if (CONFIG.allowedIPs.length > 0 && !CONFIG.allowedIPs.includes(clientIP)) {
    console.warn('⚠️ Unauthorized IP:', clientIP);
    return res.status(403).json({ error: 'Forbidden' });
  }

  // Verify signature if provided
  const signature = req.headers['x-webhook-signature'];
  if (signature) {
    const payload = JSON.stringify(req.body);
    const expectedSignature = crypto
      .createHmac('sha256', CONFIG.webhookSecret)
      .update(payload)
      .digest('hex');

    if (signature !== expectedSignature) {
      console.warn('⚠️ Invalid signature');
      return res.status(401).json({ error: 'Invalid signature' });
    }
  }

  next();
}

// =============================================
// TRADING LOGIC
// =============================================

async function executeTrade(signal) {
  try {
    resetDailyCounters();

    // Safety checks
    if (CONFIG.emergencyStop) {
      throw new Error('Emergency stop active - all trading halted');
    }

    if (tradingState.dailyTrades >= CONFIG.maxDailyTrades) {
      throw new Error('Daily trade limit reached');
    }

    const {
      action,
      symbol,
      price,
      quantity,
      stopLoss,
      takeProfit,
      exchange = CONFIG.defaultExchange,
      strategy = 'unknown'
    } = signal;

    // Validate inputs
    if (!action || !symbol) {
      throw new Error('Missing required fields: action, symbol');
    }

    if (!exchangeClients[exchange]) {
      throw new Error(`Exchange ${exchange} not configured`);
    }

    const client = exchangeClients[exchange];

    // Paper trading mode
    if (CONFIG.paperTrade) {
      console.log('📝 PAPER TRADE:', {
        action,
        symbol,
        price,
        quantity,
        stopLoss,
        takeProfit
      });

      tradingState.tradeHistory.push({
        timestamp: new Date(),
        action,
        symbol,
        price,
        quantity,
        mode: 'paper'
      });

      return {
        success: true,
        mode: 'paper',
        message: 'Paper trade executed'
      };
    }

    // REAL TRADING EXECUTION
    let result = {};

    if (action === 'buy') {
      // Calculate position size
      const positionValue = price * quantity;
      if (positionValue > CONFIG.maxPositionSize) {
        throw new Error(`Position size ${positionValue} exceeds max ${CONFIG.maxPositionSize}`);
      }

      // Place market buy order
      const order = await client.createMarketBuyOrder(symbol, quantity);
      console.log('✅ BUY order executed:', order.id);

      result.mainOrder = order;

      // Set stop loss if provided
      if (stopLoss) {
        const slOrder = await client.createOrder(
          symbol,
          'stop_loss_limit',
          'sell',
          quantity,
          stopLoss,
          { stopPrice: stopLoss }
        );
        console.log('✅ Stop loss set:', slOrder.id);
        result.stopLoss = slOrder;
      }

      // Set take profit if provided
      if (takeProfit) {
        const tpOrder = await client.createLimitSellOrder(
          symbol,
          quantity,
          takeProfit
        );
        console.log('✅ Take profit set:', tpOrder.id);
        result.takeProfit = tpOrder;
      }

      // Track position
      tradingState.activePositions.set(symbol, {
        entryPrice: price,
        quantity,
        stopLoss,
        takeProfit,
        timestamp: new Date()
      });

    } else if (action === 'sell') {
      // Close position
      const position = tradingState.activePositions.get(symbol);
      const sellQuantity = quantity || position?.quantity;

      if (!sellQuantity) {
        throw new Error('No quantity specified and no open position found');
      }

      // Place market sell order
      const order = await client.createMarketSellOrder(symbol, sellQuantity);
      console.log('✅ SELL order executed:', order.id);

      result.mainOrder = order;

      // Cancel any open SL/TP orders
      try {
        const openOrders = await client.fetchOpenOrders(symbol);
        for (const openOrder of openOrders) {
          await client.cancelOrder(openOrder.id, symbol);
          console.log('✅ Cancelled order:', openOrder.id);
        }
      } catch (error) {
        console.warn('⚠️ Error cancelling orders:', error.message);
      }

      // Remove from active positions
      tradingState.activePositions.delete(symbol);
    }

    // Update counters
    tradingState.dailyTrades++;
    tradingState.tradeHistory.push({
      timestamp: new Date(),
      action,
      symbol,
      price,
      quantity,
      strategy,
      result
    });

    return {
      success: true,
      mode: 'live',
      result
    };

  } catch (error) {
    console.error('❌ Trade execution error:', error.message);
    throw error;
  }
}

