  };

  // Calculate statistics
  const calculateStats = (trades) => {
    if (!trades.length) return;

    const today = new Date().toDateString();
    const todayTrades = trades.filter(t => 
      new Date(t.timestamp).toDateString() === today
    );

    const closedTrades = trades.filter(t => t.action === 'sell');
    const wins = closedTrades.filter(t => {
      const profit = (t.price - t.entryPrice) * t.quantity;
      return profit > 0;
    });

    const totalProfit = closedTrades.reduce((sum, t) => {
      const profit = (t.price - t.entryPrice) * t.quantity;
      return sum + profit;
    }, 0);

    const todayProfit = todayTrades.reduce((sum, t) => {
      if (t.action === 'sell') {
        const profit = (t.price - t.entryPrice) * t.quantity;
        return sum + profit;
      }
      return sum;
    }, 0);

    setStats({
      totalProfit,
      todayProfit,
      winRate: closedTrades.length > 0 ? (wins.length / closedTrades.length) * 100 : 0,
      totalTrades: trades.length,
      activePositions: positions.length,
      dailyTrades: todayTrades.length
