// =============================================
// Multi-Agent Trading Orchestrator
// =============================================
// Coordinates Claude, Gemini, Copilot, and Perplexity for trading decisions
// Save as: multi-agent-orchestrator.js

const axios = require('axios');
require('dotenv').config();

class MultiAgentOrchestrator {
  constructor() {
    this.agents = {
      claude: {
        name: 'Claude (Strategy Analysis)',
        apiKey: process.env.OPENROUTER_API_KEY,
        model: 'anthropic/claude-sonnet-4',
        endpoint: 'https://openrouter.ai/api/v1/chat/completions',
        specialty: 'Technical analysis and risk assessment'
      },
      gemini: {
        name: 'Gemini (Market Research)',
        apiKey: process.env.GEMINI_API_KEY,
        model: 'gemini-pro',
        endpoint: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-pro:generateContent',
        specialty: 'Market trends and sentiment analysis'
      },
      openai: {
        name: 'ChatGPT (Pattern Recognition)',
        apiKey: process.env.OPENAI_API_KEY,
        model: 'gpt-4-turbo-preview',
        endpoint: 'https://api.openai.com/v1/chat/completions',
        specialty: 'Historical pattern matching and predictions'
      },
      copilot: {
        name: 'Copilot (Meta-Agent Synthesis)',
        role: 'synthesizer',
        specialty: 'Combining insights and final decision making'
      }
    };

    this.consensusThreshold = 0.6; // 60% agreement required
    this.tradeHistory = [];
  }

  // =============================================
  // AGENT COMMUNICATION
  // =============================================

  async askClaude(prompt) {
    try {
      const response = await axios.post(
        this.agents.claude.endpoint,
        {
          model: this.agents.claude.model,
          messages: [
            {
              role: 'system',
              content: 'You are a professional crypto trading analyst specializing in technical analysis and risk management. Provide clear, actionable insights in JSON format.'
            },
            {
              role: 'user',
              content: prompt
            }
          ],
          temperature: 0.3
        },
        {
          headers: {
            'Authorization': `Bearer ${this.agents.claude.apiKey}`,
            'Content-Type': 'application/json'
          }
        }
      );

      return {
        agent: 'claude',
        response: response.data.choices[0].message.content,
        confidence: this.extractConfidence(response.data.choices[0].message.content)
      };
    } catch (error) {
      console.error('Claude error:', error.message);
      return { agent: 'claude', response: null, confidence: 0, error: error.message };
    }
  }

  async askGemini(prompt) {
    try {
      const response = await axios.post(
        `${this.agents.gemini.endpoint}?key=${this.agents.gemini.apiKey}`,
        {
          contents: [{
            parts: [{
              text: prompt
            }]
          }]
        }
      );

      const text = response.data.candidates[0].content.parts[0].text;

      return {
        agent: 'gemini',
        response: text,
        confidence: this.extractConfidence(text)
      };
    } catch (error) {
      console.error('Gemini error:', error.message);
      return { agent: 'gemini', response: null, confidence: 0, error: error.message };
    }
  }

  async askOpenAI(prompt) {
    try {
      const response = await axios.post(
        this.agents.openai.endpoint,
        {
          model: this.agents.openai.model,
          messages: [
            {
              role: 'system',
              content: 'You are a crypto trading expert specializing in pattern recognition and historical analysis. Respond in JSON format.'
            },
            {
              role: 'user',
              content: prompt
            }
          ],
          temperature: 0.3
        },
        {
          headers: {
            'Authorization': `Bearer ${this.agents.openai.apiKey}`,
            'Content-Type': 'application/json'
          }
        }
      );

      return {
        agent: 'openai',
        response: response.data.choices[0].message.content,
        confidence: this.extractConfidence(response.data.choices[0].message.content)
      };
    } catch (error) {
      console.error('OpenAI error:', error.message);
      return { agent: 'openai', response: null, confidence: 0, error: error.message };
    }
  }

  // =============================================
  // MARKET ANALYSIS ORCHESTRATION
  // =============================================

  async analyzeMarketSignal(signal) {
    console.log('\n🤖 Multi-Agent Analysis Started');
    console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n');

    const { symbol, action, price, volume, indicators } = signal;

    // Prepare analysis prompts
    const claudePrompt = `
Analyze this trading signal with a focus on risk management:

Symbol: ${symbol}
Action: ${action}
Price: ${price}
Volume: ${volume}
Indicators: ${JSON.stringify(indicators)}

Provide your analysis in this JSON format:
{
  "recommendation": "BUY|SELL|HOLD",
  "confidence": 0-100,
  "riskLevel": "LOW|MEDIUM|HIGH",
  "reasoning": "brief explanation",
  "concerns": ["list of concerns"]
}`;

    const geminiPrompt = `
Research current market sentiment and trends for ${symbol}:

Current price: ${price}
Action signal: ${action}

Analyze market conditions and provide response in JSON:
{
  "recommendation": "BUY|SELL|HOLD",
  "confidence": 0-100,
  "marketSentiment": "BULLISH|BEARISH|NEUTRAL",
  "keyFactors": ["list of factors"],
  "newsImpact": "brief summary"
}`;

    const openaiPrompt = `
Analyze historical patterns for ${symbol}:

Current price: ${price}
Action: ${action}
Volume: ${volume}

Identify similar historical patterns and provide JSON:
{
  "recommendation": "BUY|SELL|HOLD",
  "confidence": 0-100,
  "historicalMatch": "description",
  "successRate": 0-100,
  "warnings": ["list of warnings"]
}`;

    // Query all agents in parallel
    const [claudeResult, geminiResult, openaiResult] = await Promise.all([
      this.askClaude(claudePrompt),
      this.askGemini(geminiPrompt),
      this.askOpenAI(openaiPrompt)
    ]);

    // Display individual agent responses
    this.displayAgentResponse('Claude', claudeResult);
    this.displayAgentResponse('Gemini', geminiResult);
    this.displayAgentResponse('OpenAI', openaiResult);

    // Synthesize with Copilot (meta-agent logic)
    const synthesis = this.synthesizeResponses([
      claudeResult,
      geminiResult,
      openaiResult
    ]);

    console.log('\n🎯 Copilot Synthesis (Meta-Agent)');
    console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
    console.log(JSON.stringify(synthesis, null, 2));

    // Log to history
    this.tradeHistory.push({
      timestamp: new Date(),
      signal,
      agentResponses: { claudeResult, geminiResult, openaiResult },
      synthesis
    });

    return synthesis;
  }

  // =============================================
  // SYNTHESIS LOGIC (COPILOT META-AGENT)
  // =============================================

  synthesizeResponses(responses) {
    const validResponses = responses.filter(r => r.response !== null);

    if (validResponses.length === 0) {
      return {
        decision: 'ABORT',
        confidence: 0,
        reason: 'All agents failed to respond',
        agentConsensus: 0
      };
    }

    // Extract recommendations
    const recommendations = validResponses.map(r => {
      try {
        const parsed = JSON.parse(r.response);
        return {
          agent: r.agent,
          recommendation: parsed.recommendation,
          confidence: parsed.confidence || r.confidence,
          details: parsed
        };
      } catch (e) {
        // Fallback: extract from text
        const rec = this.extractRecommendation(r.response);
        return {
          agent: r.agent,
          recommendation: rec,
          confidence: r.confidence,
          details: { rawResponse: r.response }
        };
      }
    });

    // Calculate consensus
    const buyVotes = recommendations.filter(r => r.recommendation === 'BUY').length;
    const sellVotes = recommendations.filter(r => r.recommendation === 'SELL').length;
    const holdVotes = recommendations.filter(r => r.recommendation === 'HOLD').length;
    const totalVotes = recommendations.length;

    const consensus = Math.max(buyVotes, sellVotes, holdVotes) / totalVotes;
    const majorityAction = buyVotes > sellVotes && buyVotes > holdVotes ? 'BUY' :
                          sellVotes > buyVotes && sellVotes > holdVotes ? 'SELL' : 'HOLD';

    // Calculate weighted confidence
    const weightedConfidence = recommendations.reduce((sum, r) => 
      sum + (r.confidence * (r.recommendation === majorityAction ? 1 : 0.5)), 0
    ) / recommendations.length;

    // Final decision logic
    let decision;
    if (consensus >= this.consensusThreshold && weightedConfidence >= 60) {
      decision = majorityAction;
    } else {
      decision = 'HOLD'; // Default to caution
    }

    return {
      decision,
      confidence: Math.round(weightedConfidence),
      agentConsensus: Math.round(consensus * 100),
      votes: {
        buy: buyVotes,
        sell: sellVotes,
        hold: holdVotes
      },
      recommendations,
      reasoning: this.generateReasoning(recommendations, decision),
      shouldExecute: decision !== 'HOLD' && consensus >= this.consensusThreshold && weightedConfidence >= 60
    };
  }

  // =============================================
  // HELPER FUNCTIONS
  // =============================================

  extractConfidence(text) {
    // Try to find confidence in JSON or text
    const confidenceMatch = text.match(/"confidence":\s*(\d+)/i);
    if (confidenceMatch) return parseInt(confidenceMatch[1]);

    // Look for percentage
    const percentMatch = text.match(/(\d+)%\s*confident/i);
    if (percentMatch) return parseInt(percentMatch[1]);

    return 50; // Default medium confidence
  }

  extractRecommendation(text) {
    const upper = text.toUpperCase();
    if (upper.includes('BUY') || upper.includes('LONG')) return 'BUY';
    if (upper.includes('SELL') || upper.includes('SHORT')) return 'SELL';
    return 'HOLD';
  }

  generateReasoning(recommendations, decision) {
    const agreeingAgents = recommendations
      .filter(r => r.recommendation === decision)
      .map(r => r.agent);

    return `${agreeingAgents.length}/${recommendations.length} agents recommend ${decision}. ` +
           `Agreeing agents: ${agreeingAgents.join(', ')}. ` +
           `This represents sufficient consensus for action.`;
  }

  displayAgentResponse(name, result) {
    console.log(`\n📊 ${name} Response:`);
    console.log('─────────────────────────────────────────');

    if (result.error) {
      console.log(`❌ Error: ${result.error}`);
      return;
    }

    try {
      const parsed = JSON.parse(result.response);
      console.log(JSON.stringify(parsed, null, 2));
    } catch (e) {
      console.log(result.response);
    }

    console.log(`Confidence: ${result.confidence}%`);
  }

  // =============================================
  // WEBHOOK INTEGRATION
  // =============================================

  async processWebhookSignal(signal) {
    console.log('\n🔔 New Trading Signal Received');
    console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
    console.log(JSON.stringify(signal, null, 2));

    // Analyze with all agents
    const analysis = await this.analyzeMarketSignal(signal);

    // Decision gate
    if (!analysis.shouldExecute) {
      console.log('\n⚠️  TRADE REJECTED');
      console.log(`Reason: ${analysis.reasoning}`);
      console.log(`Consensus: ${analysis.agentConsensus}% (need ${this.consensusThreshold * 100}%)`);
      return {
        executed: false,
        reason: analysis.reasoning,
        analysis
      };
    }

    // Execute trade if consensus reached
    console.log('\n✅ TRADE APPROVED');
    console.log(`Decision: ${analysis.decision}`);
    console.log(`Confidence: ${analysis.confidence}%`);
    console.log(`Consensus: ${analysis.agentConsensus}%`);

    // Forward to webhook server
    try {
      const webhookUrl = process.env.WEBHOOK_SERVER_URL || 'http://localhost:3000/webhook';

      const tradePayload = {
        ...signal,
        action: analysis.decision.toLowerCase(),
        multiAgentApproved: true,
        agentConsensus: analysis.agentConsensus,
        confidence: analysis.confidence
      };

      const response = await axios.post(webhookUrl, tradePayload);

      console.log('\n🚀 Trade executed via webhook');
      console.log(response.data);

      return {
        executed: true,
        analysis,
        webhookResponse: response.data
      };
    } catch (error) {
      console.error('\n❌ Webhook execution failed:', error.message);
      return {
        executed: false,
        analysis,
        error: error.message
      };
    }
  }

  // =============================================
  // ANALYSIS ENDPOINTS
  // =============================================

  getTradeHistory(limit = 10) {
    return this.tradeHistory.slice(-limit);
  }

  getAgentStats() {
    const stats = {};

    for (const [key, agent] of Object.entries(this.agents)) {
      if (agent.role === 'synthesizer') continue;

      const agentTrades = this.tradeHistory.filter(t => 
        t.agentResponses[`${key}Result`]?.response !== null
      );

      stats[key] = {
        name: agent.name,
        specialty: agent.specialty,
        totalAnalyses: agentTrades.length,
        averageConfidence: agentTrades.length > 0 
          ? Math.round(
              agentTrades.reduce((sum, t) => 
                sum + (t.agentResponses[`${key}Result`]?.confidence || 0), 0
              ) / agentTrades.length
            )
          : 0
      };
    }

    return stats;
  }
}

// =============================================
// EXPRESS SERVER FOR MULTI-AGENT SYSTEM
// =============================================

const express = require('express');
const app = express();
app.use(express.json());

const orchestrator = new MultiAgentOrchestrator();

// Analyze signal endpoint
app.post('/analyze', async (req, res) => {
  try {
    const result = await orchestrator.processWebhookSignal(req.body);
    res.json(result);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Get agent statistics
app.get('/agent-stats', (req, res) => {
  res.json(orchestrator.getAgentStats());
});

// Get trade history
app.get('/history', (req, res) => {
  const limit = parseInt(req.query.limit) || 10;
  res.json(orchestrator.getTradeHistory(limit));
});

// Health check
app.get('/health', (req, res) => {
  res.json({
    status: 'online',
    agents: Object.keys(orchestrator.agents),
    consensusThreshold: orchestrator.consensusThreshold * 100 + '%'
  });
});

const PORT = process.env.ORCHESTRATOR_PORT || 3001;
app.listen(PORT, () => {
  console.log('\n╔════════════════════════════════════════╗');
  console.log('║  Multi-Agent Trading Orchestrator     ║');
  console.log('╚════════════════════════════════════════╝\n');
  console.log(`🤖 Agents: ${Object.keys(orchestrator.agents).join(', ')}`);
  console.log(`📡 Port: ${PORT}`);
  console.log(`🎯 Consensus Threshold: ${orchestrator.consensusThreshold * 100}%\n`);
});

module.exports = MultiAgentOrchestrator;

// =============================================
// .env File Validator & System Health Checker
// =============================================
// Save as: validate-config.js
// Run: node validate-config.js

const fs = require('fs');
const path = require('path');
const axios = require('axios');
require('dotenv').config();

class ConfigValidator {
  constructor() {
    this.errors = [];
    this.warnings = [];
    this.info = [];
    this.envPath = path.join(__dirname, '.env');
  }

  // =============================================
  // VALIDATION RULES
  // =============================================

  validateEnvFile() {
    console.log('\n🔍 Checking .env file...\n');

    // Check if .env exists
    if (!fs.existsSync(this.envPath)) {
      this.errors.push('.env file not found at: ' + this.envPath);
      return false;
    }

    this.info.push('✅ .env file found at: ' + this.envPath);

    // Read and parse .env
    const envContent = fs.readFileSync(this.envPath, 'utf8');
    const lines = envContent.split('\n');

    // Check for common issues
    this.checkDuplicateKeys(lines);
    this.checkEmptyValues(lines);
    this.checkQuotes(lines);
    this.checkComments(lines);

    return true;
  }

  checkDuplicateKeys(lines) {
    const keys = {};
    lines.forEach((line, index) => {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#')) {
        const [key] = trimmed.split('=');
        if (key) {
          const cleanKey = key.trim();
          if (keys[cleanKey]) {
            this.errors.push(`Duplicate key "${cleanKey}" on line ${index + 1} (first seen on line ${keys[cleanKey]})`);
          } else {
            keys[cleanKey] = index + 1;
          }
        }
      }
    });
  }

  checkEmptyValues(lines) {
    lines.forEach((line, index) => {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#') && trimmed.includes('=')) {
        const [key, ...valueParts] = trimmed.split('=');
        const value = valueParts.join('=').trim();

        if (!value && !key.includes('_SECRET') && !key.includes('_KEY') && !key.includes('API')) {
          this.warnings.push(`Empty value for "${key.trim()}" on line ${index + 1}`);
        }
      }
    });
  }

  checkQuotes(lines) {
    lines.forEach((line, index) => {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#') && trimmed.includes('=')) {
        const [key, ...valueParts] = trimmed.split('=');
        const value = valueParts.join('=').trim();

        // Check for mismatched quotes
        if ((value.startsWith('"') && !value.endsWith('"')) || 
            (value.startsWith("'") && !value.endsWith("'"))) {
          this.errors.push(`Mismatched quotes for "${key.trim()}" on line ${index + 1}`);
        }

        // Warn about spaces in unquoted values
        if (value.includes(' ') && !value.startsWith('"') && !value.startsWith("'")) {
          this.warnings.push(`Value with spaces should be quoted: "${key.trim()}" on line ${index + 1}`);
        }
      }
    });
  }

  checkComments(lines) {
    lines.forEach((line, index) => {
      if (line.includes('#') && !line.trim().startsWith('#')) {
        const [before, after] = line.split('#');
        if (before.includes('=')) {
          this.warnings.push(`Inline comment on line ${index + 1} - may cause parsing issues`);
        }
      }
    });
  }

  // =============================================
  // API KEY VALIDATION
  // =============================================

  validateApiKeys() {
    console.log('\n🔑 Validating API Keys...\n');

    const requiredKeys = {
      'GEMINI_API_KEY': {
        required: true,
        pattern: /^AIza[0-9A-Za-z_-]{35}$/,
        length: 39,
        description: 'Google Gemini API key'
      },
      'OPENAI_API_KEY': {
        required: true,
        pattern: /^sk-proj-[A-Za-z0-9_-]+$/,
        minLength: 20,
        description: 'OpenAI API key (project-based)'
      },
      'OPENROUTER_API_KEY': {
        required: true,
        pattern: /^sk-or-v1-[a-f0-9]{64}$/,
        length: 73,
        description: 'OpenRouter API key'
      },
      'COINMARKETCAP_API_KEY': {
        required: false,
        pattern: /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/,
        description: 'CoinMarketCap API key (UUID format)'
      },
      'BINANCE_API_KEY': {
        required: false,
        minLength: 64,
        description: 'Binance API key'
      },
      'BINANCE_SECRET': {
        required: false,
        minLength: 64,
        description: 'Binance API secret'
      },
      'WEBHOOK_SECRET': {
        required: true,
        minLength: 16,
        description: 'Webhook security secret (should be random)'
      }
    };

    for (const [key, rules] of Object.entries(requiredKeys)) {
      const value = process.env[key];

      if (!value) {
        if (rules.required) {
          this.errors.push(`❌ Missing required key: ${key} (${rules.description})`);
        } else {
          this.warnings.push(`⚠️  Optional key not set: ${key} (${rules.description})`);
        }
        continue;
      }

      // Check pattern
      if (rules.pattern && !rules.pattern.test(value)) {
        this.errors.push(`❌ Invalid format for ${key}: ${rules.description}`);
        continue;
      }

      // Check exact length
      if (rules.length && value.length !== rules.length) {
        this.errors.push(`❌ ${key} should be ${rules.length} characters (found ${value.length})`);
        continue;
      }

      // Check minimum length
      if (rules.minLength && value.length < rules.minLength) {
        this.errors.push(`❌ ${key} too short (min ${rules.minLength} chars, found ${value.length})`);
        continue;
      }

      this.info.push(`✅ ${key}: Valid (${rules.description})`);
    }
  }

  // =============================================
  // CONFIGURATION VALIDATION
  // =============================================

  validateConfiguration() {
    console.log('\n⚙️  Validating Configuration...\n');

    // Port validation
    const port = parseInt(process.env.PORT) || 3000;
    const orchestratorPort = parseInt(process.env.ORCHESTRATOR_PORT) || 3001;

    if (port < 1024 || port > 65535) {
      this.errors.push(`❌ Invalid PORT: ${port} (must be 1024-65535)`);
    } else {
      this.info.push(`✅ Webhook server port: ${port}`);
    }

    if (orchestratorPort < 1024 || orchestratorPort > 65535) {
      this.errors.push(`❌ Invalid ORCHESTRATOR_PORT: ${orchestratorPort}`);
    } else {
      this.info.push(`✅ Orchestrator port: ${orchestratorPort}`);
    }

    if (port === orchestratorPort) {
      this.errors.push(`❌ PORT and ORCHESTRATOR_PORT cannot be the same (${port})`);
    }

    // Paper trade validation
    const paperTrade = process.env.PAPER_TRADE;
    if (paperTrade !== 'true' && paperTrade !== 'false') {
      this.warnings.push(`⚠️  PAPER_TRADE should be 'true' or 'false' (found: ${paperTrade})`);
    } else if (paperTrade === 'false') {
      this.warnings.push(`⚠️  LIVE TRADING MODE ENABLED! Real money will be used!`);
    } else {
      this.info.push(`✅ Paper trading mode enabled (safe)`);
    }

    // Risk limits
    const maxPositionSize = parseFloat(process.env.MAX_POSITION_SIZE);
    const maxDailyTrades = parseInt(process.env.MAX_DAILY_TRADES);

    if (!maxPositionSize || maxPositionSize <= 0) {
      this.errors.push(`❌ Invalid MAX_POSITION_SIZE: ${process.env.MAX_POSITION_SIZE}`);
    } else {
      this.info.push(`✅ Max position size: $${maxPositionSize}`);
    }

    if (!maxDailyTrades || maxDailyTrades <= 0) {
      this.errors.push(`❌ Invalid MAX_DAILY_TRADES: ${process.env.MAX_DAILY_TRADES}`);
    } else {
      this.info.push(`✅ Max daily trades: ${maxDailyTrades}`);
    }

    // Webhook URL validation
    const webhookUrl = process.env.WEBHOOK_SERVER_URL;
    if (webhookUrl) {
      try {
        const url = new URL(webhookUrl);
        if (url.protocol !== 'http:' && url.protocol !== 'https:') {
          this.errors.push(`❌ WEBHOOK_SERVER_URL must use http:// or https://`);
        } else {
          this.info.push(`✅ Webhook URL: ${webhookUrl}`);
        }
      } catch (e) {
        this.errors.push(`❌ Invalid WEBHOOK_SERVER_URL format: ${webhookUrl}`);
      }
    }

    // Consensus threshold
    const threshold = parseFloat(process.env.CONSENSUS_THRESHOLD);
    if (threshold && (threshold < 0 || threshold > 1)) {
      this.errors.push(`❌ CONSENSUS_THRESHOLD must be 0-1 (found: ${threshold})`);
    } else if (threshold) {
      this.info.push(`✅ Consensus threshold: ${(threshold * 100).toFixed(0)}%`);
    }
  }

  // =============================================
  // SERVER CONNECTIVITY TESTS
  // =============================================

  async testServerConnectivity() {
    console.log('\n🌐 Testing Server Connectivity...\n');

    const webhookPort = process.env.PORT || 3000;
    const orchestratorPort = process.env.ORCHESTRATOR_PORT || 3001;

    // Test webhook server
    try {
      const response = await axios.get(`http://localhost:${webhookPort}/health`, {
        timeout: 3000
      });
      this.info.push(`✅ Webhook server responding on port ${webhookPort}`);
      console.log('   Response:', JSON.stringify(response.data, null, 2));
    } catch (error) {
      this.warnings.push(`⚠️  Webhook server not responding on port ${webhookPort}`);
      this.info.push(`   (This is OK if server isn't running yet)`);
    }

    // Test orchestrator
    try {
      const response = await axios.get(`http://localhost:${orchestratorPort}/health`, {
        timeout: 3000
      });
      this.info.push(`✅ Orchestrator responding on port ${orchestratorPort}`);
      console.log('   Response:', JSON.stringify(response.data, null, 2));
    } catch (error) {
      this.warnings.push(`⚠️  Orchestrator not responding on port ${orchestratorPort}`);
      this.info.push(`   (This is OK if server isn't running yet)`);
    }
  }

  // =============================================
  // SECURITY CHECKS
  // =============================================

  checkSecurity() {
    console.log('\n🔒 Security Checks...\n');

    // Check if .env is in .gitignore
    const gitignorePath = path.join(__dirname, '.gitignore');
    if (fs.existsSync(gitignorePath)) {
      const gitignore = fs.readFileSync(gitignorePath, 'utf8');
      if (gitignore.includes('.env')) {
        this.info.push(`✅ .env is in .gitignore (safe)`);
      } else {
        this.errors.push(`❌ .env NOT in .gitignore - API keys could be exposed!`);
      }
    } else {
      this.warnings.push(`⚠️  No .gitignore file found - create one and add .env`);
    }

    // Check webhook secret strength
    const secret = process.env.WEBHOOK_SECRET;
    if (secret) {
      if (secret === 'your-secret-key-here' || secret === 'change-this' || secret.length < 16) {
        this.errors.push(`❌ WEBHOOK_SECRET is weak or default - change it!`);
      } else if (secret.length < 32) {
        this.warnings.push(`⚠️  WEBHOOK_SECRET should be at least 32 characters`);
      } else {
        this.info.push(`✅ WEBHOOK_SECRET is strong`);
      }
    }

    // Check for default/example values
    const defaultValues = [
      'your_binance_api_key_here',
      'your_cryptocom_api_key_here',
      'your-super-secret-key-change-this'
    ];

    const envContent = fs.readFileSync(this.envPath, 'utf8');
    defaultValues.forEach(defaultVal => {
      if (envContent.includes(defaultVal)) {
        this.warnings.push(`⚠️  Found default placeholder: "${defaultVal}"`);
      }
    });
  }

  // =============================================
  // MAIN VALIDATION
  // =============================================

  async runAllValidations() {
    console.log('\n╔════════════════════════════════════════╗');
    console.log('║   .env Configuration Validator        ║');
    console.log('╚════════════════════════════════════════╝');

    // Run all validations
    this.validateEnvFile();
    this.validateApiKeys();
    this.validateConfiguration();
    this.checkSecurity();
    await this.testServerConnectivity();

    // Print results
    this.printResults();
  }

  printResults() {
    console.log('\n\n═══════════════════════════════════════');
    console.log('           VALIDATION RESULTS');
    console.log('═══════════════════════════════════════\n');

    // Errors
    if (this.errors.length > 0) {
      console.log('🚨 ERRORS (Must fix):\n');
      this.errors.forEach(err => console.log('  ' + err));
      console.log('');
    }

    // Warnings
    if (this.warnings.length > 0) {
      console.log('⚠️  WARNINGS (Should review):\n');
      this.warnings.forEach(warn => console.log('  ' + warn));
      console.log('');
    }

    // Info
    if (this.info.length > 0) {
      console.log('ℹ️  INFO:\n');
      this.info.forEach(info => console.log('  ' + info));
      console.log('');
    }

    // Summary
    console.log('═══════════════════════════════════════');
    console.log(`✅ Passed: ${this.info.filter(i => i.startsWith('✅')).length}`);
    console.log(`⚠️  Warnings: ${this.warnings.length}`);
    console.log(`❌ Errors: ${this.errors.length}`);
    console.log('═══════════════════════════════════════\n');

    if (this.errors.length === 0) {
      console.log('✅ Configuration is VALID! Ready to start servers.\n');
    } else {
      console.log('❌ Configuration has ERRORS. Fix them before starting.\n');
      process.exit(1);
    }
  }

