  • SELL: ${analysis.votes.sell}
  • HOLD: ${analysis.votes.hold}

Reasoning: ${analysis.reasoning}

${analysis.shouldExecute ? '✅ APPROVED - Trade will be executed' : '❌ REJECTED - Insufficient consensus'}
      `;

      return {
        content: [
          {
            type: 'text',
            text: resultText.trim(),
          },
        ],
      };
    } catch (error) {
      throw new Error(`Failed to analyze signal: ${error.message}`);
    }
  }

  async getAgentConsensus() {
    try {
      const response = await axios.get(`${ORCHESTRATOR_SERVER}/agent-stats`);
      const stats = response.data;

      const statsText = Object.entries(stats).map(([key, agent]) => `
${agent.name}:
  Specialty: ${agent.specialty}
  Total Analyses: ${agent.totalAnalyses}
  Avg Confidence: ${agent.averageConfidence}%
      `).join('\n');

      return {
        content: [
          {
            type: 'text',
            text: `AI Agent Statistics:\n${statsText}`,
          },
        ],
      };
    } catch (error) {
      throw new Error(`Failed to get agent stats: ${error.message}`);
    }
  }

  async emergencyStop(reason) {
    try {
      await axios.post(`${WEBHOOK_SERVER}/emergency-stop`);

      return {
        content: [
          {
            type: 'text',
            text: `🛑 EMERGENCY STOP ACTIVATED\n\nReason: ${reason}\n\nAll trading has been halted. Use 'resume_trading' to restart.`,
          },
        ],
      };
    } catch (error) {
      throw new Error(`Failed to activate emergency stop: ${error.message}`);
    }
  }

  async resumeTrading() {
    try {
      await axios.post(`${WEBHOOK_SERVER}/resume`);

      return {
        content: [
          {
            type: 'text',
            text: '✅ Trading resumed. Bot is now active.',
          },
        ],
      };
    } catch (error) {
      throw new Error(`Failed to resume trading: ${error.message}`);
    }
  }

  async getPerformanceStats(period) {
    try {
      const response = await axios.get(`${WEBHOOK_SERVER}/history?limit=100`);
      const trades = response.data.trades || [];

      // Calculate stats
      const closedTrades = trades.filter(t => t.action === 'sell');
      const wins = closedTrades.filter(t => {
        const profit = (t.price - (t.entryPrice || t.price)) * t.quantity;
        return profit > 0;
      });

      const totalProfit = closedTrades.reduce((sum, t) => {
        const profit = (t.price - (t.entryPrice || t.price)) * t.quantity;
        return sum + profit;
      }, 0);

      const winRate = closedTrades.length > 0 ? (wins.length / closedTrades.length * 100) : 0;

      const statsText = `
📈 Performance Statistics (${period})
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

Total Trades: ${trades.length}
Closed Trades: ${closedTrades.length}
Win Rate: ${winRate.toFixed(1)}%
Total Profit: $${totalProfit.toFixed(2)}

Wins: ${wins.length}
Losses: ${closedTrades.length - wins.length}
      `;

      return {
        content: [
          {
            type: 'text',
            text: statsText.trim(),
          },
        ],
      };
    } catch (error) {
      throw new Error(`Failed to get performance stats: ${error.message}`);
    }
  }

  async updateRiskSettings(settings) {
    // Note: This would need to be implemented in the webhook server
    // For now, return a message
    const settingsText = Object.entries(settings)
      .map(([key, value]) => `  ${key}: ${value}`)
      .join('\n');

    return {
      content: [
        {
          type: 'text',
          text: `⚠️  Risk settings update requested:\n\n${settingsText}\n\nNote: Settings will be applied on next server restart. Update your .env file with these values.`,
        },
      ],
    };
  }

  // =============================================
  // ERROR HANDLING
  // =============================================

  setupErrorHandling() {
    this.server.onerror = (error) => {
      console.error('[MCP Error]', error);
    };

    process.on('SIGINT', async () => {
      await this.server.close();
      process.exit(0);
    });
  }

  // =============================================
  // START SERVER
  // =============================================

  async run() {
    const transport = new StdioServerTransport();
    await this.server.connect(transport);

    console.error('Trading Bot MCP Server running on stdio');
  }
}

// =============================================
// MAIN
// =============================================

const server = new TradingBotMCPServer();
server.run().catch(console.error);

module.exports = TradingBotMCPServer;

