import React, { useState, useEffect } from 'react';
import { TrendingUp, TrendingDown, Activity, DollarSign, Youtube, Brain, Zap, AlertCircle } from 'lucide-react';

const FullStackTradingApp = () => {
  const [selectedAsset, setSelectedAsset] = useState('BTC/USDT');
  const [chartData, setChartData] = useState([]);
  const [orderbook, setOrderbook] = useState({ bids: [], asks: [] });
  const [youtubeSignals, setYoutubeSignals] = useState([]);
  const [aiConsensus, setAiConsensus] = useState(null);
  const [positions, setPositions] = useState([]);
  const [livePrices, setLivePrices] = useState({});

  const assets = ['BTC/USDT', 'ETH/USDT', 'CRO/USDT', 'SOL/USDT', 'AVAX/USDT'];

  // Generate candlestick data with opening range levels
  const generateCandlestickData = (asset) => {
    const basePrice = {
      'BTC/USDT': 42000,
      'ETH/USDT': 2200,
      'CRO/USDT': 0.12,
      'SOL/USDT': 95,
      'AVAX/USDT': 35
    }[asset];

    const candles = [];
    let currentPrice = basePrice;
    const now = Date.now();

    // Generate 100 candles (5-minute intervals)
    for (let i = 99; i >= 0; i--) {
      const timestamp = now - (i * 5 * 60 * 1000);
      const volatility = basePrice * 0.002;

      const open = currentPrice;
      const change = (Math.random() - 0.48) * volatility;
      const high = open + Math.abs(change) + (Math.random() * volatility);
      const low = open - Math.abs(change) - (Math.random() * volatility);
      const close = open + change;
      const volume = Math.random() * 1000000;

      candles.push({
        timestamp,
        open,
        high,
        low,
        close,
        volume
      });

      currentPrice = close;
    }

    // Add opening range levels from previous day
    const prevDayHigh = Math.max(...candles.slice(0, 20).map(c => c.high));
    const prevDayLow = Math.min(...candles.slice(0, 20).map(c => c.low));

    // 15-min opening range (first 3 candles)
    const or15High = Math.max(...candles.slice(-3).map(c => c.high));
    const or15Low = Math.min(...candles.slice(-3).map(c => c.low));

    return {
      candles,
      levels: {
        prevDayHigh,
        prevDayLow,
        or15High,
        or15Low
      }
    };
  };

  // Simulate YouTube sentiment analysis
  const analyzeYouTubeSentiment = (asset) => {
    const channels = [
      { name: 'The Trading Warrior', subscribers: '125K', credibility: 85 },
      { name: 'Lux Algo', subscribers: '310K', credibility: 92 },
      { name: 'Crypto Banter', subscribers: '450K', credibility: 78 }
    ];

    return channels.map(channel => {
      const videosLastWeek = Math.floor(Math.random() * 8) + 1;
      const mentions = Math.floor(Math.random() * videosLastWeek);
      const sentiment = Math.random() > 0.5 ? 'BULLISH' : 'BEARISH';
      const strength = Math.floor(Math.random() * 40) + 60;

      return {
        ...channel,
        asset,
        videosLastWeek,
        mentions,
        sentiment,
        strength,
        lastVideo: `${Math.floor(Math.random() * 48)} hours ago`,
        titleKeywords: sentiment === 'BULLISH' 
          ? ['MOON', 'BREAKOUT', 'RALLY', 'PUMP']
          : ['DUMP', 'CRASH', 'SELL', 'WARNING']
      };
    });
  };

  // Simulate AI consensus
  const getAIConsensus = () => {
    const agents = ['Claude', 'Gemini', 'GPT-4'];
    const signals = agents.map(agent => ({
      agent,
      signal: Math.random() > 0.5 ? 'BUY' : 'SELL',
      confidence: Math.floor(Math.random() * 30) + 70,
      reasoning: [
        'Strong volume confirmation',
        'RSI shows oversold',
        'MA crossover detected',
        'Support level holding'
      ][Math.floor(Math.random() * 4)]
    }));

    const buyVotes = signals.filter(s => s.signal === 'BUY').length;
    const consensus = buyVotes >= 2 ? 'BUY' : 'SELL';
    const avgConfidence = signals.reduce((sum, s) => sum + s.confidence, 0) / signals.length;

    return {
      signals,
      consensus,
      confidence: Math.round(avgConfidence),
      approved: avgConfidence >= 65 && buyVotes >= 2
    };
  };

  // Generate orderbook
  const generateOrderbook = (price) => {
    const bids = [];
    const asks = [];

    for (let i = 0; i < 15; i++) {
      bids.push({
        price: price * (1 - (i * 0.0001)),
        amount: Math.random() * 5,
        total: Math.random() * 50000
      });

      asks.push({
        price: price * (1 + (i * 0.0001)),
        amount: Math.random() * 5,
        total: Math.random() * 50000
      });
    }

    return { bids, asks };
  };

  // Initialize data
  useEffect(() => {
    const data = generateCandlestickData(selectedAsset);
    setChartData(data);

    const currentPrice = data.candles[data.candles.length - 1].close;
    setOrderbook(generateOrderbook(currentPrice));
    setYoutubeSignals(analyzeYouTubeSentiment(selectedAsset));
    setAiConsensus(getAIConsensus());

    setLivePrices(prev => ({
      ...prev,
      [selectedAsset]: currentPrice
    }));
  }, [selectedAsset]);

  // Simulate real-time updates
  useEffect(() => {
    const interval = setInterval(() => {
      if (chartData.candles && chartData.candles.length > 0) {
        const lastCandle = chartData.candles[chartData.candles.length - 1];
        const newPrice = lastCandle.close * (1 + (Math.random() - 0.5) * 0.001);

        setLivePrices(prev => ({
          ...prev,
          [selectedAsset]: newPrice
        }));

        setOrderbook(generateOrderbook(newPrice));
      }
    }, 2000);

    return () => clearInterval(interval);
  }, [chartData, selectedAsset]);

  // Render candlestick chart
  const renderCandlestickChart = () => {
    if (!chartData.candles) return null;

    const candles = chartData.candles.slice(-50); // Last 50 candles
    const maxPrice = Math.max(...candles.map(c => c.high));
    const minPrice = Math.min(...candles.map(c => c.low));
    const priceRange = maxPrice - minPrice;

    const width = 800;
    const height = 400;
    const candleWidth = width / candles.length - 2;

    const priceToY = (price) => {
      return height - ((price - minPrice) / priceRange * height);
    };

    return (
      <div className="relative bg-gray-900 rounded-lg p-4">
        <svg width={width} height={height} className="mx-auto">
          {/* Opening Range Levels */}
          {chartData.levels && (
            <>
              {/* Previous Day High */}
              <line
                x1={0}
                y1={priceToY(chartData.levels.prevDayHigh)}
                x2={width}
                y2={priceToY(chartData.levels.prevDayHigh)}
                stroke="#10b981"
                strokeWidth="1"
                strokeDasharray="5,5"
                opacity="0.6"
              />
              <text x={width - 120} y={priceToY(chartData.levels.prevDayHigh) - 5} fill="#10b981" fontSize="10">
                Prev Day High
              </text>

              {/* Previous Day Low */}
              <line
                x1={0}
                y1={priceToY(chartData.levels.prevDayLow)}
                x2={width}
                y2={priceToY(chartData.levels.prevDayLow)}
                stroke="#ef4444"
                strokeWidth="1"
                strokeDasharray="5,5"
                opacity="0.6"
              />
              <text x={width - 120} y={priceToY(chartData.levels.prevDayLow) + 12} fill="#ef4444" fontSize="10">
                Prev Day Low
              </text>

              {/* 15-min OR High */}
              <line
                x1={0}
                y1={priceToY(chartData.levels.or15High)}
                x2={width}
                y2={priceToY(chartData.levels.or15High)}
                stroke="#3b82f6"
                strokeWidth="1"
                strokeDasharray="3,3"
                opacity="0.5"
              />
              <text x={5} y={priceToY(chartData.levels.or15High) - 5} fill="#3b82f6" fontSize="10">
                15m OR High
              </text>

              {/* 15-min OR Low */}
              <line
                x1={0}
                y1={priceToY(chartData.levels.or15Low)}
                x2={width}
                y2={priceToY(chartData.levels.or15Low)}
                stroke="#f59e0b"
                strokeWidth="1"
                strokeDasharray="3,3"
                opacity="0.5"
              />
              <text x={5} y={priceToY(chartData.levels.or15Low) + 12} fill="#f59e0b" fontSize="10">
                15m OR Low
              </text>
            </>
          )}

          {/* Candlesticks */}
          {candles.map((candle, i) => {
            const x = i * (candleWidth + 2);
            const isGreen = candle.close > candle.open;
            const color = isGreen ? '#10b981' : '#ef4444';

            const bodyTop = priceToY(Math.max(candle.open, candle.close));
            const bodyBottom = priceToY(Math.min(candle.open, candle.close));
            const bodyHeight = Math.max(bodyBottom - bodyTop, 1);

            return (
              <g key={i}>
                {/* Wick */}
                <line
                  x1={x + candleWidth / 2}
                  y1={priceToY(candle.high)}
                  x2={x + candleWidth / 2}
                  y2={priceToY(candle.low)}
                  stroke={color}
                  strokeWidth="1"
                />
                {/* Body */}
                <rect
                  x={x}
                  y={bodyTop}
                  width={candleWidth}
                  height={bodyHeight}
                  fill={color}
                  opacity="0.9"
                />
              </g>
            );
          })}
        </svg>

        {/* Price Labels */}
        <div className="absolute top-4 right-4 bg-gray-800 p-3 rounded">
          <div className="text-white text-sm space-y-1">
            <div className="flex justify-between gap-4">
              <span className="text-gray-400">Current:</span>
              <span className="font-bold">${livePrices[selectedAsset]?.toFixed(4)}</span>
            </div>
            {chartData.levels && (
              <>
                <div className="flex justify-between gap-4">
                  <span className="text-green-400">PDH:</span>
                  <span>${chartData.levels.prevDayHigh.toFixed(4)}</span>
                </div>
                <div className="flex justify-between gap-4">
                  <span className="text-red-400">PDL:</span>
                  <span>${chartData.levels.prevDayLow.toFixed(4)}</span>
                </div>
                <div className="flex justify-between gap-4">
                  <span className="text-blue-400">OR15H:</span>
                  <span>${chartData.levels.or15High.toFixed(4)}</span>
                </div>
                <div className="flex justify-between gap-4">
                  <span className="text-yellow-400">OR15L:</span>
                  <span>${chartData.levels.or15Low.toFixed(4)}</span>
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    );
  };

  // Render volume chart
  const renderVolumeChart = () => {
    if (!chartData.candles) return null;

    const candles = chartData.candles.slice(-50);
    const maxVolume = Math.max(...candles.map(c => c.volume));

    const width = 800;
    const height = 100;
    const barWidth = width / candles.length - 1;

    return (
      <svg width={width} height={height} className="mx-auto">
        {candles.map((candle, i) => {
          const barHeight = (candle.volume / maxVolume) * height;
          const isGreen = candle.close > candle.open;
          const color = isGreen ? '#10b981' : '#ef4444';

          return (
            <rect
              key={i}
              x={i * (barWidth + 1)}
              y={height - barHeight}
              width={barWidth}
              height={barHeight}
              fill={color}
              opacity="0.6"
            />
          );
        })}
      </svg>
    );
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 via-blue-900 to-gray-900 p-4">
      <div className="max-w-[1800px] mx-auto">
        {/* Header */}
        <div className="bg-gradient-to-r from-blue-600 to-purple-600 rounded-xl p-6 mb-6 shadow-2xl">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <Activity className="text-white" size={40} />
              <div>
                <h1 className="text-3xl font-bold text-white">AI Trading Terminal</h1>
                <p className="text-blue-100">Full-Stack Real-Time Analysis</p>
              </div>
            </div>

            {/* Asset Selector */}
            <div className="flex gap-2">
              {assets.map(asset => (
                <button
                  key={asset}
                  onClick={() => setSelectedAsset(asset)}
                  className={`px-4 py-2 rounded-lg font-semibold transition-all ${
                    selectedAsset === asset
                      ? 'bg-white text-blue-600'
                      : 'bg-white/20 text-white hover:bg-white/30'
                  }`}
                >
                  {asset.split('/')[0]}
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
          {/* Left Column - Charts */}
          <div className="xl:col-span-2 space-y-6">
            {/* Main Chart */}
            <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-xl font-bold text-white">{selectedAsset} Chart</h2>
                <div className="flex items-center gap-2">
                  <span className={`px-3 py-1 rounded text-sm font-bold ${
                    livePrices[selectedAsset] > chartData.candles?.[0]?.close
                      ? 'bg-green-500/20 text-green-400'
                      : 'bg-red-500/20 text-red-400'
                  }`}>
                    {livePrices[selectedAsset] > chartData.candles?.[0]?.close ? '↑' : '↓'} 
                    ${livePrices[selectedAsset]?.toFixed(4)}
                  </span>
                </div>
              </div>
              {renderCandlestickChart()}
              <div className="mt-2">
                {renderVolumeChart()}
              </div>

              {/* Legend */}
              <div className="mt-4 flex flex-wrap gap-4 text-sm">
                <div className="flex items-center gap-2">
                  <div className="w-8 h-0.5 bg-green-500"></div>
                  <span className="text-gray-300">Prev Day High</span>
                </div>
                <div className="flex items-center gap-2">
                  <div className="w-8 h-0.5 bg-red-500"></div>
