              </div>
            </div>

            {/* Trading Signals Summary */}
            <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
              <h2 className="text-xl font-bold text-white mb-4">Signal Summary</h2>

