                    <Brain className="text-purple-400" size={20} />
                    <span className="text-gray-300">AI Consensus</span>
                  </div>
                  <span className={`font-bold ${
                    aiConsensus?.consensus === 'BUY' ? 'text-green-400' : 'text-red-400'
                  }`}>
                    {aiConsensus?.consensus}
                  </span>
                </div>

                <div className="flex items-center justify-between p-3 bg-white/5 rounded">
                  <div className="flex items-center gap-2">
                    <Youtube className="text-red-500" size={20} />
                    <span className="text-gray-300">YouTube Sentiment</span>
                  </div>
                  <span className={`font-bold ${
                    youtubeSignals.filter(s => s.sentiment === 'BULLISH').length >= 2
                      ? 'text-green-400'
                      : 'text-red-400'
                  }`}>
                    {youtubeSignals.filter(s => s.sentiment === 'BULLISH').length >= 2 ? 'BULLISH' : 'BEARISH'}
                  </span>
                </div>

                <div className="flex items-center justify-between p-3 bg-white/5 rounded">
                  <div className="flex items-center gap-2">
                    <Zap className="text-yellow-400" size={20} />
                    <span className="text-gray-300">Technical</span>
                  </div>
                  <span className="font-bold text-blue-400">NEUTRAL</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FullStackTradingApp;

