// =============================================
// Crypto News Integration API
// =============================================
// Aggregates news from multiple sources with AI sentiment analysis
// Save as: news-integration-api.js

const express = require('express');
const axios = require('axios');
const cheerio = require('cheerio');
require('dotenv').config();

const app = express();
app.use(express.json());

// Enable CORS for frontend
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Headers', 'Content-Type');
  next();
});

// =============================================
// NEWS SOURCES CONFIGURATION
// =============================================

const NEWS_SOURCES = {
  newsapi: {
    enabled: true,
    key: process.env.NEWS_API_KEY,
    endpoint: 'https://newsapi.org/v2/everything'
  },
  cryptopanic: {
    enabled: true,
    endpoint: 'https://cryptopanic.com/api/v1/posts/',
    key: process.env.CRYPTOPANIC_KEY || 'free'
  },
  coindesk: {
    enabled: true,
    rss: 'https://www.coindesk.com/arc/outboundfeeds/rss/'
  },
  cointelegraph: {
    enabled: true,
    rss: 'https://cointelegraph.com/rss'
  },
  decrypt: {
    enabled: true,
    rss: 'https://decrypt.co/feed'
  }
};

// =============================================
// AI SENTIMENT ANALYSIS
// =============================================

class NewsSentimentAnalyzer {
  constructor() {
    this.bullishKeywords = [
      'surge', 'rally', 'breakout', 'bull', 'moon', 'pump', 'soar', 
      'gain', 'rise', 'adoption', 'partnership', 'upgrade', 'launch',
      'positive', 'growth', 'institutional', 'etf', 'approval'
    ];

    this.bearishKeywords = [
      'crash', 'dump', 'plunge', 'bear', 'decline', 'drop', 'fall',
      'lose', 'scam', 'hack', 'ban', 'regulation', 'lawsuit', 'sec',
      'warning', 'risk', 'concern', 'investigation', 'fraud'
    ];

    this.highImpactWords = [
      'sec', 'fed', 'etf', 'institutional', 'ban', 'regulation',
      'hack', 'exploit', 'billion', 'major', 'breaking'
    ];
  }

  analyzeSentiment(text) {
    const lower = text.toLowerCase();

    let bullishScore = 0;
    let bearishScore = 0;
    let impactScore = 0;

    // Count keyword matches
    this.bullishKeywords.forEach(word => {
      if (lower.includes(word)) bullishScore++;
    });

    this.bearishKeywords.forEach(word => {
      if (lower.includes(word)) bearishScore++;
    });

    this.highImpactWords.forEach(word => {
      if (lower.includes(word)) impactScore++;
    });

    // Calculate sentiment
    const total = bullishScore + bearishScore;
    let sentiment = 'NEUTRAL';
    let confidence = 50;

    if (total > 0) {
      const bullishPercent = (bullishScore / total) * 100;
      confidence = Math.abs(bullishPercent - 50) + 50;

      if (bullishPercent > 60) sentiment = 'BULLISH';
      else if (bullishPercent < 40) sentiment = 'BEARISH';
    }

    // Impact level
    let impact = 'LOW';
    if (impactScore >= 3) impact = 'HIGH';
    else if (impactScore >= 1) impact = 'MEDIUM';

    return {
      sentiment,
      confidence: Math.round(confidence),
      impact,
      bullishScore,
      bearishScore,
      impactScore
    };
  }

  async analyzeWithAI(text, symbol) {
    // Use OpenAI/Claude for deep analysis
    try {
      const response = await axios.post(
        'https://api.openai.com/v1/chat/completions',
        {
          model: 'gpt-4-turbo-preview',
          messages: [
            {
              role: 'system',
              content: `You are a crypto news sentiment analyzer. Analyze news for ${symbol} and respond with JSON only: {"sentiment": "BULLISH|BEARISH|NEUTRAL", "confidence": 0-100, "impact": "HIGH|MEDIUM|LOW", "reasoning": "brief explanation", "priceImpact": "UP|DOWN|NONE"}`
            },
            {
              role: 'user',
              content: text
            }
          ],
          temperature: 0.3,
          max_tokens: 200
        },
        {
          headers: {
            'Authorization': `Bearer ${process.env.OPENAI_API_KEY}`,
            'Content-Type': 'application/json'
          }
        }
      );

      const result = JSON.parse(response.data.choices[0].message.content);
      return result;
    } catch (error) {
      console.error('AI analysis failed:', error.message);
      return this.analyzeSentiment(text);
    }
  }
}

const sentimentAnalyzer = new NewsSentimentAnalyzer();

// =============================================
// NEWS FETCHERS
// =============================================

// Fetch from NewsAPI
async function fetchNewsAPI(symbol) {
  if (!NEWS_SOURCES.newsapi.enabled || !NEWS_SOURCES.newsapi.key) {
    return [];
  }

  try {
    const response = await axios.get(NEWS_SOURCES.newsapi.endpoint, {
      params: {
        q: `${symbol} OR crypto OR bitcoin`,
        language: 'en',
        sortBy: 'publishedAt',
        pageSize: 20,
        apiKey: NEWS_SOURCES.newsapi.key
      }
    });

    return response.data.articles.map(article => ({
      source: 'NewsAPI',
      title: article.title,
      description: article.description,
      url: article.url,
      image: article.urlToImage,
      publishedAt: article.publishedAt,
      author: article.source.name
    }));
  } catch (error) {
    console.error('NewsAPI error:', error.message);
    return [];
  }
}

// Fetch from CryptoPanic
async function fetchCryptoPanic(symbol) {
  if (!NEWS_SOURCES.cryptopanic.enabled) return [];

  try {
    const currencies = {
      'BTC': 'BTC',
      'ETH': 'ETH',
      'CRO': 'CRO',
      'SOL': 'SOL',
      'AVAX': 'AVAX'
    };

    const currency = currencies[symbol] || symbol;

    const response = await axios.get(NEWS_SOURCES.cryptopanic.endpoint, {
      params: {
        auth_token: NEWS_SOURCES.cryptopanic.key,
        currencies: currency,
        kind: 'news',
        filter: 'hot'
      }
    });

    return response.data.results.slice(0, 20).map(item => ({
      source: 'CryptoPanic',
      title: item.title,
      description: item.title,
      url: item.url,
      image: null,
      publishedAt: item.created_at,
      author: item.source.title,
      votes: {
        positive: item.votes?.positive || 0,
        negative: item.votes?.negative || 0,
        liked: item.votes?.liked || 0
      }
    }));
  } catch (error) {
    console.error('CryptoPanic error:', error.message);
    return [];
  }
}

// Scrape CoinDesk RSS
async function fetchCoinDesk() {
  if (!NEWS_SOURCES.coindesk.enabled) return [];

  try {
    const response = await axios.get(NEWS_SOURCES.coindesk.rss);
    const $ = cheerio.load(response.data, { xmlMode: true });

    const articles = [];
    $('item').slice(0, 15).each((i, elem) => {
      articles.push({
        source: 'CoinDesk',
        title: $(elem).find('title').text(),
        description: $(elem).find('description').text(),
        url: $(elem).find('link').text(),
        image: $(elem).find('enclosure').attr('url'),
        publishedAt: $(elem).find('pubDate').text(),
        author: 'CoinDesk'
      });
    });

    return articles;
  } catch (error) {
    console.error('CoinDesk error:', error.message);
    return [];
  }
}

// Scrape Cointelegraph RSS
async function fetchCointelegraph() {
  if (!NEWS_SOURCES.cointelegraph.enabled) return [];

  try {
    const response = await axios.get(NEWS_SOURCES.cointelegraph.rss);
    const $ = cheerio.load(response.data, { xmlMode: true });

    const articles = [];
    $('item').slice(0, 15).each((i, elem) => {
      articles.push({
        source: 'Cointelegraph',
        title: $(elem).find('title').text(),
        description: $(elem).find('description').text(),
        url: $(elem).find('link').text(),
        image: $(elem).find('enclosure').attr('url'),
        publishedAt: $(elem).find('pubDate').text(),
        author: 'Cointelegraph'
      });
    });

    return articles;
  } catch (error) {
    console.error('Cointelegraph error:', error.message);
    return [];
  }
}

// =============================================
// AGGREGATION & ANALYSIS
// =============================================

async function aggregateNews(symbol) {
  console.log(`Fetching news for ${symbol}...`);

  // Fetch from all sources in parallel
  const [newsapi, cryptopanic, coindesk, cointelegraph] = await Promise.all([
    fetchNewsAPI(symbol),
    fetchCryptoPanic(symbol),
    fetchCoinDesk(),
    fetchCointelegraph()
  ]);

  // Combine all articles
  let allArticles = [
    ...newsapi,
    ...cryptopanic,
    ...coindesk,
    ...cointelegraph
  ];

  // Filter relevant articles for symbol
  const symbolKeywords = [symbol, symbol.toLowerCase()];
  allArticles = allArticles.filter(article => {
    const text = `${article.title} ${article.description}`.toLowerCase();
    return symbolKeywords.some(keyword => text.includes(keyword.toLowerCase()));
  });

  // Remove duplicates by title similarity
  const uniqueArticles = [];
  const seenTitles = new Set();

  for (const article of allArticles) {
    const normalizedTitle = article.title.toLowerCase().replace(/[^a-z0-9]/g, '');
    if (!seenTitles.has(normalizedTitle)) {
      seenTitles.add(normalizedTitle);
      uniqueArticles.push(article);
    }
  }

  // Analyze sentiment for each article
  const analyzedArticles = uniqueArticles.map(article => {
    const analysis = sentimentAnalyzer.analyzeSentiment(
      `${article.title} ${article.description}`
    );

    return {
      ...article,
      sentiment: analysis.sentiment,
      confidence: analysis.confidence,
      impact: analysis.impact,
      score: calculateNewsScore(article, analysis)
    };
  });

  // Sort by score and recency
  analyzedArticles.sort((a, b) => {
    const scoreA = a.score + (new Date(a.publishedAt).getTime() / 1000000000);
    const scoreB = b.score + (new Date(b.publishedAt).getTime() / 1000000000);
    return scoreB - scoreA;
  });

  return analyzedArticles.slice(0, 30);
}

function calculateNewsScore(article, analysis) {
  let score = 0;

  // Impact weight
  if (analysis.impact === 'HIGH') score += 50;
  else if (analysis.impact === 'MEDIUM') score += 25;

  // Confidence weight
  score += analysis.confidence / 2;

  // Source credibility
  const sourceScores = {
    'CoinDesk': 30,
    'Cointelegraph': 25,
    'CryptoPanic': 20,
    'NewsAPI': 15
  };
  score += sourceScores[article.source] || 10;

  // Votes (if available)
  if (article.votes) {
    score += (article.votes.positive - article.votes.negative) * 2;
  }

  return score;
}

// Calculate overall market sentiment
function calculateMarketSentiment(articles) {
  let bullishCount = 0;
  let bearishCount = 0;
  let totalConfidence = 0;
  let highImpactCount = 0;

  articles.forEach(article => {
    if (article.sentiment === 'BULLISH') bullishCount++;
    if (article.sentiment === 'BEARISH') bearishCount++;
    if (article.impact === 'HIGH') highImpactCount++;
    totalConfidence += article.confidence;
  });

  const total = bullishCount + bearishCount;
  let overallSentiment = 'NEUTRAL';

  if (total > 0) {
    const bullishPercent = (bullishCount / total) * 100;
    if (bullishPercent > 60) overallSentiment = 'BULLISH';
    else if (bullishPercent < 40) overallSentiment = 'BEARISH';
  }

  return {
    sentiment: overallSentiment,
    bullishCount,
    bearishCount,
    neutralCount: articles.length - bullishCount - bearishCount,
    avgConfidence: Math.round(totalConfidence / articles.length),
    highImpactCount,
    totalArticles: articles.length
  };
}

// =============================================
// API ENDPOINTS
// =============================================

// Get news for specific symbol
app.get('/api/news/:symbol', async (req, res) => {
  try {
    const symbol = req.params.symbol.toUpperCase();
    const articles = await aggregateNews(symbol);
    const marketSentiment = calculateMarketSentiment(articles);

    res.json({
      symbol,
      timestamp: new Date().toISOString(),
      marketSentiment,
      articles,
      total: articles.length
    });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Get trending news (all crypto)
app.get('/api/news/trending', async (req, res) => {
  try {
    const articles = await aggregateNews('crypto');
    const marketSentiment = calculateMarketSentiment(articles);

    res.json({
      timestamp: new Date().toISOString(),
      marketSentiment,
      articles: articles.slice(0, 20),
      total: articles.length
    });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Get breaking news (high impact only)
app.get('/api/news/breaking', async (req, res) => {
  try {
    const articles = await aggregateNews('crypto');
    const breaking = articles.filter(a => a.impact === 'HIGH');

    res.json({
      timestamp: new Date().toISOString(),
      articles: breaking,
      total: breaking.length
    });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Analyze specific article with AI
app.post('/api/news/analyze', async (req, res) => {
  try {
    const { text, symbol } = req.body;
    const analysis = await sentimentAnalyzer.analyzeWithAI(text, symbol);

    res.json(analysis);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
