  res.json({
    status: 'online',
    sources: Object.keys(NEWS_SOURCES).filter(s => NEWS_SOURCES[s].enabled),
    timestamp: new Date().toISOString()
  });
});

// =============================================
// START SERVER
// =============================================

const PORT = process.env.NEWS_API_PORT || 3003;

app.listen(PORT, () => {
