# SVS Server Firewall Configuration and File System Check
# Run this script as Administrator

# Configuration
$svsServerPort = 8080  # Change this to your SVS server port
$svsServerPath = "C:\Path\To\Your\SVSServer.exe"  # Change to your SVS server executable path
$ruleName = "SVS Server Access"

Write-Host "=== SVS Server Firewall & File System Check ===" -ForegroundColor Cyan
Write-Host ""

# Check if running as Administrator
$isAdmin = ([Security.Principal.WindowsPrincipal] [Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)

if (-not $isAdmin) {
    Write-Host "ERROR: This script must be run as Administrator!" -ForegroundColor Red
    Write-Host "Right-click PowerShell and select 'Run as Administrator'" -ForegroundColor Yellow
    exit 1
}

Write-Host "[1/3] Configuring Windows Firewall Rules..." -ForegroundColor Green

# Remove existing rule if it exists
$existingRule = Get-NetFirewallRule -DisplayName $ruleName -ErrorAction SilentlyContinue
if ($existingRule) {
    Write-Host "Removing existing firewall rule..." -ForegroundColor Yellow
    Remove-NetFirewallRule -DisplayName $ruleName
}

# Add inbound rule for SVS Server (TCP)
try {
    New-NetFirewallRule -DisplayName $ruleName `
                        -Direction Inbound `
                        -Protocol TCP `
                        -LocalPort $svsServerPort `
                        -Action Allow `
                        -Profile Domain,Private,Public `
                        -Enabled True
    Write-Host "✓ Inbound TCP rule created for port $svsServerPort" -ForegroundColor Green
} catch {
    Write-Host "✗ Failed to create inbound rule: $_" -ForegroundColor Red
}

# Add outbound rule for SVS Server (TCP)
try {
    New-NetFirewallRule -DisplayName "$ruleName - Outbound" `
                        -Direction Outbound `
                        -Protocol TCP `
                        -LocalPort $svsServerPort `
                        -Action Allow `
                        -Profile Domain,Private,Public `
                        -Enabled True
    Write-Host "✓ Outbound TCP rule created for port $svsServerPort" -ForegroundColor Green
} catch {
    Write-Host "✗ Failed to create outbound rule: $_" -ForegroundColor Red
}

# Add program-based rule if path exists
if (Test-Path $svsServerPath) {
    try {
        New-NetFirewallRule -DisplayName "$ruleName - Program" `
                            -Direction Inbound `
                            -Program $svsServerPath `
                            -Action Allow `
                            -Profile Domain,Private,Public `
                            -Enabled True
        Write-Host "✓ Program-based rule created for $svsServerPath" -ForegroundColor Green
    } catch {
        Write-Host "✗ Failed to create program rule: $_" -ForegroundColor Red
    }
} else {
    Write-Host "⚠ SVS Server executable not found at: $svsServerPath" -ForegroundColor Yellow
    Write-Host "  Update the `$svsServerPath variable if you need program-based rules" -ForegroundColor Yellow
}

Write-Host ""
Write-Host "[2/3] Checking File System..." -ForegroundColor Green

# Get all drives
$drives = Get-PSDrive -PSProvider FileSystem | Where-Object { $_.Used -ne $null }

foreach ($drive in $drives) {
    $driveName = $drive.Name + ":"
    Write-Host ""
    Write-Host "Checking drive: $driveName" -ForegroundColor Cyan

    # Check disk space
    $usedGB = [math]::Round($drive.Used / 1GB, 2)
    $freeGB = [math]::Round($drive.Free / 1GB, 2)
    $totalGB = [math]::Round(($drive.Used + $drive.Free) / 1GB, 2)
    $percentFree = [math]::Round(($drive.Free / ($drive.Used + $drive.Free)) * 100, 2)

    Write-Host "  Total: $totalGB GB | Used: $usedGB GB | Free: $freeGB GB ($percentFree% free)"

    if ($percentFree -lt 10) {
        Write-Host "  ⚠ WARNING: Low disk space!" -ForegroundColor Red
    } elseif ($percentFree -lt 20) {
        Write-Host "  ⚠ Disk space getting low" -ForegroundColor Yellow
    } else {
        Write-Host "  ✓ Disk space OK" -ForegroundColor Green
    }

    # Run CHKDSK status check (non-intrusive)
    Write-Host "  Running file system check..."
    $chkdskOutput = chkdsk $driveName 2>&1

    if ($chkdskOutput -match "Windows has scanned the file system and found no problems") {
        Write-Host "  ✓ File system is healthy" -ForegroundColor Green
    } elseif ($chkdskOutput -match "errors") {
        Write-Host "  ⚠ File system may have errors - run 'chkdsk $driveName /F' to fix" -ForegroundColor Yellow
    } else {
        Write-Host "  ℹ File system check completed" -ForegroundColor Cyan
    }
}

Write-Host ""
Write-Host "[3/3] Summary" -ForegroundColor Green
Write-Host "✓ Firewall rules configured for port $svsServerPort" -ForegroundColor Green
Write-Host "✓ File system check completed" -ForegroundColor Green
Write-Host ""
Write-Host "To verify firewall rules, run:" -ForegroundColor Cyan
Write-Host "  Get-NetFirewallRule -DisplayName '*SVS Server*' | Format-Table" -ForegroundColor White
Write-Host ""
Write-Host "To run a full disk check with repair (requires restart):" -ForegroundColor Cyan
Write-Host "  chkdsk C: /F /R" -ForegroundColor White
Write-Host ""

{
  "manifest_version": 3,
  "name": "Close All Tabs with Warning",
  "version": "1.0",
  "description": "Closes all tabs after showing a warning dialog",
  "permissions": [
    "tabs",
    "storage"
  ],
  "action": {
    "default_popup": "popup.html",
    "default_icon": {
      "16": "icon16.png",
      "48": "icon48.png",
      "128": "icon128.png"
    }
  },
  "background": {
    "service_worker": "background.js"
  },
  "commands": {
    "close-all-tabs": {
      "suggested_key": {
        "default": "Ctrl+Shift+Q",
        "mac": "Command+Shift+Q"
      },
      "description": "Close all tabs with warning"
    },
    "unpin-all-tabs": {
      "suggested_key": {
        "default": "Ctrl+Shift+U",
        "mac": "Command+Shift+U"
      },
      "description": "Unpin all pinned tabs"
    }
  },
  "icons": {
    "16": "icon16.png",
    "48": "icon48.png",
    "128": "icon128.png"
  }
}

// popup.js - Handles button clicks in the popup

document.getElementById('closeAll').addEventListener('click', async () => {
  const tabs = await chrome.tabs.query({});

  const confirmed = confirm(
    `⚠️ WARNING ⚠️\n\nYou are about to close ${tabs.length} tab(s).\n\nThis action cannot be undone.\n\nDo you want to continue?`
  );

  if (confirmed) {
    // Get all tabs
    const allTabs = await chrome.tabs.query({});
    const tabIds = allTabs.map(tab => tab.id);

    // Close all tabs
    await chrome.tabs.remove(tabIds);
  }
});

document.getElementById('unpinAll').addEventListener('click', async () => {
  const pinnedTabs = await chrome.tabs.query({ pinned: true });

  if (pinnedTabs.length === 0) {
    alert('No pinned tabs found!');
    return;
  }

  const confirmed = confirm(
    `Found ${pinnedTabs.length} pinned tab(s).\n\nDo you want to unpin them all?`
  );

  if (confirmed) {
    for (const tab of pinnedTabs) {
      await chrome.tabs.update(tab.id, { pinned: false });
    }
    alert(`✅ Successfully unpinned ${pinnedTabs.length} tab(s)!`);
  }
});

document.getElementById('closeExcept').addEventListener('click', async () => {
  const currentTab = await chrome.tabs.query({ active: true, currentWindow: true });
  const allTabs = await chrome.tabs.query({ currentWindow: true });

  const tabsToClose = allTabs.filter(tab => tab.id !== currentTab[0].id);

  if (tabsToClose.length === 0) {
    alert('No other tabs to close!');
    return;
  }

  const confirmed = confirm(
    `⚠️ Close ${tabsToClose.length} tab(s)?\n\nThe current tab will remain open.`
  );

  if (confirmed) {
    const tabIds = tabsToClose.map(tab => tab.id);
    await chrome.tabs.remove(tabIds);
  }
});

// background.js - Handles keyboard shortcuts

chrome.commands.onCommand.addListener(async (command) => {
  if (command === 'close-all-tabs') {
    const tabs = await chrome.tabs.query({});

    // Create a notification-style confirmation using a new tab
    const confirmTab = await chrome.tabs.create({
      url: chrome.runtime.getURL('confirm.html') + '?action=closeAll&count=' + tabs.length,
      active: true
    });
  }

  if (command === 'unpin-all-tabs') {
    const pinnedTabs = await chrome.tabs.query({ pinned: true });

    if (pinnedTabs.length === 0) {
      return;
    }

    const confirmTab = await chrome.tabs.create({
      url: chrome.runtime.getURL('confirm.html') + '?action=unpinAll&count=' + pinnedTabs.length,
      active: true
    });
  }
});

// Listen for messages from confirm page
chrome.runtime.onMessage.addListener(async (message, sender, sendResponse) => {
  if (message.action === 'closeAllConfirmed') {
    const allTabs = await chrome.tabs.query({});
    const tabIds = allTabs.map(tab => tab.id);
    await chrome.tabs.remove(tabIds);
  }

  if (message.action === 'unpinAllConfirmed') {
    const pinnedTabs = await chrome.tabs.query({ pinned: true });
    for (const tab of pinnedTabs) {
      await chrome.tabs.update(tab.id, { pinned: false });
    }
    // Close the confirm tab
    if (sender.tab) {
      chrome.tabs.remove(sender.tab.id);
    }
  }

  if (message.action === 'cancelAction') {
    // Close the confirm tab
    if (sender.tab) {
      chrome.tabs.remove(sender.tab.id);
    }
  }
});

